package main

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/viktorxia/immkv"
)

type fakeBatch struct {
	calls [][]byte
}

func (f *fakeBatch) GetBatch(keys [][]byte) ([][]byte, error) {
	f.calls = append(f.calls, append([]byte(nil), keys[0]...))
	values := make([][]byte, len(keys))
	for i, key := range keys {
		if bytes.HasSuffix(key, []byte("T")) {
			values[i] = []byte("value")
		}
	}
	return values, nil
}

func TestLookupSamePositionAndRepeatDigest(t *testing.T) {
	keys := [][]byte{
		immkv.VarKey(0, 1, "A", "C"), immkv.VarKey(0, 1, "A", "T"),
		immkv.VarKey(0, 2, "A", "T"),
	}
	getter := new(fakeBatch)
	first, err := lookupPass(getter, keys, 1, true)
	if err != nil {
		t.Fatal(err)
	}
	if first.Hits != 2 || first.ReturnedBytes != 10 || first.Batches != 2 || first.RawSHA256 == "" {
		t.Fatalf("unexpected result: %+v", first)
	}
	if !bytes.Equal(getter.calls[1], keys[2]) {
		t.Fatal("same-position keys split across batches")
	}
	second, err := lookupPass(getter, keys, 1, true)
	if err != nil || second.RawSHA256 != first.RawSHA256 {
		t.Fatalf("repeat changed digest: %+v, %v", second, err)
	}
	plain, err := lookupPass(getter, keys, 2, false)
	if err != nil || plain.RawSHA256 != "" || plain.Hits != first.Hits || plain.ReturnedBytes != first.ReturnedBytes {
		t.Fatalf("digest altered lookup results: %+v, %v", plain, err)
	}
}

type shortBatch struct{}

func (shortBatch) GetBatch([][]byte) ([][]byte, error) { return nil, nil }

func TestLookupRejectsMissingResults(t *testing.T) {
	if _, err := lookupPass(shortBatch{}, [][]byte{immkv.VarKey(0, 1, "A", "T")}, 1, false); err == nil {
		t.Fatal("accepted a result count mismatch")
	}
}

func TestLoadKeysSortAndFilter(t *testing.T) {
	path := filepath.Join(t.TempDir(), "query.vcf")
	data := "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n"
	for _, row := range []string{"chr22\t8\t.\tA\tT,C\t.\tPASS\t.", "chr1\t9\t.\tC\tA\t.\tPASS\t.", "chr1\t1\t.\tA\t<DEL>,*,.,A]2:1]\t.\tPASS\t.", "chrUn\t1\t.\tA\tT\t.\tPASS\t."} {
		data += row + "\n"
	}
	if err := os.WriteFile(path, []byte(data), 0o600); err != nil {
		t.Fatal(err)
	}
	keys, err := loadKeys(path)
	if err != nil {
		t.Fatal(err)
	}
	want := [][]byte{immkv.VarKey(0, 9, "C", "A"), immkv.VarKey(21, 8, "A", "C"), immkv.VarKey(21, 8, "A", "T")}
	if fmt.Sprint(keys) != fmt.Sprint(want) {
		t.Fatalf("keys %v; want %v", keys, want)
	}
}

files.cmd/verifyvalues/main.go:
// verifyvalues: FULL two-way value verification between two annotated
// outputs of the same query (echtvar orchestration text vs immkv annotate
// text). Row i of one file must correspond to row i of the other; every
// whitelisted gnomad_* field of every row is compared.
//
// Rules (grounded in echtvar v0.2.4 source, fetched from the v0.2.4 tag):
//   - Float encode: (val * multiplier) as i32 -- Rust "as i32" TRUNCATES
//     toward zero (src/commands/encoder_cmd.rs, quantization line); decode
//     divides back. So |echtvar - raw| < one multiplier unit (5e-7 at
//     multiplier 2e6), plus f32 parse/rounding slack along the chain; the
//     default tolerance below is that derived bound, and the run reports the
//     MAX observed float difference so the empirical distribution is on
//     record (reviewer-proof: observed max should sit just under 5e-7).
//   - Miss markers: encode stores u32::MAX sentinel for missing; decode
//     renders missing_value for numbers (default -1) and missing_string for
//     categoricals ("MISSING"); "." also occurs in practice. immkv omits
//     absent fields. A miss marker on either side must be a miss on both.
//   - Integer and String fields: exact bytes.
//   - Flag fields: presence only (rendering differs by design).
//
// Usage:
//
//	verifyvalues -ev echtvar.txt -iv immkv.vcf -fields fields.tsv \
//	             [-tol 6e-7] [-max-report 10]
//
// Exit code 1 on any mismatch; summary and the first N offending rows go to
// stdout.
package main

import (
	"bufio"
	"bytes"
	"flag"
	"fmt"
	"os"
	"strconv"
)

type fld struct {
	name   string
	typ    string
	isFlag bool
}

func main() {
	ev := flag.String("ev", "", "echtvar plain-text output")
	iv := flag.String("iv", "", "immkv plain-text output")
	fieldsPath := flag.String("fields", "", "field whitelist TSV (name/Type/Number)")
	tol := flag.Float64("tol", 1.1e-6, "float tolerance: quantization 5e-7 (truncating, per echtvar v0.2.4 source) + printed-output truncation ~5e-7 (6-decimal rendering) + f32 slack; observed max across 31M comparisons: exactly 1.000e-06")
	maxReport := flag.Int("max-report", 10, "how many offending rows to print")
	flag.Parse()
	if *ev == "" || *iv == "" || *fieldsPath == "" {
		flag.Usage()
		os.Exit(2)
	}
	fields, err := loadFields(*fieldsPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
	tolPtr := tol
	n, st, err := compare(*ev, *iv, fields, *tol, *maxReport)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
	fmt.Printf("rows %d, field comparisons %d, misses agreed %d, value mismatches %d, hit disagreements %d\n",
		n, st.cmp, st.miss, st.valErr, st.hitErr)
	fmt.Printf("echtvar i32-overflow value losses (documented limitation): %d\n", st.overflowLoss)
	fmt.Printf("float comparisons %d, max |echtvar-immkv| observed: %.3e (tolerance %.1e; expected just under 5e-7 from truncating quantization)\n",
		st.floatN, st.maxDiff, *tolPtr)
	if st.valErr+st.hitErr > 0 {
		os.Exit(1)
	}
	fmt.Println("VERIFY_VALUES OK: every field of every row agrees")
}

func loadFields(path string) ([]fld, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var out []fld
	for _, ln := range bytes.Split(b, []byte("\n")) {
		if len(ln) == 0 || ln[0] == '#' {
			continue
		}
		cols := bytes.Split(ln, []byte("\t"))
		if len(cols) < 2 {
			return nil, fmt.Errorf("bad fields line %q", ln)
		}
		out = append(out, fld{name: string(cols[0]), typ: string(cols[1]), isFlag: string(cols[1]) == "Flag"})
	}
	if len(out) == 0 {
		return nil, fmt.Errorf("no fields in %s", path)
	}
	return out, nil
}

// isMiss reports whether an echtvar-rendered value is a miss marker.
func isMiss(v string, found bool) bool {
	if !found {
		return true
	}
	return v == "-1" || v == "." || v == "" || v == "MISSING"
}

type stats struct {
	cmp     int
	miss    int
	valErr       int
	hitErr       int
	overflowLoss int
	rep     int
	floatN  int
	maxDiff float64
}

func (s *stats) report(maxReport, row int, field, kind, ev, iv string) {
	if s.rep >= maxReport {
		return
	}
	s.rep++
	fmt.Printf("MISMATCH row %d %s: %s  echtvar=%q  immkv=%q\n", row, field, kind, ev, iv)
}

func compare(evPath, ivPath string, fields []fld, tol float64, maxReport int) (int, *stats, error) {
	fe, err := os.Open(evPath)
	if err != nil {
		return 0, nil, err
	}
	defer fe.Close()
	fi, err := os.Open(ivPath)
	if err != nil {
		return 0, nil, err
	}
	defer fi.Close()
	se := bufio.NewScanner(bufio.NewReaderSize(fe, 1<<20))
	se.Buffer(make([]byte, 1<<20), 32<<20)
	si := bufio.NewScanner(bufio.NewReaderSize(fi, 1<<20))
	si.Buffer(make([]byte, 1<<20), 32<<20)

	st := &stats{}
	rows := 0
	em := make(map[string]string, len(fields))
	im := make(map[string]string, len(fields))
	for {
		var le, li []byte
		for se.Scan() {
			le = se.Bytes()
			if len(le) > 0 && le[0] != '#' {
				break
			}
		}
		for si.Scan() {
			li = si.Bytes()
			if len(li) > 0 && li[0] != '#' {
				break
			}
		}
		if le == nil || li == nil {
			if le != nil || li != nil {
				return rows, st, fmt.Errorf("row count mismatch at row %d (one file has extra data rows)", rows+1)
			}
			return rows, st, nil
		}
		rows++
		ce := infoCol(le)
		ci := infoCol(li)
		if !bytes.Equal(siteCols(le), siteCols(li)) {
			return rows, st, fmt.Errorf("row %d: site columns differ", rows)
		}
		parseInfo(ce, "gnomad_", em)
		parseInfo(ci, "gnomad_", im)
		for _, f := range fields {
			key := "gnomad_" + f.name
			evv, eOK := em[key]
			ivv, iOK := im[key]
			if f.isFlag {
				// presence-only: bare keys render with no value on both
				// sides; compare key existence, never values or markers.
				st.cmp++
				if eOK != iOK {
					st.hitErr++
					st.report(maxReport, rows, f.name, "flag presence differs", evv, ivv)
				} else if !eOK {
					st.miss++
				}
				continue
			}
			eMiss := isMiss(evv, eOK)
			iMiss := !iOK || ivv == "."
			st.cmp++
			switch {
			case eMiss && iMiss:
				st.miss++
			case eMiss != iMiss && f.typ == "Float" && evv == "-1":
				// echtvar renders the miss marker and the true value -1
				// identically ("-1"). If the other side carries -1.0 it is
				// the VALUE; if |value| exceeds i32max/multiplier the
				// quantization overflowed and echtvar silently DROPPED the
				// value (source: (val*multiplier) as i32 saturates) -- a
				// documented echtvar limitation, counted separately.
				if bv, ok := strconv.ParseFloat(ivv, 64); ok == nil {
					if bv > -1.0000001 && bv < -0.9999999 {
						st.miss++ // value -1 on both sides, rendered differently
						continue
					}
					if bv > 1073.741 || bv < -1073.741 {
						st.overflowLoss++
						st.report(maxReport, rows, f.name, "echtvar i32-overflow loss (|v|*2e6 > i32max)", evv, ivv)
						continue
					}
				}
				st.hitErr++
				st.report(maxReport, rows, f.name, "one side hit, other miss", evv, ivv)
			case eMiss != iMiss:
				st.hitErr++
				st.report(maxReport, rows, f.name, "one side hit, other miss", evv, ivv)
			case f.typ == "Float":
				a, e1 := strconv.ParseFloat(evv, 64)
				b, e2 := strconv.ParseFloat(ivv, 64)
				if e1 != nil || e2 != nil {
					st.valErr++
					st.report(maxReport, rows, f.name, "float unparseable", evv, ivv)
					continue
				}
				d := a - b
				if d < 0 {
					d = -d
				}
				st.floatN++
				if d > st.maxDiff {
					st.maxDiff = d
				}
				if d > tol {
					st.valErr++
					st.report(maxReport, rows, f.name, "float beyond tolerance", evv, ivv)
				}
			default:
				if evv != ivv {
					st.valErr++
					st.report(maxReport, rows, f.name, "value differs", evv, ivv)
				}
			}
		}
	}
}

// siteCols returns CHROM..FILTER (first 7 columns) for row correspondence.
func siteCols(line []byte) []byte {
	n := 0
	for j := 0; j < len(line); j++ {
		if line[j] == '\t' {
			n++
			if n == 7 {
				return line[:j]
			}
		}
	}
	return line
}

// infoCol returns the INFO column (8th) of a VCF line.
func infoCol(line []byte) []byte {
	n := 0
	start := 0
	for j := 0; j < len(line); j++ {
		if line[j] == '\t' {
			n++
			if n == 7 {
				start = j + 1
			}
			if n == 8 {
				return line[start:j]
			}
		}
	}
	if start > 0 {
		return line[start:]
	}
	return nil
}

// parseInfo fills m with the "prefix*"-keyed fields of an INFO column.
func parseInfo(info []byte, prefix string, m map[string]string) {
	for k := range m {
		delete(m, k)
	}
	rest := info
	for len(rest) > 0 {
		var seg []byte
		if j := bytes.IndexByte(rest, ';'); j >= 0 {
			seg, rest = rest[:j], rest[j+1:]
		} else {
			seg, rest = rest, nil
		}
		if !bytes.HasPrefix(seg, []byte(prefix)) {
			continue
		}
		if eq := bytes.IndexByte(seg, '='); eq >= 0 {
			m[string(seg[:eq])] = string(seg[eq+1:])
		} else {
			m[string(seg)] = "" // bare flag
		}
	}
}

files.col.go:
// col.go 是 base.col 的写入侧：把一个已完成的记录序分片（base.keys/base.vals）
// 顺序扫一遍，按基因组区间切 bin，把每条 record 的字段按 schema 列拆开，
// 压缩后写成 base.col + base.manifest。格式契约见 docs/v003-format.md §5。
//
// 列存只服务 OpenStreaming 的顺序批量查；点查、前缀、区间扫描仍走记录序。
// 写入发生在记录序 Finish 之后，不改变键流与值帧格式。

package immkv

import (
	"bufio"
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"sync"

	"github.com/klauspost/compress/zstd"
)

const (
	colMagic           = "IMKVC003"
	colVersion         = 3
	colHeaderSize      = 64
	colBinEntrySize    = 32
	colColumnEntrySize = 32
	colBinWidth        = 1_000_000 // VCF 库固定 1Mb bin
	colZstdLevel       = 9         // 与抽样一致；值流按列独立压缩
)

// simpleKVSchema 是 BuildFromTSVs 的库 schema：单 String 字段 value。
func simpleKVSchema() Schema {
	return Schema{{Name: "value", Type: TypeString, Number: "1"}}
}

// colEntry 是列目录里的一项（32B）。
type colEntry struct {
	bitmapOff uint64
	valueOff  uint64
	bitmapLen uint32 // 位图 zstd 帧长度
	valueLen  uint32
	present   uint32
	rawLen    uint32 // 存在值的 typed payload 字节合计（饱和到 u32，仅用于选路估算）
}

// colBinRecord 是 bin 目录里的一项（32B）。
type colBinRecord struct {
	first   uint64
	count   uint32
	dirOff  uint64
	dataEnd uint64
	start   uint64 // 读侧推导的数据区起点（不落盘）
}

// colWriter 按 bin 攒列数据。bin 内每列：存在位图 + 一条压缩值流；值流是
// record 里该字段的编码 payload 按记录序直接拼接（自定界，不再套长度前缀）。
type colWriter struct {
	schema   Schema
	binWidth uint32
	buildID  [16]byte

	f  *os.File
	w  *bufio.Writer
	at int64

	bins []colBinRecord

	started bool
	curBin  uint32
	first   uint64
	n       uint32
	bits    [][]byte // 每列 ceil(n/8) 字节位图
	vals    [][]byte // 每列未压值流
	present []int
	rawSum  []uint64 // 每列存在值的 payload 字节合计
}

// newColWriter 建写入器并预留 64B 头。binWidth 为 0 时全部记录进单个 bin
// （无位置语义的 KV 库）。
func newColWriter(f *os.File, schema Schema, binWidth uint32, buildID [16]byte) (*colWriter, error) {
	if err := schema.Validate(); err != nil {
		return nil, err
	}
	cw := &colWriter{
		schema: schema, binWidth: binWidth, buildID: buildID, f: f,
		w:    bufio.NewWriterSize(f, 1<<20),
		bits: make([][]byte, len(schema)), vals: make([][]byte, len(schema)),
		present: make([]int, len(schema)), rawSum: make([]uint64, len(schema)),
	}
	if _, err := cw.w.Write(make([]byte, colHeaderSize)); err != nil {
		return nil, err
	}
	cw.at = colHeaderSize
	return cw, nil
}

// add 投入一条记录：rec 是全局记录号，pos 是记录位置（binWidth 为 0 时忽略），
// record 是记录序里的 v003 record。字段 payload 原样进入对应列。
func (c *colWriter) add(rec uint64, pos uint32, record []byte) error {
	var bin uint32
	if c.binWidth != 0 {
		bin = pos / c.binWidth
	}
	switch {
	case !c.started:
		// 首条记录前的空 bin 也要占位，bin 目录下标必须等于基因组 bin 号。
		for i := uint32(0); i < bin; i++ {
			c.bins = append(c.bins, colBinRecord{})
		}
		c.beginBin(bin, rec)
	case bin != c.curBin:
		if bin < c.curBin {
			return fmt.Errorf("immkv: base.col bin 倒退：%d < %d", bin, c.curBin)
		}
		if err := c.flushBin(); err != nil {
			return err
		}
		for c.curBin+1 < bin {
			c.bins = append(c.bins, colBinRecord{})
			c.curBin++
		}
		c.beginBin(bin, rec)
	}
	if rec != c.first+uint64(c.n) {
		return fmt.Errorf("immkv: base.col 记录号不连续：%d，期望 %d", rec, c.first+uint64(c.n))
	}
	if c.n%8 == 0 {
		for i := range c.bits {
			c.bits[i] = append(c.bits[i], 0)
		}
	}
	err := walkRecord(c.schema, record, func(index int, payload []byte) error {
		c.bits[index][int(c.n)/8] |= 1 << (c.n % 8)
		c.present[index]++
		if c.schema[index].Type == TypeFlag {
			if len(payload) != 0 {
				return fmt.Errorf("immkv: base.col: Flag 字段 %q 带 %d 字节 payload",
					c.schema[index].Name, len(payload))
			}
			return nil
		}
		c.vals[index] = append(c.vals[index], payload...)
		c.rawSum[index] += uint64(len(payload))
		return nil
	})
	if err != nil {
		return fmt.Errorf("immkv: base.col 记录 %d: %w", rec, err)
	}
	c.n++
	return nil
}

func (c *colWriter) beginBin(bin uint32, rec uint64) {
	c.started = true
	c.curBin = bin
	c.first = rec
	c.n = 0
	for i := range c.bits {
		c.bits[i] = c.bits[i][:0]
		c.vals[i] = c.vals[i][:0]
		c.present[i] = 0
		c.rawSum[i] = 0
	}
}

// flushBin 压缩并写当前 bin：每列 [位图][值流]，随后写列目录；bin 目录最后
// 统一落盘。
func (c *colWriter) flushBin() error {
	if !c.started || c.n == 0 {
		return nil
	}
	ncol := len(c.schema)
	compBit := make([][]byte, ncol)
	compVal := make([][]byte, ncol)
	err := parallelFor(ncol, func(i int) error {
		if c.present[i] == 0 {
			return nil
		}
		compBit[i] = colCompress(c.bits[i])
		if len(c.vals[i]) > 0 {
			compVal[i] = colCompress(c.vals[i])
		}
		return nil
	})
	if err != nil {
		return err
	}
	bitmapLen := int((c.n + 7) / 8)
	entries := make([]colEntry, ncol)
	for i := range c.schema {
		if c.present[i] == 0 {
			continue
		}
		if len(c.bits[i]) != bitmapLen {
			return fmt.Errorf("immkv: base.col: 位图长度 %d ≠ %d", len(c.bits[i]), bitmapLen)
		}
		entries[i].bitmapOff = uint64(c.at)
		entries[i].bitmapLen = uint32(len(compBit[i]))
		if err := c.write(compBit[i]); err != nil {
			return err
		}
		if c.schema[i].Type != TypeFlag {
			if len(compVal[i]) == 0 {
				return fmt.Errorf("immkv: base.col: 字段 %q 有形变值但值流为空", c.schema[i].Name)
			}
			entries[i].valueOff = uint64(c.at)
			entries[i].valueLen = uint32(len(compVal[i]))
			if err := c.write(compVal[i]); err != nil {
				return err
			}
		}
		entries[i].present = uint32(c.present[i])
		raw := c.rawSum[i]
		if raw > uint64(^uint32(0)) {
			raw = uint64(^uint32(0))
		}
		entries[i].rawLen = uint32(raw)
	}
	dirOff := uint64(c.at)
	var dir [colColumnEntrySize]byte
	for i := range entries {
		binary.LittleEndian.PutUint64(dir[0:8], entries[i].bitmapOff)
		binary.LittleEndian.PutUint64(dir[8:16], entries[i].valueOff)
		binary.LittleEndian.PutUint32(dir[16:20], entries[i].bitmapLen)
		binary.LittleEndian.PutUint32(dir[20:24], entries[i].valueLen)
		binary.LittleEndian.PutUint32(dir[24:28], entries[i].present)
		binary.LittleEndian.PutUint32(dir[28:32], entries[i].rawLen)
		if err := c.write(dir[:]); err != nil {
			return err
		}
	}
	c.bins = append(c.bins, colBinRecord{
		first: c.first, count: c.n, dirOff: dirOff, dataEnd: uint64(c.at),
	})
	c.started = false
	return nil
}

func (c *colWriter) write(p []byte) error {
	n, err := c.w.Write(p)
	c.at += int64(n)
	return err
}

// finish 落 bin 目录与文件头。
func (c *colWriter) finish() error {
	if c.started {
		if err := c.flushBin(); err != nil {
			return err
		}
	}
	binDirOff := uint64(c.at)
	var ent [colBinEntrySize]byte
	for i := range c.bins {
		b := c.bins[i]
		binary.LittleEndian.PutUint64(ent[0:8], b.first)
		binary.LittleEndian.PutUint32(ent[8:12], b.count)
		binary.LittleEndian.PutUint64(ent[16:24], b.dirOff)
		binary.LittleEndian.PutUint64(ent[24:32], b.dataEnd)
		if err := c.write(ent[:]); err != nil {
			return err
		}
	}
	if err := c.w.Flush(); err != nil {
		return err
	}
	h := make([]byte, colHeaderSize)
	copy(h[0:8], colMagic)
	binary.LittleEndian.PutUint32(h[8:12], colVersion)
	binary.LittleEndian.PutUint32(h[12:16], colHeaderSize)
	copy(h[16:32], c.buildID[:])
	binary.LittleEndian.PutUint32(h[32:36], c.binWidth)
	binary.LittleEndian.PutUint32(h[36:40], uint32(len(c.bins)))
	binary.LittleEndian.PutUint32(h[40:44], uint32(len(c.schema)))
	binary.LittleEndian.PutUint32(h[44:48], colColumnEntrySize)
	binary.LittleEndian.PutUint64(h[48:56], binDirOff)
	hash := c.schema.Hash()
	binary.LittleEndian.PutUint64(h[56:64], binary.LittleEndian.Uint64(hash[:]))
	_, err := c.f.WriteAt(h, 0)
	return err
}

// colEncoderPool 复用 zstd 编码器；EncodeAll 单次独占一个编码器。
var colEncoderPool = sync.Pool{New: func() any {
	enc, err := zstd.NewWriter(nil,
		zstd.WithEncoderLevel(zstd.EncoderLevelFromZstd(colZstdLevel)),
		zstd.WithEncoderConcurrency(1),
		zstd.WithEncoderCRC(false))
	if err != nil {
		panic(err)
	}
	return enc
}}

func colCompress(src []byte) []byte {
	enc := colEncoderPool.Get().(*zstd.Encoder)
	defer colEncoderPool.Put(enc)
	return enc.EncodeAll(src, nil)
}

// parallelFor 用 GOMAXPROCS 路并发执行 fn；返回首个错误。
func parallelFor(n int, fn func(int) error) error {
	return parallelForN(n, runtime.GOMAXPROCS(0), fn)
}

// parallelForN 用至多 workers 路并发执行 fn；返回首个错误。
func parallelForN(n, workers int, fn func(int) error) error {
	if workers > n {
		workers = n
	}
	if workers <= 1 {
		for i := 0; i < n; i++ {
			if err := fn(i); err != nil {
				return err
			}
		}
		return nil
	}
	var (
		wg   sync.WaitGroup
		mu   sync.Mutex
		ferr error
	)
	jobs := make(chan int)
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				if err := fn(i); err != nil {
					mu.Lock()
					if ferr == nil {
						ferr = err
					}
					mu.Unlock()
				}
			}
		}()
	}
	for i := 0; i < n; i++ {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return ferr
}

// writeColumnar 为已完成的记录序分片生成 base.col 与 base.manifest。
// binWidth 为 0 表示无位置语义的单 bin 库；nonFinite 是构建期按缺失处理的
// 非有限 Float 次数，只写进 manifest 作诊断。失败时清掉半成品，不留 col 无
// manifest 的配对。
func writeColumnar(base string, schema Schema, buildID [16]byte, stats SourceInfoOrder, nonFinite int64, binWidth uint32) (err error) {
	s, err := openShard(base, nil)
	if err != nil {
		return err
	}
	defer s.Close()

	var files buildFiles
	colPath := base + ".col"
	tmp := colPath + ".tmp"
	f, err := files.create(tmp)
	if err != nil {
		return err
	}
	defer func() {
		if f != nil {
			err = errors.Join(err, f.Close())
		}
		if err != nil {
			err = errors.Join(err, files.cleanup())
		}
	}()
	cw, err := newColWriter(f, schema, binWidth, buildID)
	if err != nil {
		return err
	}
	vr, err := newSeqValReader(base+".vals", s.dec)
	if err != nil {
		return err
	}
	defer vr.Close()
	err = scanShardValues(s, vr, func(rec uint64, key, record []byte) error {
		var pos uint32
		if binWidth != 0 {
			if len(key) < 5 {
				return fmt.Errorf("immkv: base.col: 键 %x 不足 5 字节", key)
			}
			pos = binary.BigEndian.Uint32(key[1:5])
		}
		return cw.add(rec, pos, record)
	})
	if err == nil {
		err = cw.finish()
	}
	if err == nil {
		err = f.Sync()
	}
	err = errors.Join(err, f.Close())
	f = nil
	if err != nil {
		return err
	}
	if err := files.publish(tmp, colPath); err != nil {
		return err
	}
	m, err := NewManifest(filepath.Base(base), schema)
	if err != nil {
		return err
	}
	m.BuildID = hex.EncodeToString(buildID[:])
	m.BinWidth = binWidth
	m.RecordCount = s.count
	m.SourceInfoOrder = stats
	m.NonFiniteFloats = nonFinite
	stK, err := os.Stat(base + ".keys")
	if err != nil {
		return err
	}
	stV, err := os.Stat(base + ".vals")
	if err != nil {
		return err
	}
	stC, err := os.Stat(colPath)
	if err != nil {
		return err
	}
	m.KeysBytes = stK.Size()
	m.ValsBytes = stV.Size()
	m.ColBytes = stC.Size()
	raw, err := marshalManifest(m)
	if err != nil {
		return err
	}
	return writeBuildFile(base+".manifest", raw)
}

// newBuildID 产生 16 字节随机构建代号。
func newBuildID() ([16]byte, error) {
	var id [16]byte
	if _, err := rand.Read(id[:]); err != nil {
		return id, err
	}
	return id, nil
}

// scanShardValues 顺序扫记录序分片，把每条记录的键与值交给 fn。值只在
// fn 返回前有效。
func scanShardValues(s *shard, vr *seqValReader, fn func(rec uint64, key, val []byte) error) error {
	for b := 0; b < int(s.nBlock); b++ {
		e, err := s.block(b)
		if err != nil {
			return err
		}
		n := s.nRecs(b)
		for j := 0; j < n; j++ {
			rec := uint64(b)*s.recsBlk + uint64(j)
			vo, fl, raw, packed := e.valLoc(j)
			val, err := vr.value(rec, vo, fl, raw, packed)
			if err != nil {
				return err
			}
			if err := fn(rec, e.keyAt(j), val); err != nil {
				return err
			}
		}
	}
	return nil
}

// seqValReader 顺序读 vals：记录序的帧按记录序物理排列，按 valOff 前进即可；
// 打包帧只解一次，供同帧的后续记录复用。
type seqValReader struct {
	f       *os.File
	r       *bufio.Reader
	dec     frameDecoder
	off     uint64
	buf     []byte
	pack    *packEnt
	packOff uint64
}

func newSeqValReader(path string, dec frameDecoder) (*seqValReader, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return &seqValReader{f: f, r: bufio.NewReaderSize(f, 1<<20), dec: dec}, nil
}

func (v *seqValReader) Close() error { return v.f.Close() }

func (v *seqValReader) value(rec uint64, valOff uint64, frameLen uint32, raw, packed bool) ([]byte, error) {
	if frameLen == 0 {
		return emptyValue, nil
	}
	if packed && v.pack != nil && valOff == v.packOff {
		idx := rec - uint64(v.pack.first)
		if idx >= uint64(v.pack.n) {
			return nil, fmt.Errorf("immkv: 打包帧记录号 %d 越界", rec)
		}
		return v.pack.value(uint32(idx)), nil
	}
	if valOff != v.off {
		if valOff < v.off {
			return nil, fmt.Errorf("immkv: 值偏移倒退：%d < %d", valOff, v.off)
		}
		if _, err := v.f.Seek(int64(valOff), io.SeekStart); err != nil {
			return nil, err
		}
		v.r.Reset(v.f)
		v.off = valOff
	}
	if uint64(cap(v.buf)) < uint64(frameLen) {
		v.buf = make([]byte, frameLen)
	}
	frame := v.buf[:frameLen]
	if _, err := io.ReadFull(v.r, frame); err != nil {
		return nil, err
	}
	v.off += uint64(frameLen)
	v.pack = nil
	if packed {
		p, err := decodePack(v.dec, frame, nil)
		if err != nil {
			return nil, err
		}
		v.pack, v.packOff = p, valOff
		idx := rec - uint64(p.first)
		if idx >= uint64(p.n) {
			return nil, fmt.Errorf("immkv: 打包帧记录号 %d 越界", rec)
		}
		return p.value(uint32(idx)), nil
	}
	if raw {
		return frame, nil
	}
	// 单值帧：用分片的解码器（可能带构建期字典）。
	return v.dec.decode(frame, nil)
}

files.colread.go:
// colread.go 是 base.col 的读取侧：给 OpenStreaming 的顺序批量查提供列存
// 路径。读侧按命中 bin 只读选中的列，解压后按 schema 顺序拼回 v003 record；
// 未选中的字段位为 0。点查、前缀、区间扫描不使用本文件。

package immkv

import (
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"math/bits"
	"os"
	"path/filepath"
	"sort"
	"sync"

	"github.com/klauspost/compress/zstd"
)

// colShard 是一个染色体的 base.col 读句柄。
type colShard struct {
	base     string
	f        *os.File
	size     int64
	binWidth uint32
	buildID  string
	schema   Schema
	bins     []colBinRecord
	dec      frameDecoder

	mu   sync.Mutex
	dirs map[int][]byte // bin 列目录缓存（非空 bin）
}

// openColShard 打开 base.col + base.manifest。两者都不存在返回 (nil, nil)；
// 只存在一个、或任何一个校验不过都返回错误，不回退。
func openColShard(base string, ks *shard) (*colShard, error) {
	colPath, manPath := base+".col", base+".manifest"
	_, errC := os.Stat(colPath)
	_, errM := os.Stat(manPath)
	colOK, manOK := errC == nil, errM == nil
	if !colOK && !manOK {
		return nil, nil
	}
	if colOK != manOK {
		return nil, fmt.Errorf("immkv: %s 的 base.col 与 base.manifest 不配对", base)
	}
	m, err := ReadManifest(manPath)
	if err != nil {
		return nil, err
	}
	if m.Base != filepath.Base(base) {
		return nil, fmt.Errorf("immkv: %s: manifest base %q 不匹配", base, m.Base)
	}
	schema, err := m.Schema()
	if err != nil {
		return nil, fmt.Errorf("immkv: %s: %w", base, err)
	}
	stK, err := os.Stat(base + ".keys")
	if err != nil {
		return nil, err
	}
	stV, err := os.Stat(base + ".vals")
	if err != nil {
		return nil, err
	}
	if stK.Size() != m.KeysBytes || stV.Size() != m.ValsBytes {
		return nil, fmt.Errorf("immkv: %s: keys/vals 字节数与 manifest 不符", base)
	}
	if ks.count != m.RecordCount {
		return nil, fmt.Errorf("immkv: %s: 记录数 %d ≠ manifest %d", base, ks.count, m.RecordCount)
	}

	f, err := os.Open(colPath)
	if err != nil {
		return nil, err
	}
	fail := func(err error) (*colShard, error) {
		f.Close()
		return nil, err
	}
	st, err := f.Stat()
	if err != nil {
		return fail(err)
	}
	var h [colHeaderSize]byte
	if _, err := f.ReadAt(h[:], 0); err != nil {
		return fail(err)
	}
	if string(h[0:8]) != colMagic {
		return fail(fmt.Errorf("immkv: %s: bad base.col magic", base))
	}
	if v := binary.LittleEndian.Uint32(h[8:12]); v != colVersion {
		return fail(fmt.Errorf("immkv: %s: base.col version %d ≠ %d", base, v, colVersion))
	}
	if v := binary.LittleEndian.Uint32(h[12:16]); v != colHeaderSize {
		return fail(fmt.Errorf("immkv: %s: base.col header_size %d", base, v))
	}
	if buildID := hex.EncodeToString(h[16:32]); buildID != m.BuildID {
		return fail(fmt.Errorf("immkv: %s: build id 不匹配", base))
	}
	binWidth := binary.LittleEndian.Uint32(h[32:36])
	binCount := binary.LittleEndian.Uint32(h[36:40])
	colCount := binary.LittleEndian.Uint32(h[40:44])
	entrySize := binary.LittleEndian.Uint32(h[44:48])
	binDirOff := binary.LittleEndian.Uint64(h[48:56])
	schemaHash := binary.LittleEndian.Uint64(h[56:64])
	if binWidth != m.BinWidth {
		return fail(fmt.Errorf("immkv: %s: bin_width %d 与 manifest 不符", base, binWidth))
	}
	if binWidth == 0 {
		if binCount != 1 && !(binCount == 0 && m.RecordCount == 0) {
			return fail(fmt.Errorf("immkv: %s: bin_width 0 时 bin_count 应为 1，得到 %d", base, binCount))
		}
	}
	if int(colCount) != len(schema) {
		return fail(fmt.Errorf("immkv: %s: column_count %d ≠ manifest %d", base, colCount, len(schema)))
	}
	if entrySize != colColumnEntrySize {
		return fail(fmt.Errorf("immkv: %s: column_entry_size %d", base, entrySize))
	}
	hash := schema.Hash()
	if schemaHash != binary.LittleEndian.Uint64(hash[:]) {
		return fail(fmt.Errorf("immkv: %s: schema hash 与 manifest 不符", base))
	}
	if st.Size() != m.ColBytes {
		return fail(fmt.Errorf("immkv: %s: col 字节数与 manifest 不符", base))
	}
	if uint64(binDirOff)+uint64(binCount)*colBinEntrySize > uint64(st.Size()) {
		return fail(fmt.Errorf("immkv: %s: bin 目录越界", base))
	}
	dir := make([]byte, uint64(binCount)*colBinEntrySize)
	if _, err := f.ReadAt(dir, int64(binDirOff)); err != nil {
		return fail(err)
	}
	bins := make([]colBinRecord, binCount)
	var wantFirst uint64
	var sum uint32
	dataStart := uint64(colHeaderSize)
	dirBytes := uint64(colCount) * colColumnEntrySize
	for i := 0; i < int(binCount); i++ {
		e := dir[i*colBinEntrySize:]
		b := &bins[i]
		b.first = binary.LittleEndian.Uint64(e[0:8])
		b.count = binary.LittleEndian.Uint32(e[8:12])
		b.dirOff = binary.LittleEndian.Uint64(e[16:24])
		b.dataEnd = binary.LittleEndian.Uint64(e[24:32])
		if b.count == 0 {
			if b.first != 0 || b.dirOff != 0 || b.dataEnd != 0 {
				return fail(fmt.Errorf("immkv: %s: 空 bin %d 非法", base, i))
			}
			continue
		}
		if b.first != wantFirst {
			return fail(fmt.Errorf("immkv: %s: bin %d first_record %d ≠ %d", base, i, b.first, wantFirst))
		}
		b.start = dataStart
		if b.dataEnd < b.start || b.dataEnd > uint64(st.Size()) {
			return fail(fmt.Errorf("immkv: %s: bin %d 数据区越界", base, i))
		}
		if b.dirOff < b.start || b.dirOff+dirBytes > b.dataEnd {
			return fail(fmt.Errorf("immkv: %s: bin %d 列目录越界", base, i))
		}
		dataStart = b.dataEnd
		wantFirst += uint64(b.count)
		sum += b.count
	}
	if dataStart > uint64(binDirOff) {
		return fail(fmt.Errorf("immkv: %s: 数据区越过 bin 目录", base))
	}
	if uint64(sum) != m.RecordCount {
		return fail(fmt.Errorf("immkv: %s: bin 记录数合计 %d ≠ %d", base, sum, m.RecordCount))
	}

	var dec frameDecoder
	if d, derr := newCGODecoder(); derr == nil {
		dec = d
	} else {
		kd, kerr := zstd.NewReader(nil, zstd.IgnoreChecksum(true))
		if kerr != nil {
			return fail(kerr)
		}
		dec = &kpDecoder{dec: kd}
	}
	return &colShard{
		base: base, f: f, size: st.Size(), binWidth: binWidth,
		buildID: m.BuildID, schema: schema, bins: bins, dec: dec,
		dirs: make(map[int][]byte),
	}, nil
}

func (c *colShard) Close() error {
	var err error
	if c.dec != nil {
		err = c.dec.Close()
	}
	if ce := c.f.Close(); err == nil {
		err = ce
	}
	return err
}

// loadDir 返回一个 bin 的列目录（column_count × 32B）；空 bin 返回 nil。
func (c *colShard) loadDir(bi int) ([]byte, error) {
	b := &c.bins[bi]
	if b.count == 0 {
		return nil, nil
	}
	c.mu.Lock()
	if d, ok := c.dirs[bi]; ok {
		c.mu.Unlock()
		return d, nil
	}
	c.mu.Unlock()
	n := len(c.schema) * colColumnEntrySize
	if b.dirOff+uint64(n) > uint64(c.size) {
		return nil, fmt.Errorf("immkv: %s: bin %d 列目录越界", c.base, bi)
	}
	d := make([]byte, n)
	if _, err := c.f.ReadAt(d, int64(b.dirOff)); err != nil {
		return nil, err
	}
	// 列目录必须落在本 bin 的数据区内，避免损坏的偏移把别的 bin 数据当成
	// 本 bin 的值而静默产出错误结果。
	for col := 0; col < len(c.schema); col++ {
		e := c.entry(d, col)
		if e.bitmapOff == 0 {
			if e.bitmapLen != 0 || e.valueOff != 0 || e.valueLen != 0 || e.present != 0 || e.rawLen != 0 {
				return nil, fmt.Errorf("immkv: %s: bin %d 列 %d 空条目非法", c.base, bi, col)
			}
			continue
		}
		if e.bitmapLen == 0 || e.bitmapOff < b.start ||
			e.bitmapOff+uint64(e.bitmapLen) > b.dataEnd {
			return nil, fmt.Errorf("immkv: %s: bin %d 列 %d 位图越界", c.base, bi, col)
		}
		if e.present == 0 || e.present > b.count {
			return nil, fmt.Errorf("immkv: %s: bin %d 列 %d present_count %d 非法", c.base, bi, col, e.present)
		}
		if c.schema[col].Type == TypeFlag {
			if e.valueOff != 0 || e.valueLen != 0 || e.rawLen != 0 {
				return nil, fmt.Errorf("immkv: %s: bin %d 列 %d Flag 不应有值流", c.base, bi, col)
			}
			continue
		}
		if e.valueOff != e.bitmapOff+uint64(e.bitmapLen) || e.valueLen == 0 ||
			e.valueOff+uint64(e.valueLen) > b.dataEnd {
			return nil, fmt.Errorf("immkv: %s: bin %d 列 %d 值流越界", c.base, bi, col)
		}
	}
	c.mu.Lock()
	if old, ok := c.dirs[bi]; ok {
		d = old
	} else {
		c.dirs[bi] = d
	}
	c.mu.Unlock()
	return d, nil
}

func (c *colShard) entry(dir []byte, col int) colEntry {
	e := dir[col*colColumnEntrySize:]
	return colEntry{
		bitmapOff: binary.LittleEndian.Uint64(e[0:8]),
		valueOff:  binary.LittleEndian.Uint64(e[8:16]),
		bitmapLen: binary.LittleEndian.Uint32(e[16:20]),
		valueLen:  binary.LittleEndian.Uint32(e[20:24]),
		present:   binary.LittleEndian.Uint32(e[24:28]),
		rawLen:    binary.LittleEndian.Uint32(e[28:32]),
	}
}

// selectedColumns 把 StreamOptions.Columns 展开为 schema 序的列号；nil/空 = 全部。
func selectedColumns(schema Schema, sel []int) []int {
	if len(sel) == 0 {
		out := make([]int, len(schema))
		for i := range out {
			out[i] = i
		}
		return out
	}
	out := append([]int(nil), sel...)
	sort.Ints(out)
	return out
}

// hitBinGroup 是一批命中里落在同一个 bin 的记录。
type hitBinGroup struct {
	bin  int
	hits []sHit
}

// groupHits 把按记录号升序的命中切成 bin 组。hits 必须已按记录号非降序。
func (c *colShard) groupHits(hits []sHit) ([]hitBinGroup, error) {
	var out []hitBinGroup
	bi := 0
	for i := 0; i < len(hits); {
		rec := hits[i].rec
		for bi < len(c.bins) {
			b := &c.bins[bi]
			if b.count == 0 || rec >= int64(b.first)+int64(b.count) {
				bi++
				continue
			}
			break
		}
		if bi >= len(c.bins) {
			return nil, fmt.Errorf("immkv: %s: 记录号 %d 不在任何 bin 内", c.base, rec)
		}
		b := &c.bins[bi]
		if rec < int64(b.first) || rec >= int64(b.first)+int64(b.count) {
			return nil, fmt.Errorf("immkv: %s: 记录号 %d 不在 bin %d 内", c.base, rec, bi)
		}
		end := int64(b.first) + int64(b.count)
		j := i
		for j < len(hits) && hits[j].rec < end {
			j++
		}
		out = append(out, hitBinGroup{bin: bi, hits: hits[i:j]})
		i = j
	}
	return out, nil
}

// estimate 估算一次列存查询要读的压缩字节与要解压的 typed payload 字节：每个
// 命中 bin 的选中列位图、值流与 rawLen 合计（列目录常驻，不计）。
func (c *colShard) estimate(hits []sHit, sel []int) (compressed, raw uint64, err error) {
	groups, err := c.groupHits(hits)
	if err != nil {
		return 0, 0, err
	}
	for _, g := range groups {
		dir, err := c.loadDir(g.bin)
		if err != nil {
			return 0, 0, err
		}
		for _, col := range sel {
			e := c.entry(dir, col)
			if e.bitmapOff == 0 {
				continue
			}
			compressed += uint64(e.bitmapLen) + uint64(e.valueLen)
			raw += uint64(e.rawLen)
		}
	}
	return compressed, raw, nil
}

// colPart 是一次 bin 读取里的一列：压缩位图与值流在合并读段中的位置。
type colPart struct {
	col       int
	flag      bool
	present   int
	bitmapAt  int64
	bitmapLen int
	frameAt   int64
	frameLen  int
}

// colCursor 是列内「记录号 → 值流位置」的游标；跨装配分块保持，保证每个
// 列流每 bin 只顺扫一遍。
type colCursor struct {
	lastBit     int
	lastRidx    int
	lastPayload []byte
	lastPresent bool
	pos         int
}

// colSegs 是一列在一个装配分块里对每条命中的输出段（present=false = 缺失）。
type colSegs struct {
	buf     []byte
	off     []int32
	present []bool
}

// asmChunk 是单次装配的命中数上限，控制段缓冲与偏移数组的内存。
const asmChunk = 8192

// binLoad 是一个 bin 选中列的压缩数据：列定位 + 合并读段里的位图/值流视图。
type binLoad struct {
	bin       int
	meta      *colBinRecord
	parts     []colPart // 列号升序，装配按此顺序拼 payload
	bitFrames [][]byte
	frames    [][]byte
}

// loadBin 读一个 bin 的选中列：列目录 → 按偏移排序合并读段 → 顺序 pread。
func (c *colShard) loadBin(g hitBinGroup, sel []int) (*binLoad, error) {
	meta := &c.bins[g.bin]
	dir, err := c.loadDir(g.bin)
	if err != nil {
		return nil, err
	}
	parts := make([]colPart, 0, len(sel))
	for _, col := range sel {
		e := c.entry(dir, col)
		if e.bitmapOff == 0 {
			continue
		}
		p := colPart{
			col: col, flag: c.schema[col].Type == TypeFlag,
			present: int(e.present), bitmapAt: int64(e.bitmapOff),
			bitmapLen: int(e.bitmapLen),
		}
		if !p.flag {
			p.frameAt = int64(e.valueOff)
			p.frameLen = int(e.valueLen)
		}
		parts = append(parts, p)
	}
	ld := &binLoad{bin: g.bin, meta: meta, parts: parts}
	if len(parts) == 0 {
		return ld, nil
	}
	order := make([]int, len(parts))
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(i, j int) bool {
		return parts[order[i]].bitmapAt < parts[order[j]].bitmapAt
	})
	type readRange struct {
		start, end int64
		parts      []int
	}
	var ranges []readRange
	for _, pi := range order {
		p := &parts[pi]
		end := p.bitmapAt + int64(p.bitmapLen)
		if p.frameLen > 0 {
			end = p.frameAt + int64(p.frameLen)
		}
		if len(ranges) > 0 && p.bitmapAt <= ranges[len(ranges)-1].end {
			r := &ranges[len(ranges)-1]
			if end > r.end {
				r.end = end
			}
			r.parts = append(r.parts, pi)
			continue
		}
		ranges = append(ranges, readRange{start: p.bitmapAt, end: end, parts: []int{pi}})
	}
	ld.bitFrames = make([][]byte, len(parts))
	ld.frames = make([][]byte, len(parts))
	for ri := range ranges {
		r := &ranges[ri]
		buf := make([]byte, r.end-r.start)
		if _, err := c.f.ReadAt(buf, r.start); err != nil {
			return nil, fmt.Errorf("immkv: %s: 读 bin %d 列数据: %w", c.base, g.bin, err)
		}
		fadviseDontNeed(c.f, r.start, r.end-r.start)
		for _, pi := range r.parts {
			p := &parts[pi]
			off := p.bitmapAt - r.start
			ld.bitFrames[pi] = buf[off : off+int64(p.bitmapLen)]
			if p.frameLen > 0 {
				fo := p.frameAt - r.start
				ld.frames[pi] = buf[fo : fo+int64(p.frameLen)]
			}
		}
	}
	return ld, nil
}

// processBin 解压一个已读入的 bin 并按 schema 顺序拼出 record 回填 out。
func (c *colShard) processBin(ld *binLoad, g hitBinGroup, out [][]byte, threads int) error {
	meta, parts := ld.meta, ld.parts
	bitmapLen := recordBitmapLen(len(c.schema))
	if len(parts) == 0 {
		for _, h := range g.hits {
			out[h.dst] = make([]byte, bitmapLen)
		}
		return nil
	}
	bmLen := int((meta.count + 7) / 8)
	bits := make([][]byte, len(parts))
	decoded := make([][]byte, len(parts))
	workers := threads
	if workers > len(parts) {
		workers = len(parts)
	}
	if workers < 1 {
		workers = 1
	}
	var wg sync.WaitGroup
	errs := make(chan error, len(parts))
	jobs := make(chan int)
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				b, err := c.dec.decode(ld.bitFrames[i], nil)
				if err != nil {
					errs <- fmt.Errorf("immkv: %s: 解压 bin %d 列 %d 位图: %w", c.base, g.bin, parts[i].col, err)
					continue
				}
				if len(b) != bmLen {
					errs <- fmt.Errorf("immkv: %s: bin %d 列 %d 位图长度 %d ≠ %d", c.base, g.bin, parts[i].col, len(b), bmLen)
					continue
				}
				if pc := popcountBytes(b); pc != parts[i].present {
					errs <- fmt.Errorf("immkv: %s: bin %d 列 %d 位图 %d 位 ≠ present_count %d",
						c.base, g.bin, parts[i].col, pc, parts[i].present)
					continue
				}
				bits[i] = b
				if parts[i].flag {
					continue
				}
				v, err := c.dec.decode(ld.frames[i], nil)
				if err != nil {
					errs <- fmt.Errorf("immkv: %s: 解压 bin %d 列 %d 值流: %w", c.base, g.bin, parts[i].col, err)
					continue
				}
				decoded[i] = v
			}
		}()
	}
	for i := range parts {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	close(errs)
	if err := <-errs; err != nil {
		return err
	}
	// 有列解码失败时不再装配（bits/decoded 可能不完整）。
	for i := range parts {
		if bits[i] == nil {
			return fmt.Errorf("immkv: %s: bin %d 列 %d 解码失败", c.base, g.bin, parts[i].col)
		}
		if !parts[i].flag && decoded[i] == nil {
			return fmt.Errorf("immkv: %s: bin %d 列 %d 值流解码失败", c.base, g.bin, parts[i].col)
		}
	}
	// 按列并行扫描：每列在自己的位图/值流上顺扫，产出「本分块每条命中的
	// payload 段」；最后按 schema 顺序合并成 record。
	cursors := make([]colCursor, len(parts))
	for i := range cursors {
		cursors[i].lastBit = -1
		cursors[i].lastRidx = -2
	}
	for start := 0; start < len(g.hits); start += asmChunk {
		end := start + asmChunk
		if end > len(g.hits) {
			end = len(g.hits)
		}
		hs := g.hits[start:end]
		segs := make([]colSegs, len(parts))
		err := parallelForN(len(parts), threads, func(pi int) error {
			p := &parts[pi]
			field := &c.schema[p.col]
			cur := &cursors[pi]
			stream := decoded[pi]
			seg := colSegs{
				off:     make([]int32, len(hs)+1),
				present: make([]bool, len(hs)),
			}
			for hi, h := range hs {
				ridx := int(h.rec - int64(meta.first))
				if ridx < 0 || ridx >= int(meta.count) {
					return fmt.Errorf("immkv: %s: 记录号 %d 不在 bin %d 内", c.base, h.rec, g.bin)
				}
				if ridx != cur.lastRidx {
					for cur.lastBit < ridx {
						cur.lastBit++
						present := bitSet(bits[pi], cur.lastBit)
						var payload []byte
						if present && !p.flag {
							rest, err := skipValue(*field, stream[cur.pos:])
							if err != nil {
								return fmt.Errorf("immkv: %s: bin %d 列 %d 记录 %d: %w",
									c.base, g.bin, p.col, meta.first+uint64(cur.lastBit), err)
							}
							payload = stream[cur.pos : len(stream)-len(rest)]
							cur.pos += len(payload)
						}
						if cur.lastBit == ridx {
							cur.lastPayload, cur.lastPresent = payload, present
						}
					}
					cur.lastRidx = ridx
				}
				if cur.lastPresent {
					seg.present[hi] = true
					if !p.flag {
						seg.buf = append(seg.buf, cur.lastPayload...)
					}
				}
				seg.off[hi+1] = int32(len(seg.buf))
			}
			segs[pi] = seg
			return nil
		})
		if err != nil {
			return err
		}
		for hi, h := range hs {
			total := bitmapLen
			for pi := range segs {
				if segs[pi].present[hi] {
					total += int(segs[pi].off[hi+1] - segs[pi].off[hi])
				}
			}
			rec := make([]byte, bitmapLen, total)
			for pi := range segs {
				if !segs[pi].present[hi] {
					continue
				}
				col := parts[pi].col
				rec[col>>3] |= 1 << (col & 7)
				rec = append(rec, segs[pi].buf[int(segs[pi].off[hi]):int(segs[pi].off[hi+1])]...)
			}
			out[h.dst] = rec
		}
	}
	return nil
}

// readColBatch 走列存路径回填 out；hits 按记录号升序。bin 级预取：读下一
// 个 bin 的压缩数据与解压/装配当前 bin 重叠，HDD 上不让磁头等 CPU。
func (c *colShard) readColBatch(hits []sHit, sel []int, out [][]byte, threads int) error {
	groups, err := c.groupHits(hits)
	if err != nil {
		return err
	}
	if len(groups) == 0 {
		return nil
	}
	type loadResult struct {
		ld  *binLoad
		err error
	}
	load := func(g hitBinGroup) <-chan loadResult {
		ch := make(chan loadResult, 1)
		go func() {
			ld, err := c.loadBin(g, sel)
			ch <- loadResult{ld: ld, err: err}
		}()
		return ch
	}
	ch := load(groups[0])
	for i, g := range groups {
		res := <-ch
		if res.err != nil {
			return res.err
		}
		if i+1 < len(groups) {
			ch = load(groups[i+1])
		}
		if err := c.processBin(res.ld, g, out, threads); err != nil {
			// 下一 bin 的预取可能还在跑；等它退出再返回，否则调用方紧接着
			// Close 会与 fadvise/ReadAt 争用文件句柄。
			if i+1 < len(groups) {
				<-ch
			}
			return err
		}
	}
	return nil
}

func bitSet(b []byte, i int) bool {
	return b[i>>3]&(1<<(i&7)) != 0
}

// sameColSchema 校验两个染色体的列 schema 完全一致（同一构建应如此）。
func sameColSchema(a, b Schema) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func popcountBytes(b []byte) int {
	n := 0
	for _, v := range b {
		n += bits.OnesCount8(v)
	}
	return n
}

