files.immkv.go:
// Package immkv（immutable sorted KV）是独立发布的存储引擎库：
// 构建一次、不可变、排序 KV。每条染色体的数据是两个文件——键流（有序、
// 带稀疏锚点索引）与值文件（每条值独立成帧）——读侧 pread 显式按需读取，
// 不使用 mmap 缺页路径。
//
// 形态：通用排序键值。键是任意字节串，全序按 bytes.Compare；值是任意字节串。
// 适合「构建后只读、多进程共享同一份数据文件、点查/前缀/区间/批量查询」的场景。
//
// 文件布局（base 是公共前缀，如 …/chr1 → chr1.keys + chr1.vals）：
//
//	chr1.keys: [64B 头][微块 ×N][块索引]
//	  微块（64 条记录）：[keyEnds u32×n][lens u32×n][baseValOff u64][键区]
//	                     lens 三标记位：bit31 裸存 / bit30 打包帧 / bit29 同帧
//	  块索引（常驻内存）：[首键 8B 前缀 u64 大端 ×N][块偏移 u64 ×N]
//	chr1.vals: [64B 头][字典（每值模式）][值帧 ×N]
//
// 值帧三种：短于 RawValueBelow 的值裸存；打包模式下小于 packBelow 的值按
// packTarget 攒组打包成一个 zstd 帧（组头含首记录号与长度表）；其余每条
// 独立成帧。PackTarget<0 进入每值成帧模式（全部值独立成帧 + 构建期训练
// 字典嵌 vals 头）。
//
// 记录按 key 升序；偏移一律是文件内绝对偏移。微块内 valOff 由 baseValOff
// 与 lens 推导（bit29 同帧位不加前条帧长）。
//
// 生命周期契约：
//   - Create 的目标文件必须不存在；已有库不会被覆盖，重建前先删除旧文件。
//   - Finish 走临时文件 + fsync + rename；失败时返回错误并清理本次创建的文件。
//   - 构建期间调用方独占目标，Finish 成功后才能打开库。
//   - 同一份数据文件可被任意多进程同时打开（无锁）。
//   - 查询返回的切片只保证到下一次查询前有效，要保留就拷贝。
//
// 平台：纯 Go 可构建（CGO_ENABLED=0）；CGO 可用时每值压缩与解压走 libzstd
// 加速（帧格式与纯 Go 后端标准互通），文件格式本身零地址与内存布局依赖，
// 跨机器、跨架构可直接使用。
//
// 本包为 annoplex `kv-custom` 后端的底层引擎，独立成库发布；
// 前身 immdb（annoplex internal/immdb，块 + 值子块 + mmap 直访）已由本包取代。
package immkv

import (
	"bufio"
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"os"
	"sort"

	"github.com/klauspost/compress/zstd"
)

const (
	keysMagic = "IMKVK002" // v2：微块键流（64 条/块 + 常驻块索引）
	valsMagic = "IMKVV003"

	headerSize   = 64
	recsPerBlock = 64      // 每微块记录数（末块可短）
	flagShare    = 1 << 29 // frameLen bit29：与上一条记录同帧（valOff 相同）

	flagRaw      = 1 << 31   // valLen 最高位：1 = 裸存帧
	flagPacked   = 1 << 30   // valLen 次高位：1 = 打包帧（多值一帧）
	frameLenMask = 1<<29 - 1 // valLen 低 29 位 = 帧长（bit31 裸存、bit30 打包、bit29 同帧）
	maxFrameLen  = 1<<29 - 1 // 帧长度语义上限（512MB，高 3 位是标记）
	maxValLen    = 1<<31 - 1 // 单条值的长度上限（u32 存得下，检查在投入时）
	maxKeyLen    = 1<<16 - 1 // keyLen u16 语义上限

	defaultRawValueBelow = 64
	packBelow            = 32 << 10 // 值小于此进打包帧；大值（>32KB，罕见）按值独立成帧
	packTarget           = 64 << 10 // 打包帧的目标未压字节数
	flushChunk           = 4 << 20  // AddSorted 攒集缓冲上限（key+val 字节数）

	// 每值成帧模式（CreateOptions.PackTarget < 0）的字典训练参数
	trainSamples = 5000      // Contents 条数（训熵表用）
	trainHistory = 512 << 10 // History 上限：实测 512KB 时 chr22 为 bgzip 的 82%，128KB 涨到 110% 破体积线
	dictID       = 1         // 字典 ID；帧头记录它，解码侧按 vals 头还原
)

// CreateOptions 是 Create 的选项。
type CreateOptions struct {
	// RawValueBelow：值短于该字节数时裸存（不压缩、免解压），0 取默认 64；
	// 设成大值即全裸存（对应旧 immdb 的 raw 档）。读侧按每条记录的裸存
	// 标记识别，不依赖这个参数。
	RawValueBelow int
	// PackTarget：打包帧的目标未压字节数，0 取默认 64KB。小包解码与读量都
	// 小、体积大；大包反之。负值表示不打包——每条值独立成帧，并用首批值
	// 训练 zstd 字典嵌进 vals 头（稀疏点查读得最省，体积比打包大 ~20%）。
	// 读侧不依赖这个参数。
	PackTarget int
	// Schema 是字段表。nil/空表示单 String 字段 value：Add 与 AddSorted
	// 收原始值字节，writer 包成 record。非空表示调用方传入的 value 已经
	// 是 record 字节，writer 只落盘、不校验内容。
	Schema []Field
}

// BuildOptions 是 BuildFromVCFs 与 BuildFromTSVs 的构建选项；schema 由输入
// 格式决定，调用方不能指定。
type BuildOptions struct {
	RawValueBelow int
	PackTarget    int
}

// StreamOptions 是 OpenStreaming 的选项。
type StreamOptions struct {
	// Threads 是并发旋钮：同时决定在途 pread 请求数与并行解压 goroutine
	// 数，默认 1。生产口径由调用方在多个句柄间分配总预算。
	Threads int
	// Columns 是字段选择：nil 或空表示库内全部列，非空是 base.manifest 里
	// 的列号；顺序无关，输出始终按 schema 顺序。选择只决定读出哪些字段，
	// 不决定走记录序还是列存——路径由读侧按估算 I/O 成本选。没有
	// base.col/manifest 的库用非空 Columns 会报错。
	Columns []int
}

// ---- Writer ----

// dictCompressor 是字典逐值压缩的后端：CGO 可用时走 libzstd（快 6 倍），
// 否则回退 klauspost 纯 Go。帧格式标准互通，查询端只认帧不认后端。
type dictCompressor interface {
	encode(src []byte) []byte
}

type kvRec struct {
	key []byte
	val []byte
}

// Writer 收集键值并在 Finish 时一次性落盘；或用 AddSorted 流式逐段落盘。
type Writer struct {
	base          string
	keysPath      string
	valsPath      string
	keysTmp       string
	valsTmp       string
	kf, vf        *os.File
	kw, vw        *bufio.Writer
	files         buildFiles
	opts          CreateOptions
	rawBelow      int
	packTarget    int // <0：每值独立成帧模式（配合训练字典）
	wrapRawValues bool
	wrapBuf       []byte
	enc           *zstd.Encoder
	dictComp      dictCompressor // 每值模式的字典压缩后端（libzstd CGO 或 klauspost）
	dictTrained   bool
	dictLen       uint32
	dictOff       uint64

	mode     int8  // 0 未定，1 任意序（Add），2 组升序（AddSorted）；两种模式不可混用
	finished bool  // Finish 已被调用（无论成败）
	closed   bool  // Finish/Abort 已结束，包括清理失败；不再重复清理
	err      error // 首个构建错误；一旦置位，后续 Add/AddSorted/Finish 都返回它

	recs   []kvRec // Add 全量驻存；AddSorted 是当前攒集缓冲
	pend   int     // 攒集缓冲里 key+val 的字节数
	total  uint64
	keysAt int64 // keys 文件逻辑写位置（含 64B 头）
	valsAt int64 // vals 文件逻辑写位置（含 64B 头）

	// 微块组装：攒 recsPerBlock 条（键 + 帧长标记）成块落盘；flagShare 由
	// valOff 与上一条的关系推导，块首条记 baseValOff 绝对值
	blkKeys    []byte
	blkKeyEnds []uint32
	blkLens    []uint32
	blkValOff  uint64 // 本块首条记录的 valOff
	prevValOff uint64 // 上一条已发射记录的 valOff
	prevLen    uint32 // 上一条的帧长
	hasPrev    bool
	nInBlk     int
	blockCount uint32
	blkPrefix  []byte // 块首键 8B 前缀（零填充），Finish 时拼索引
	blkOffs    []byte // 块偏移，与 blkPrefix 平行

	curGroup []byte // AddSorted 当前组键（拷贝；nil = 还没有组）
	lastKey  []byte // AddSorted 已进入攒集缓冲的最大键（拷贝）
	grp      []kvRec
}

// Create 创建最终文件为 basePath.keys 与 basePath.vals 的构建器。
// 目标文件或 .tmp 文件已存在时返回错误，绝不覆盖已有库；构建失败后由调用方
// 删除残留再重建。Finish 前磁盘上只有两个 .tmp 文件。CreateOptions.Schema
// 决定 Add/AddSorted 收到的是原始值还是已编码 record：空 schema 由 writer
// 包 record，非空 schema 要求调用方自己编码。
func Create(basePath string, opts CreateOptions) (_ *Writer, err error) {
	if len(opts.Schema) > 0 {
		if err := Schema(opts.Schema).Validate(); err != nil {
			return nil, err
		}
	}
	kp, vp := basePath+".keys", basePath+".vals"
	kt, vt := kp+".tmp", vp+".tmp"
	for _, p := range []string{kp, vp, kt, vt, basePath + ".col", basePath + ".manifest", basePath + ".col.tmp", basePath + ".manifest.tmp"} {
		if _, err := os.Lstat(p); err == nil {
			return nil, fmt.Errorf("immkv: %s already exists; delete it and rebuild", p)
		} else if !os.IsNotExist(err) {
			return nil, err
		}
	}
	w := &Writer{
		base: basePath, keysPath: kp, valsPath: vp, keysTmp: kt, valsTmp: vt,
		opts: opts, wrapRawValues: len(opts.Schema) == 0,
	}
	defer func() {
		if err != nil {
			w.closeEnc()
			err = errors.Join(err, w.abort())
		}
	}()
	w.kf, err = w.files.create(kt)
	if err != nil {
		return nil, err
	}
	w.vf, err = w.files.create(vt)
	if err != nil {
		return nil, err
	}
	w.enc, err = zstd.NewWriter(nil)
	if err != nil {
		return nil, err
	}
	w.kw = bufio.NewWriterSize(w.kf, 1<<20)
	w.vw = bufio.NewWriterSize(w.vf, 1<<20)
	if w.opts.RawValueBelow <= 0 {
		w.rawBelow = defaultRawValueBelow
	} else {
		w.rawBelow = w.opts.RawValueBelow
	}
	switch {
	case w.opts.PackTarget < 0:
		w.packTarget = w.opts.PackTarget // 每值成帧模式
	case w.opts.PackTarget > 0:
		w.packTarget = w.opts.PackTarget
	default:
		w.packTarget = packTarget
	}
	// 两个文件各预留 64B 头，Finish 时回填
	if _, err := w.kw.Write(make([]byte, headerSize)); err != nil {
		return nil, err
	}
	if _, err := w.vw.Write(make([]byte, headerSize)); err != nil {
		return nil, err
	}
	w.keysAt, w.valsAt = headerSize, headerSize
	return w, nil
}

// Add 投入一条记录，键值内容会被拷贝，调用方可复用自己的缓冲。键可重复，
// Get 返回排序后的第一条，GetPrefix/Scan 能看到全部。与 AddSorted 不可混用。
// CreateOptions.Schema 为空时 val 是原始值，writer 包成单 String 字段 record；
// 非空时 val 必须已经是 record。键值全量驻内存（ClinVar 规模约 GB 级）；
// TB 级用 AddSorted。键或值超出格式上限（u16 / u31）返回错误。
// 任一错误都会粘住 writer：之后的操作与 Finish 都返回该错误。
func (w *Writer) Add(key, val []byte) error {
	if w.finished {
		return errors.New("immkv: Writer already finished")
	}
	if w.err != nil {
		return w.err
	}
	if w.mode == 2 {
		return w.fail(errors.New("immkv: Add after AddSorted"))
	}
	val = w.prepareValue(val)
	if err := checkRecCaps(key, val); err != nil {
		return w.fail(err)
	}
	w.recs = append(w.recs, kvRec{bytes.Clone(key), bytes.Clone(val)})
	w.mode = 1
	return nil
}

// AddSorted 以「组升序」流式投入一条记录：键值内容会被拷贝。group 按 bytesCompare
// 升序到来（相等表示同组，同组记录必须连续到达），组内顺序任意；攒够 flushChunk
// （4MB）即时落盘。组结束（group 变化或 Finish）时组内按完整键排序后进入落盘路径。
// group 倒序、或键低于已进入攒集缓冲的最大键（组间倒挂在该条投入时即已注定）返回
// error 且该条不进库。内存有界：攒集缓冲 + 当前组（组大小由数据决定）。与 Add
// 不可混用。CreateOptions.Schema 为空时 val 是原始值，writer 包成单 String
// 字段 record；非空时 val 必须已经是 record。
//
// 基因组数据的标准用法：group 传键的位置前缀（如 [chrom][pos]），同一位置
// (ref, alt) 的乱序由库吸收，升序条件收窄为「本染色体内按位置有序」；输入已
// 全排序时 group 传键本身，行为与逐条升序一致。
// 任一错误都会粘住 writer：之后的操作与 Finish 都返回该错误。
func (w *Writer) AddSorted(group, key, val []byte) error {
	if w.finished {
		return errors.New("immkv: Writer already finished")
	}
	if w.err != nil {
		return w.err
	}
	if w.mode == 1 {
		return w.fail(errors.New("immkv: AddSorted after Add"))
	}
	if w.curGroup == nil {
		w.curGroup = bytes.Clone(group)
	} else {
		c := bytes.Compare(group, w.curGroup)
		if c < 0 {
			return w.fail(fmt.Errorf("immkv: AddSorted group out of order: %q < current %q", group, w.curGroup))
		}
		if c > 0 {
			if err := w.closeGroup(); err != nil {
				return w.fail(err)
			}
			w.curGroup = bytes.Clone(group)
		}
	}
	// 到这里 lastKey 已含先前全部已接受记录；键低于它 ⇒ 本组最小键必然更低，
	// 组间倒挂已定，该条立即拒绝
	if w.lastKey != nil && bytes.Compare(key, w.lastKey) < 0 {
		return w.fail(fmt.Errorf("immkv: AddSorted key %q below last emitted %q", key, w.lastKey))
	}
	val = w.prepareValue(val)
	if err := checkRecCaps(key, val); err != nil {
		return w.fail(err)
	}
	w.grp = append(w.grp, kvRec{bytes.Clone(key), bytes.Clone(val)})
	w.mode = 2
	return nil
}

// closeGroup 把当前组按完整键排序、校验组间不倒挂，然后逐条进入攒集缓冲
// （攒够 flushChunk 即落盘）。重复键允许，照常落盘。
func (w *Writer) closeGroup() error {
	if len(w.grp) == 0 {
		return nil
	}
	sort.Slice(w.grp, func(i, j int) bool { return bytes.Compare(w.grp[i].key, w.grp[j].key) < 0 })
	if w.lastKey != nil && bytes.Compare(w.grp[0].key, w.lastKey) < 0 {
		return fmt.Errorf("immkv: AddSorted key inversion across groups: %q < %q", w.grp[0].key, w.lastKey)
	}
	for i := range w.grp {
		r := w.grp[i]
		w.lastKey = append(w.lastKey[:0], r.key...)
		w.recs = append(w.recs, r)
		w.pend += len(r.key) + len(r.val)
		if w.pend >= flushChunk {
			if err := w.flushPending(); err != nil {
				return err
			}
		}
	}
	w.grp = w.grp[:0]
	return nil
}

// flushPending 把攒集缓冲里的记录依序落盘：短于 rawBelow 的值裸存；打包模式
// 下小于 packBelow 的值攒进打包帧、其余独立成帧；每值模式（PackTarget<0）下
// 除裸存外全部独立成帧，并在首次落盘前用攒集缓冲里的前 trainSamples 条值
// 训练 zstd 字典（正文截 trainHistory），字典嵌进 vals 头，之后全部值帧用它
// 压缩——稀疏点查的读取粒度与解码量都按单值计。
func (w *Writer) flushPending() error {
	if len(w.recs) == 0 {
		return nil
	}
	if w.packTarget < 0 && !w.dictTrained {
		if err := w.trainDict(); err != nil {
			return err
		}
	}
	if w.packTarget >= 0 {
		return w.flushPacked()
	}
	for i := range w.recs {
		r := w.recs[i]
		if len(r.val) < w.rawBelow {
			if err := w.emitRec(r.key, uint64(w.valsAt), uint32(len(r.val))|flagRaw); err != nil {
				return err
			}
			if _, err := w.vw.Write(r.val); err != nil {
				return err
			}
			w.valsAt += int64(len(r.val))
			continue
		}
		var comp []byte
		if w.dictComp != nil {
			comp = w.dictComp.encode(r.val)
		} else {
			comp = w.enc.EncodeAll(r.val, nil)
		}
		if len(comp) > maxFrameLen {
			panic(fmt.Sprintf("immkv: 值帧 %d B 超过上限", len(comp)))
		}
		if err := w.emitRec(r.key, uint64(w.valsAt), uint32(len(comp))); err != nil {
			return err
		}
		if _, err := w.vw.Write(comp); err != nil {
			return err
		}
		w.valsAt += int64(len(comp))
	}
	w.recs = w.recs[:0]
	w.pend = 0
	return nil
}

// trainDict 用攒集缓冲里的首批值训练 zstd 字典，重建带字典的编码器，并把
// 字典写到 vals 头之后（记录 dictOff/dictLen 供读侧还原）。
func (w *Writer) trainDict() error {
	w.dictTrained = true
	n := len(w.recs)
	if n > trainSamples {
		n = trainSamples
	}
	contents := make([][]byte, 0, n)
	var hist []byte
	for i := 0; i < n; i++ {
		v := w.recs[i].val
		contents = append(contents, v)
		if len(hist) < trainHistory {
			take := len(v)
			if rem := trainHistory - len(hist); take > rem {
				take = rem
			}
			hist = append(hist, v[:take]...)
		}
	}
	if len(hist) < 8 || n == 0 {
		return nil // 值太少（或全空）：不写字典，裸 zstd 帧
	}
	dict, err := zstd.BuildDict(zstd.BuildDictOptions{
		ID:       dictID,
		Contents: contents,
		History:  hist,
	})
	if err != nil {
		return err
	}
	w.dictOff = headerSize
	w.dictLen = uint32(len(dict))
	if _, err := w.vw.Write(dict); err != nil {
		return err
	}
	w.valsAt += int64(len(dict))
	w.enc.Close()
	enc, err := zstd.NewWriter(nil, zstd.WithEncoderDict(dict), zstd.WithEncoderCRC(false))
	if err != nil {
		return err
	}
	w.enc = enc
	// 每值压缩优先 libzstd CGO（CDict，实测 630MB/s/核，klauspost 纯 Go
	// 102MB/s）；不可用（CGO_ENABLED=0）或建器失败时 dictComp 留 nil，
	// flushPending 回退 w.enc（klauspost 字典编码器）。帧格式两后端互通。
	if dc, derr := newCGODictCompressor(dict); derr == nil {
		w.dictComp = dc
	}
	return nil
}

// flushPacked 是打包模式的落盘实现。
func (w *Writer) flushPacked() error {
	var (
		packKeys  [][]byte // 打包成员的键（键流记录推迟到帧成形时写）
		packVals  [][]byte
		packFirst int // 首成员的全局记录号（写进组头，读侧换算组内下标）
		packBytes int
	)
	closePack := func() error {
		if len(packVals) == 0 {
			return nil
		}
		frame := make([]byte, 8+4*len(packVals)+packBytes)
		binary.LittleEndian.PutUint32(frame[0:4], uint32(packFirst))
		binary.LittleEndian.PutUint32(frame[4:8], uint32(len(packVals)))
		o := 8
		for _, v := range packVals {
			binary.LittleEndian.PutUint32(frame[o:o+4], uint32(len(v)))
			o += 4
		}
		for _, v := range packVals {
			copy(frame[o:], v)
			o += len(v)
		}
		comp := w.enc.EncodeAll(frame, nil)
		if len(comp) > maxFrameLen {
			panic(fmt.Sprintf("immkv: 打包帧 %d B 超过 u30 上限", len(comp)))
		}
		valOff := uint64(w.valsAt)
		mark := uint32(len(comp)) | flagPacked
		for _, k := range packKeys {
			if err := w.emitRec(k, valOff, mark); err != nil {
				return err
			}
		}
		if _, err := w.vw.Write(comp); err != nil {
			return err
		}
		w.valsAt += int64(len(comp))
		packKeys, packVals, packBytes = packKeys[:0], packVals[:0], 0
		return nil
	}
	for i := range w.recs {
		r := w.recs[i]
		switch {
		case len(r.val) < w.rawBelow:
			if err := closePack(); err != nil {
				return err
			}
			if err := w.emitRec(r.key, uint64(w.valsAt), uint32(len(r.val))|flagRaw); err != nil {
				return err
			}
			if _, err := w.vw.Write(r.val); err != nil {
				return err
			}
			w.valsAt += int64(len(r.val))
		case len(r.val) < packBelow:
			if packBytes > 0 && packBytes+len(r.val) > w.packTarget {
				if err := closePack(); err != nil {
					return err
				}
			}
			if len(packVals) == 0 {
				packFirst = int(w.total)
			}
			packKeys = append(packKeys, r.key)
			packVals = append(packVals, r.val)
			packBytes += len(r.val)
		default:
			if err := closePack(); err != nil {
				return err
			}
			comp := w.enc.EncodeAll(r.val, nil)
			if len(comp) > maxFrameLen {
				panic(fmt.Sprintf("immkv: 值帧 %d B 超过 u30 上限", len(comp)))
			}
			if err := w.emitRec(r.key, uint64(w.valsAt), uint32(len(comp))); err != nil {
				return err
			}
			if _, err := w.vw.Write(comp); err != nil {
				return err
			}
			w.valsAt += int64(len(comp))
		}
	}
	if err := closePack(); err != nil {
		return err
	}
	w.recs = w.recs[:0]
	w.pend = 0
	return nil
}

// fail 记录首个构建错误并返回它；后续操作与 Finish 都返回同一个错误。
func (w *Writer) fail(err error) error {
	if w.err == nil {
		w.err = err
	}
	return w.err
}

// checkRecCaps 检查键值长度是否在格式上限内，超出返回错误。
// prepareValue 在空 schema 的库里把原始值包成单 String 字段的 record：
// 8B bitmap（bit0=1）+ uvarint(len) + 原字节。非空 schema 的库认为调用方
// 已经编码好 record，原样落盘。
func (w *Writer) prepareValue(val []byte) []byte {
	if !w.wrapRawValues {
		return val
	}
	w.wrapBuf = w.wrapBuf[:0]
	var bitmap [8]byte
	binary.LittleEndian.PutUint64(bitmap[:], 1)
	w.wrapBuf = append(w.wrapBuf, bitmap[:]...)
	w.wrapBuf = binary.AppendUvarint(w.wrapBuf, uint64(len(val)))
	w.wrapBuf = append(w.wrapBuf, val...)
	return w.wrapBuf
}

func checkRecCaps(key, val []byte) error {
	if len(key) > maxKeyLen {
		return fmt.Errorf("immkv: key 长度 %d 超过 u16 上限 %d", len(key), maxKeyLen)
	}
	if len(val) > maxValLen {
		return fmt.Errorf("immkv: 值长度 %d 超过 u31 上限 %d", len(val), maxValLen)
	}
	return nil
}

// emitRec 发射一条键流记录进微块组装器；frameMark 含裸存/打包标记（低 29 位
// 是帧长）。valOff 必须等于「上一条的 valOff + 上一条的帧长」或与上一条相同
// （打包帧成员）——写侧不变式，违反即 panic。攒满 recsPerBlock 条即落一块。
func (w *Writer) emitRec(key []byte, valOff uint64, frameMark uint32) error {
	mark := frameMark &^ flagShare
	if w.hasPrev {
		if valOff == w.prevValOff {
			mark |= flagShare
		} else if valOff != w.prevValOff+uint64(w.prevLen) {
			panic(fmt.Sprintf("immkv: 写侧不变式破坏：valOff %d ≠ 前条 %d+%d", valOff, w.prevValOff, w.prevLen))
		}
	} else {
		w.blkValOff = valOff
	}
	if w.nInBlk == 0 {
		w.blkValOff = valOff
	}
	w.blkKeys = append(w.blkKeys, key...)
	w.blkKeyEnds = append(w.blkKeyEnds, uint32(len(w.blkKeys)))
	w.blkLens = append(w.blkLens, mark)
	w.prevValOff, w.prevLen, w.hasPrev = valOff, mark&frameLenMask, true
	w.nInBlk++
	w.total++
	if w.nInBlk == recsPerBlock {
		return w.flushBlock()
	}
	return nil
}

// flushBlock 落一个微块：[keyEnds u32×n][lens u32×n][baseValOff u64][keyData]，
// 并把块首键 8B 前缀与块偏移记进索引材料。u32 的 keyEnd 使单块 keyData 上限
// 4GB，远超 64 条键的规模。
func (w *Writer) flushBlock() error {
	if w.nInBlk == 0 {
		return nil
	}
	// 记索引材料：块偏移 + 首键前 8B（零填充）
	w.blkOffs = binary.LittleEndian.AppendUint64(w.blkOffs, uint64(w.keysAt))
	var pfx [8]byte
	copy(pfx[:], w.blkKeys[:w.blkKeyEnds[0]])
	w.blkPrefix = append(w.blkPrefix, pfx[:]...)
	// 块体：[keyEnds u32×n][lens u32×n][baseValOff u64][keyData]
	buf := make([]byte, 0, 8*w.nInBlk+8+len(w.blkKeys))
	for _, e := range w.blkKeyEnds {
		buf = binary.LittleEndian.AppendUint32(buf, e)
	}
	buf = append(buf, w.blkLensToBytes()...)
	buf = binary.LittleEndian.AppendUint64(buf, w.blkValOff)
	buf = append(buf, w.blkKeys...)
	if _, err := w.kw.Write(buf); err != nil {
		return err
	}
	w.keysAt += int64(len(buf))
	w.blockCount++
	w.blkKeys = w.blkKeys[:0]
	w.blkKeyEnds = w.blkKeyEnds[:0]
	w.blkLens = w.blkLens[:0]
	w.nInBlk = 0
	return nil
}

func (w *Writer) blkLensToBytes() []byte {
	out := make([]byte, 4*len(w.blkLens))
	for i, l := range w.blkLens {
		binary.LittleEndian.PutUint32(out[4*i:], l)
	}
	return out
}

// Finish 排序（Add 模式）、落盘锚点、回填两个文件头、fsync，再发布两个文件。
// 再次调用返回错误。构建期间出现过错误时，Finish 返回该错误且不发布任何文件。
// 失败时只清理本次创建或发布的文件，目标文件已存在时绝不覆盖。
func (w *Writer) Finish() error {
	if w.finished {
		return errors.New("immkv: Writer already finished")
	}
	w.finished = true
	err := w.err
	if err == nil {
		err = w.finish()
	}
	w.closeEnc()
	if err != nil {
		err = errors.Join(err, w.abort())
	}
	w.closed = true
	return err
}

// Abort 放弃构建：关闭文件与编码器，只删除本次创建的文件。幂等；第一次调用
// 即使清理报错也会结束，残留由调用方处理。Finish 之后调用不再执行清理。
func (w *Writer) Abort() error {
	if w.closed {
		return nil
	}
	w.finished, w.closed = true, true
	w.closeEnc()
	return w.abort()
}

func (w *Writer) closeEnc() {
	if w.enc != nil {
		w.enc.Close()
		w.enc = nil
	}
}

func (w *Writer) finish() error {
	if w.mode == 2 {
		// 流式：组与攒集缓冲已在 AddSorted 里逐段落盘，只剩尾部一组一段
		if err := w.closeGroup(); err != nil {
			return err
		}
		if err := w.flushPending(); err != nil {
			return err
		}
	} else if w.mode == 1 {
		sort.Slice(w.recs, func(i, j int) bool {
			return bytes.Compare(w.recs[i].key, w.recs[j].key) < 0
		})
		if err := w.flushPending(); err != nil {
			return err
		}
	}
	if err := w.flushBlock(); err != nil { // 尾部不足一块的记录
		return err
	}
	indexOff := w.keysAt
	if _, err := w.kw.Write(w.blkPrefix); err != nil {
		return err
	}
	if _, err := w.kw.Write(w.blkOffs); err != nil {
		return err
	}
	if err := w.kw.Flush(); err != nil {
		return err
	}
	if err := w.vw.Flush(); err != nil {
		return err
	}
	if err := w.writeKeysHeader(uint64(indexOff)); err != nil {
		return err
	}
	if err := w.writeValsHeader(); err != nil {
		return err
	}
	if err := w.kf.Sync(); err != nil {
		return err
	}
	if err := w.vf.Sync(); err != nil {
		return err
	}
	err := w.kf.Close()
	w.kf = nil
	if err != nil {
		return err
	}
	err = w.vf.Close()
	w.vf = nil
	if err != nil {
		return err
	}
	// 值文件先发布；任一目标已经存在就报错，不覆盖其他文件。
	if err := w.files.publish(w.valsTmp, w.valsPath); err != nil {
		return err
	}
	return w.files.publish(w.keysTmp, w.keysPath)
}

func (w *Writer) writeKeysHeader(indexOff uint64) error {
	h := make([]byte, headerSize)
	copy(h[0:8], keysMagic)
	binary.LittleEndian.PutUint32(h[8:12], 1) // version
	binary.LittleEndian.PutUint64(h[12:20], w.total)
	binary.LittleEndian.PutUint16(h[20:22], recsPerBlock)
	binary.LittleEndian.PutUint32(h[24:28], w.blockCount)
	binary.LittleEndian.PutUint64(h[28:36], indexOff)
	binary.LittleEndian.PutUint32(h[36:40], uint32(w.rawBelow))
	_, err := w.kf.WriteAt(h, 0)
	return err
}

func (w *Writer) writeValsHeader() error {
	h := make([]byte, headerSize)
	copy(h[0:8], valsMagic)
	binary.LittleEndian.PutUint32(h[8:12], 3) // version
	binary.LittleEndian.PutUint64(h[12:20], w.total)
	binary.LittleEndian.PutUint32(h[20:24], w.dictLen)
	binary.LittleEndian.PutUint64(h[24:32], w.dictOff)
	_, err := w.vf.WriteAt(h, 0)
	return err
}

// abort 关闭尚未释放的文件，清理本次创建或发布的路径；清单只消耗一次。
func (w *Writer) abort() error {
	var err error
	if w.kf != nil {
		err = errors.Join(err, w.kf.Close())
		w.kf = nil
	}
	if w.vf != nil {
		err = errors.Join(err, w.vf.Close())
		w.vf = nil
	}
	return errors.Join(err, w.files.cleanup())
}

files.ingest.go:
// ingest.go 是 VCF/TSV 的建库入口：把输入格式解析、键编码、组序与落盘
// 收进库里，调用方只给路径、字段、前缀和 BuildOptions。设计见
// docs/ingest-design.md。
//
// 两个入口的产出形态沿用库的既有约定：
//   - BuildFromVCFs 产出分染色体库（outdir/chrN.keys + chrN.vals），
//     由 OpenEager/OpenStreaming 打开。
//   - BuildFromTSVs 产出单库（basePath.keys + basePath.vals），由
//     OpenSimpleKV 打开。
package immkv

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/biogo/hts/bgzf"
)

const (
	vcfRawHeaderName   = "vcf.raw.header"
	vcfImmkvHeaderName = "vcf.immkv.header"
	maxIngestLine      = 64 << 20 // 单行上限；超出返回错误，不静默截断
)

// BuildFromTSVs 从无表头的 TSV 建单库。输入按 \t 分隔：第一列是键，第二个
// 字段到行尾原样是值（列间 \t 保留）。多个文件按参数顺序拼接后，第一列必须
// 整体按字节序升序；内部走 AddSorted，内存有界。空行跳过，没有 \t 的行视为
// 键加空值，CRLF 的 \r 去掉。输出 basePath.keys + basePath.vals，用
// OpenSimpleKV 打开；basePath 的父目录不存在时创建，目标文件已存在则报错。
// 构建失败时删除本次创建的产物，调用方重建前无需手工清理（但已存在同名
// 文件会在开始时就拒绝）。
func BuildFromTSVs(basePath string, tsvs []string, opts BuildOptions) (err error) {
	if basePath == "" {
		return errors.New("immkv: BuildFromTSVs: empty basePath")
	}
	if len(tsvs) == 0 {
		return errors.New("immkv: BuildFromTSVs: no input files")
	}
	if err := os.MkdirAll(filepath.Dir(basePath), 0o755); err != nil {
		return err
	}
	w, err := Create(basePath, CreateOptions{
		RawValueBelow: opts.RawValueBelow,
		PackTarget:    opts.PackTarget,
	})
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			err = errors.Join(err, w.Abort(), w.files.cleanup())
		}
	}()
	for _, path := range tsvs {
		if err := addTSVFile(w, path); err != nil {
			return err
		}
	}
	if err := w.Finish(); err != nil {
		return err
	}
	buildID, err := newBuildID()
	if err != nil {
		return err
	}
	return writeColumnar(basePath, simpleKVSchema(), buildID, SourceInfoOrder{}, 0, 0)
}

// addTSVFile 把一个 TSV 文件的记录按顺序喂给 w。行切片会被 AddSorted 拷贝，
// 调用方可复用扫描缓冲。
func addTSVFile(w *Writer, path string) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 64*1024), maxIngestLine)
	lineNo := 0
	for sc.Scan() {
		lineNo++
		line := sc.Bytes()
		if n := len(line); n > 0 && line[n-1] == '\r' {
			line = line[:n-1]
		}
		if len(line) == 0 {
			continue
		}
		key := line
		var val []byte
		if i := bytes.IndexByte(line, '\t'); i >= 0 {
			key, val = line[:i], line[i+1:]
		}
		if err := w.AddSorted(key, key, val); err != nil {
			return fmt.Errorf("%s:%d: %w", path, lineNo, err)
		}
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	return nil
}

// BuildFromVCFs 从 VCF 建分染色体库：outdir/chrN.keys + chrN.vals，由
// OpenEager/OpenStreaming 打开。输入接受两种形态：
//
//  1. 单个 VCF：每条染色体的记录连续一块，块内 POS 升序；
//  2. 多个 VCF：每个文件只含一条染色体，文件内 POS 升序。
//
// 两种形态都允许同一 CHROM+POS 内 REF/ALT 乱序（组键吸收）。未知 contig、
// REF 为 "." 的记录、符号化/缺失 ALT 按 test/buildfull 口径跳过。
//
// fields 为 nil 或空表示全部 INFO 字段；非空时只存这些字段，fields 的顺序
// 只用于选择，值一律按 ##INFO 声明顺序拼；Number=A 的字段从 ##INFO 头读
// Number、按原始 ALT 下标取逗号元素。prefix 非空时每个 INFO 键写成 prefix_键。
// 源 INFO 的未知字段、重复字段、空段、Flag 带值、非 Flag 缺值都返回错误，
// 不静默丢字段；没有输出字段的记录值写成 "."。
//
// 构建成功后写 outdir/vcf.raw.header（第一个输入的完整头）与
// outdir/vcf.immkv.header（加前缀、按 fields 过滤并按 ##INFO 顺序排列的
// schema 头）。outdir 必须不存在（父目录可以存在）；构建失败时删除本次
// 创建的 outdir，调用方删除残留后即可重建。
func BuildFromVCFs(outdir string, vcfs []string, fields []string, prefix string, opts BuildOptions) (err error) {
	if outdir == "" {
		return errors.New("immkv: BuildFromVCFs: empty outdir")
	}
	if len(vcfs) == 0 {
		return errors.New("immkv: BuildFromVCFs: no input files")
	}
	if err := validateVCFPrefix(prefix); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(outdir), 0o755); err != nil {
		return err
	}
	if err := os.Mkdir(outdir, 0o755); err != nil {
		if os.IsExist(err) {
			return fmt.Errorf("immkv: BuildFromVCFs: %s already exists; use a new directory", outdir)
		}
		return err
	}
	defer func() {
		if err != nil {
			if rerr := os.RemoveAll(outdir); rerr != nil {
				err = fmt.Errorf("%w; cleanup: %v", err, rerr)
			}
		}
	}()
	multi := len(vcfs) > 1
	plan, err := prepareVCFInputs(vcfs, fields, prefix, multi)
	if err != nil {
		return err
	}
	if multi {
		if err := buildVCFShardsParallel(outdir, plan, opts); err != nil {
			return err
		}
	} else {
		if err := buildVCFShardsSingle(outdir, vcfs[0], plan, opts); err != nil {
			return err
		}
	}
	if err := writeBuildFile(filepath.Join(outdir, vcfRawHeaderName), plan.raw); err != nil {
		return err
	}
	return writeBuildFile(filepath.Join(outdir, vcfImmkvHeaderName),
		buildImmkvHeader(plan.header.fileFormat, plan.selectedFields))
}

// validateVCFPrefix 拒绝会破坏 INFO 语法的前缀。
func validateVCFPrefix(prefix string) error {
	if prefix == "" {
		return nil
	}
	if strings.ContainsAny(prefix, ";= \t\r\n") {
		return fmt.Errorf("immkv: BuildFromVCFs: invalid prefix %q", prefix)
	}
	return nil
}

// ---- VCF 头与字段 ----

// infoDef 是一条 ##INFO 声明的解析结果。
type infoDef struct {
	line   []byte // 完整声明行（不含换行）
	number string // Number 属性的原文
	typ    string // Type 属性的原文
	isFlag bool   // Number=0 或 Type=Flag
	order  int    // ##INFO 声明顺序（0 起）
}

// vcfHeader 是一个输入文件的头。
type vcfHeader struct {
	raw        []byte // 所有 ## 行 + #CHROM 行，逐字节
	fileFormat string // ##fileformat=... 整行
	info       map[string]*infoDef
	infoOrder  []string
}

// vcfInput 是多文件模式下待建的一个文件。
type vcfInput struct {
	path string
	cid  uint8
}

// valueField 是选中要存进值里的一个 INFO 字段。
type valueField struct {
	id       string // 原始 INFO ID
	prefixed string // prefix 后的键名
	number   string
	typ      string // Type 原文（列存 schema 用）
	isFlag   bool
	defLine  []byte // 原始 ##INFO 声明行
	order    int    // ##INFO 声明顺序（0 起）
}

// vcfPlan 是一次 BuildFromVCFs 的输入与字段方案。
type vcfPlan struct {
	header         *vcfHeader
	raw            []byte
	selectedFields []valueField
	schema         Schema
	buildID        [16]byte // 本次构建的记录序/列存配对代号
	inputs         []vcfInput
}

// prepareVCFInputs 预读所有输入的头，校验一致性，并确定字段方案。
func prepareVCFInputs(vcfs []string, fields []string, prefix string, multi bool) (*vcfPlan, error) {
	plan := &vcfPlan{}
	var seen [25]bool
	for _, path := range vcfs {
		r, err := openVCF(path, 1)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		hdr, firstData, err := readVCFHeader(r.br, multi)
		cerr := r.Close()
		if err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		if cerr != nil {
			return nil, fmt.Errorf("%s: %w", path, cerr)
		}
		if plan.header == nil {
			plan.header = hdr
			plan.raw = hdr.raw
		} else if err := sameVCFInfo(plan.header, hdr); err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		if multi {
			if firstData == nil {
				return nil, fmt.Errorf("%s: no records", path)
			}
			cid, err := firstDataChrom(firstData)
			if err != nil {
				return nil, fmt.Errorf("%s: %w", path, err)
			}
			if seen[cid] {
				return nil, fmt.Errorf("%s: chromosome %s appears in more than one input", path, ChromName(cid))
			}
			seen[cid] = true
			plan.inputs = append(plan.inputs, vcfInput{path: path, cid: cid})
		}
	}
	selectedFields, err := selectValueFields(plan.header, fields, prefix)
	if err != nil {
		return nil, err
	}
	plan.selectedFields = selectedFields
	plan.schema, err = schemaFromSelectedFields(selectedFields)
	if err != nil {
		return nil, err
	}
	id, err := newBuildID()
	if err != nil {
		return nil, err
	}
	plan.buildID = id
	return plan, nil
}

// schemaFromSelectedFields 把 ##INFO 字段方案转成 v003 schema：Flag 只占位，
// 其余字段按 Type/Number 原样落进 schema。
func schemaFromSelectedFields(fields []valueField) (Schema, error) {
	schema := make(Schema, len(fields))
	for i := range fields {
		field := &fields[i]
		if field.isFlag {
			schema[i] = Field{Name: field.prefixed, Type: TypeFlag, Number: "0"}
			continue
		}
		fieldType, ok := parseFieldType(field.typ)
		if !ok {
			return nil, fmt.Errorf("immkv: BuildFromVCFs: INFO field %q has unsupported type %q", field.id, field.typ)
		}
		schema[i] = Field{Name: field.prefixed, Type: fieldType, Number: field.number}
	}
	if err := schema.Validate(); err != nil {
		return nil, err
	}
	return schema, nil
}

// selectValueFields 把 fields 解析成 valueField 列表；fields 为空时取全部
// 字段；非空时只做选择，结果统一按 ##INFO 声明顺序排列（fields 的顺序不再
// 决定值序）。
func selectValueFields(h *vcfHeader, fields []string, prefix string) ([]valueField, error) {
	if len(fields) == 0 {
		sel := make([]valueField, 0, len(h.infoOrder))
		for _, id := range h.infoOrder {
			d := h.info[id]
			sel = append(sel, valueField{
				id: id, prefixed: prefixVCFID(prefix, id),
				number: d.number, typ: d.typ, isFlag: d.isFlag, defLine: d.line,
				order: d.order,
			})
		}
		return sel, nil
	}
	dup := make(map[string]bool, len(fields))
	sel := make([]valueField, 0, len(fields))
	for _, name := range fields {
		if name == "" {
			return nil, errors.New("immkv: BuildFromVCFs: empty field name")
		}
		if dup[name] {
			return nil, fmt.Errorf("immkv: BuildFromVCFs: duplicate field %q", name)
		}
		dup[name] = true
		d, ok := h.info[name]
		if !ok {
			return nil, fmt.Errorf("immkv: BuildFromVCFs: field %q not declared in ##INFO", name)
		}
		sel = append(sel, valueField{
			id: name, prefixed: prefixVCFID(prefix, name),
			number: d.number, typ: d.typ, isFlag: d.isFlag, defLine: d.line,
			order: d.order,
		})
	}
	sort.Slice(sel, func(i, j int) bool { return sel[i].order < sel[j].order })
	return sel, nil
}

// prefixVCFID 返回 prefix_字段名；prefix 为空时原样返回。
func prefixVCFID(prefix, id string) string {
	if prefix == "" {
		return id
	}
	return prefix + "_" + id
}

// sameVCFInfo 校验两个输入的头在 fileformat、全部 ##INFO 声明与声明顺序上一致。
func sameVCFInfo(a, b *vcfHeader) error {
	if a.fileFormat != b.fileFormat {
		return fmt.Errorf("##fileformat differs: %q vs %q", a.fileFormat, b.fileFormat)
	}
	if len(a.info) != len(b.info) {
		return errors.New("##INFO definitions differ")
	}
	for id, da := range a.info {
		db, ok := b.info[id]
		if !ok || da.number != db.number || !bytes.Equal(da.line, db.line) {
			return fmt.Errorf("##INFO definition %q differs", id)
		}
	}
	if len(a.infoOrder) != len(b.infoOrder) {
		return errors.New("##INFO order differs")
	}
	for i := range a.infoOrder {
		if a.infoOrder[i] != b.infoOrder[i] {
			return fmt.Errorf("##INFO order differs: %q vs %q", a.infoOrder[i], b.infoOrder[i])
		}
	}
	return nil
}

// ---- 文件读取 ----

// vcfReader 统一纯文本与 bgzf 输入，Close 同时关解压器和文件。
type vcfReader struct {
	f  *os.File
	br *bufio.Reader
	bg *bgzf.Reader
}

func (r *vcfReader) Close() error {
	var first error
	if r.bg != nil {
		if err := r.bg.Close(); err != nil {
			first = err
		}
	}
	if err := r.f.Close(); err != nil && first == nil {
		first = err
	}
	return first
}

// openVCF 打开输入：.gz/.bgz 走 bgzf（必须是 bgzf，不是普通 gzip），其余纯文本。
// bgzfWorkers=0 表示解压内部并行，适合单文件顺序建库；多文件模式传 1，由文件
// 级并行提供吞吐。
func openVCF(path string, bgzfWorkers int) (*vcfReader, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	if strings.HasSuffix(path, ".gz") || strings.HasSuffix(path, ".bgz") {
		bg, err := bgzf.NewReader(f, bgzfWorkers)
		if err != nil {
			f.Close()
			return nil, err
		}
		return &vcfReader{f: f, br: bufio.NewReaderSize(bg, 1<<20), bg: bg}, nil
	}
	return &vcfReader{f: f, br: bufio.NewReaderSize(f, 1<<20)}, nil
}

// readVCFHeader 读 ## 行与 #CHROM 行；needFirst 时再读第一条数据行（跳空行）。
// 返回的 raw 是头的逐字节副本。
func readVCFHeader(br *bufio.Reader, needFirst bool) (*vcfHeader, []byte, error) {
	h := &vcfHeader{info: make(map[string]*infoDef)}
	for {
		line, err := br.ReadBytes('\n')
		if len(line) > 0 {
			trimmed := bytes.TrimRight(line, "\r\n")
			switch {
			case len(trimmed) == 0:
				// 空行：跳过
			case bytes.HasPrefix(trimmed, []byte("##")):
				h.raw = append(h.raw, line...)
				if bytes.HasPrefix(trimmed, []byte("##INFO=<")) {
					if id, d, ok := parseInfoLine(trimmed); ok {
						if _, exists := h.info[id]; exists {
							return nil, nil, fmt.Errorf("duplicate ##INFO %q", id)
						}
						d.order = len(h.infoOrder)
						h.info[id] = d
						h.infoOrder = append(h.infoOrder, id)
					}
				} else if bytes.HasPrefix(trimmed, []byte("##fileformat=")) {
					h.fileFormat = string(trimmed)
				}
			case bytes.HasPrefix(trimmed, []byte("#CHROM")):
				if len(line) == len(trimmed) { // 末行没有换行
					h.raw = append(h.raw, line...)
					h.raw = append(h.raw, '\n')
				} else {
					h.raw = append(h.raw, line...)
				}
				if !needFirst {
					return h, nil, nil
				}
				first, err := readFirstDataLine(br)
				return h, first, err
			default:
				return nil, nil, errors.New("data before #CHROM line")
			}
		}
		if err != nil {
			if err == io.EOF {
				return nil, nil, errors.New("header missing #CHROM line")
			}
			return nil, nil, err
		}
	}
}

// readFirstDataLine 返回第一条非空数据行（去换行、拷贝）。
func readFirstDataLine(br *bufio.Reader) ([]byte, error) {
	for {
		line, err := br.ReadBytes('\n')
		if len(line) > 0 {
			trimmed := bytes.TrimRight(line, "\r\n")
			if len(trimmed) > 0 {
				return append([]byte(nil), trimmed...), nil
			}
		}
		if err != nil {
			if err == io.EOF {
				return nil, nil
			}
			return nil, err
		}
	}
}

// parseInfoLine 解析 ##INFO=<ID=...,Number=...,Type=...,Description="..."> 的
// ID、Number、Type；Description 里的逗号与转义引号不影响解析。
func parseInfoLine(line []byte) (string, *infoDef, bool) {
	const prefix = "##INFO=<"
	if !bytes.HasPrefix(line, []byte(prefix)) || line[len(line)-1] != '>' {
		return "", nil, false
	}
	content := line[len(prefix) : len(line)-1]
	var id, number, typ string
	start := 0
	inQuote := false
	for i := 0; i <= len(content); i++ {
		if i < len(content) {
			c := content[i]
			if inQuote {
				if c == '\\' {
					i++
				} else if c == '"' {
					inQuote = false
				}
				continue
			}
			if c == '"' {
				inQuote = true
				continue
			}
			if c != ',' {
				continue
			}
		}
		seg := content[start:i]
		if eq := bytes.IndexByte(seg, '='); eq >= 0 {
			switch string(seg[:eq]) {
			case "ID":
				id = string(headerRawValue(seg[eq+1:]))
			case "Number":
				number = string(headerRawValue(seg[eq+1:]))
			case "Type":
				typ = string(headerRawValue(seg[eq+1:]))
			}
		}
		start = i + 1
	}
	if id == "" {
		return "", nil, false
	}
	d := &infoDef{line: append([]byte(nil), line...), number: number, typ: typ}
	d.isFlag = number == "0" || typ == "Flag"
	return id, d, true
}

// headerRawValue 去掉属性值两侧的双引号。
func headerRawValue(v []byte) []byte {
	if len(v) >= 2 && v[0] == '"' && v[len(v)-1] == '"' {
		return v[1 : len(v)-1]
	}
	return v
}

// firstDataChrom 从第一行数据取 CHROM 并编码；未知 contig 报错。
func firstDataChrom(line []byte) (uint8, error) {
	chrom, _, _, _, _, err := splitVCFLine(line)
	if err != nil {
		return 0, err
	}
	cid, ok := ChromID(string(chrom))
	if !ok {
		return 0, fmt.Errorf("unknown contig %q", chrom)
	}
	return cid, nil
}

// splitVCFLine 切出 CHROM/POS/REF/ALT/INFO 五列。只认前 8 列：INFO 是第 8
// 列，有样本列时忽略；少于 8 列报错。
func splitVCFLine(line []byte) (chrom, pos, ref, alt, info []byte, err error) {
	var tabs [8]int
	n := 0
	for i := 0; i < len(line) && n < 8; i++ {
		if line[i] == '\t' {
			tabs[n] = i
			n++
		}
	}
	if n < 7 {
		return nil, nil, nil, nil, nil, errors.New("fewer than 8 columns")
	}
	chrom = line[:tabs[0]]
	pos = line[tabs[0]+1 : tabs[1]]
	ref = line[tabs[2]+1 : tabs[3]]
	alt = line[tabs[3]+1 : tabs[4]]
	if n >= 8 {
		info = line[tabs[6]+1 : tabs[7]]
	} else {
		info = line[tabs[6]+1:]
	}
	return chrom, pos, ref, alt, info, nil
}

// skipVCFAlt 是 test/buildfull 的 ALT 过滤口径。
func skipVCFAlt(alt []byte) bool {
	return len(alt) == 0 || alt[0] == '<' || alt[0] == '*' || alt[0] == '.' ||
		bytes.ContainsAny(alt, "[]")
}

// ---- 分染色体落盘 ----

// buildState 是多文件模式的取消标志与首个错误。
type buildState struct {
	canceled atomic.Bool
	mu       sync.Mutex
	err      error
}

func (s *buildState) fail(err error) {
	s.mu.Lock()
	if s.err == nil {
		s.err = err
	}
	s.mu.Unlock()
	s.canceled.Store(true)
}

func (s *buildState) firstErr() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.err
}

// vcfShardBuilder 管理一个输入文件的记录到分染色体 writer 的推进。
type vcfShardBuilder struct {
	outdir string
	opts   BuildOptions

	selectedFields []valueField
	schema         Schema
	recordEncoder  *RecordEncoder
	fixed          int // -1：跟随 CHROM 块；>=0：多文件模式只允许该染色体

	cur  int
	w    *Writer
	seen [25]bool

	hdr       *vcfHeader
	seenInfo  []uint32
	gen       uint32
	buildID   [16]byte
	stats     SourceInfoOrder
	nonFinite int64 // 非有限 Float 按缺失处理的次数（诊断）
	srcLast   int
	srcBad    bool

	idx     map[string]int
	vals    [][]byte
	has     []bool
	touched []int
	lineNo  int
}

func newVCFShardBuilder(outdir string, plan *vcfPlan, opts BuildOptions, fixed int) *vcfShardBuilder {
	b := &vcfShardBuilder{
		outdir: outdir, opts: opts,
		selectedFields: plan.selectedFields,
		schema:         plan.schema,
		recordEncoder:  NewRecordEncoder(plan.schema),
		fixed:          fixed, cur: -1,
		hdr: plan.header, seenInfo: make([]uint32, len(plan.header.infoOrder)),
		buildID: plan.buildID,
	}
	b.idx = make(map[string]int, len(b.selectedFields))
	for i := range b.selectedFields {
		b.idx[b.selectedFields[i].id] = i
	}
	b.vals = make([][]byte, len(b.selectedFields))
	b.has = make([]bool, len(b.selectedFields))
	return b
}

// addLine 处理一行 VCF 数据。
func (b *vcfShardBuilder) addLine(line []byte) error {
	b.lineNo++
	if n := len(line); n > 0 && line[n-1] == '\r' {
		line = line[:n-1]
	}
	if len(line) == 0 {
		return nil
	}
	chrom, pos, ref, alt, info, err := splitVCFLine(line)
	if err != nil {
		return fmt.Errorf("line %d: %w", b.lineNo, err)
	}
	cid, ok := ChromID(string(chrom))
	if !ok {
		return nil // 未知 contig：跳过
	}
	if bytes.Equal(ref, []byte(".")) {
		return nil
	}
	p, err := strconv.ParseUint(string(pos), 10, 32)
	if err != nil {
		return fmt.Errorf("line %d: bad POS %q: %w", b.lineNo, pos, err)
	}
	nValid := 0
	for _, a := range bytes.Split(alt, []byte(",")) {
		if !skipVCFAlt(a) {
			nValid++
		}
	}
	if nValid == 0 {
		return nil
	}
	if b.fixed >= 0 && int(cid) != b.fixed {
		return fmt.Errorf("line %d: expected chromosome %s, found %s",
			b.lineNo, ChromName(uint8(b.fixed)), ChromName(cid))
	}
	if int(cid) != b.cur {
		if b.fixed < 0 {
			if b.seen[cid] {
				return fmt.Errorf("line %d: chromosome %s block is not contiguous",
					b.lineNo, ChromName(cid))
			}
			b.seen[cid] = true
		}
		if err := b.finishCurrent(); err != nil {
			return err
		}
		b.stats = SourceInfoOrder{}
		b.nonFinite = 0
		w, err := Create(filepath.Join(b.outdir, "chr"+ChromName(cid)), CreateOptions{
			Schema:        b.schema,
			RawValueBelow: b.opts.RawValueBelow,
			PackTarget:    b.opts.PackTarget,
		})
		if err != nil {
			return err
		}
		b.w = w
		b.cur = int(cid)
	}
	if err := b.parseInfo(info); err != nil {
		return fmt.Errorf("line %d: %w", b.lineNo, err)
	}
	group := PosKey(cid, uint32(p))
	for altIndex, altAllele := range bytes.Split(alt, []byte(",")) {
		if skipVCFAlt(altAllele) {
			continue
		}
		record, err := b.buildRecord(altIndex)
		if err != nil {
			return fmt.Errorf("line %d: %w", b.lineNo, err)
		}
		key := VarKey(cid, uint32(p), string(ref), string(altAllele))
		if err := b.w.AddSorted(group, key, record); err != nil {
			return fmt.Errorf("line %d: %w", b.lineNo, err)
		}
	}
	return nil
}

// parseInfo 把当前记录的 INFO 解析进 b.vals/b.has（只关心选中字段），同时
// 校验整条 INFO：未知/重复字段、空段、Flag 带值、非 Flag 缺值都返回错误。
func (b *vcfShardBuilder) parseInfo(info []byte) error {
	for _, fi := range b.touched {
		b.vals[fi] = nil
		b.has[fi] = false
	}
	b.touched = b.touched[:0]
	b.gen++
	b.srcLast, b.srcBad = -1, false
	if len(info) == 0 || (len(info) == 1 && info[0] == '.') {
		b.endRecordOrder()
		return nil
	}
	rest := info
	for len(rest) > 0 {
		var seg []byte
		if i := bytes.IndexByte(rest, ';'); i >= 0 {
			seg, rest = rest[:i], rest[i+1:]
		} else {
			seg, rest = rest, nil
		}
		if len(seg) == 0 {
			return errors.New("empty INFO segment")
		}
		eq := bytes.IndexByte(seg, '=')
		key := seg
		var v []byte
		if eq >= 0 {
			key, v = seg[:eq], seg[eq+1:]
		}
		if len(key) == 0 {
			return errors.New("empty INFO field name")
		}
		d, ok := b.hdr.info[string(key)]
		if !ok {
			return fmt.Errorf("unknown INFO field %q", key)
		}
		b.noteInfoOrder(d)
		if b.seenInfo[d.order] == b.gen {
			return fmt.Errorf("duplicate INFO field %q", key)
		}
		b.seenInfo[d.order] = b.gen
		if d.isFlag && eq >= 0 {
			return fmt.Errorf("Flag INFO field %q has a value", key)
		}
		if !d.isFlag && eq < 0 {
			return fmt.Errorf("non-Flag INFO field %q has no value", key)
		}
		if fi, ok := b.idx[string(key)]; ok {
			if !b.has[fi] {
				b.touched = append(b.touched, fi)
			}
			b.has[fi] = true
			b.vals[fi] = v
		}
	}
	b.endRecordOrder()
	return nil
}

// noteInfoOrder 记录源 INFO 顺序是否与 ##INFO 声明序一致；只作诊断统计。
func (b *vcfShardBuilder) noteInfoOrder(d *infoDef) {
	if d.order < b.srcLast {
		b.srcBad = true
	}
	b.srcLast = d.order
}

// endRecordOrder 结算当前记录的源顺序统计。
func (b *vcfShardBuilder) endRecordOrder() {
	if b.srcBad {
		b.stats.Bad++
	} else {
		b.stats.OK++
	}
}

// buildRecord 把一个 ALT 的字段值编码成 v003 record。
func (b *vcfShardBuilder) buildRecord(altIndex int) ([]byte, error) {
	b.recordEncoder.Reset()
	for fieldIndex := range b.selectedFields {
		if !b.has[fieldIndex] {
			continue
		}
		field := &b.selectedFields[fieldIndex]
		value := b.vals[fieldIndex]
		if field.number == "A" {
			var ok bool
			value, ok = commaElem(value, altIndex)
			if !ok {
				continue
			}
		}
		if field.isFlag {
			b.recordEncoder.Flag(field.prefixed)
			continue
		}
		if missingVCFValue(value) {
			continue
		}
		switch field.typ {
		case "Integer":
			if isArrayNumber(field.number) {
				if err := b.setIntegerArray(field, value); err != nil {
					return nil, err
				}
				continue
			}
			parsed, err := strconv.ParseInt(string(value), 10, 64)
			if err != nil {
				return nil, fmt.Errorf("field %q value %q: %w", field.id, value, err)
			}
			b.recordEncoder.Int(field.prefixed, parsed)
		case "Float":
			if isArrayNumber(field.number) {
				if err := b.setFloatArray(field, value); err != nil {
					return nil, err
				}
				continue
			}
			parsed, err := strconv.ParseFloat(string(value), 64)
			if err != nil {
				return nil, fmt.Errorf("field %q value %q: %w", field.id, value, err)
			}
			if math.IsNaN(parsed) || math.IsInf(parsed, 0) {
				b.nonFinite++
				continue
			}
			b.recordEncoder.Float(field.prefixed, parsed)
		case "String":
			b.recordEncoder.Bytes(field.prefixed, value)
		default:
			return nil, fmt.Errorf("field %q has unsupported type %q", field.id, field.typ)
		}
	}
	return b.recordEncoder.Encode()
}

func isArrayNumber(number string) bool {
	switch number {
	case "R", "G", ".":
		return true
	}
	return false
}

func missingVCFValue(value []byte) bool {
	return len(value) == 0 || (len(value) == 1 && value[0] == '.')
}

func (b *vcfShardBuilder) setIntegerArray(field *valueField, value []byte) error {
	elements := bytes.Split(value, []byte(","))
	values := make([]Value, len(elements))
	for i := range elements {
		if missingVCFValue(elements[i]) {
			continue
		}
		parsed, err := strconv.ParseInt(string(elements[i]), 10, 64)
		if err != nil {
			return fmt.Errorf("field %q element %q: %w", field.id, elements[i], err)
		}
		values[i] = Value{Type: TypeInteger, Int: parsed}
	}
	b.recordEncoder.Values(field.prefixed, values)
	return nil
}

func (b *vcfShardBuilder) setFloatArray(field *valueField, value []byte) error {
	elements := bytes.Split(value, []byte(","))
	values := make([]Value, len(elements))
	for i := range elements {
		if missingVCFValue(elements[i]) {
			continue
		}
		parsed, err := strconv.ParseFloat(string(elements[i]), 64)
		if err != nil {
			return fmt.Errorf("field %q element %q: %w", field.id, elements[i], err)
		}
		if math.IsNaN(parsed) || math.IsInf(parsed, 0) {
			b.nonFinite++
			continue
		}
		values[i] = Value{Type: TypeFloat, Float: parsed}
	}
	b.recordEncoder.Values(field.prefixed, values)
	return nil
}

// commaElem 返回逗号分隔值的第 n 个元素；元素可以是空串。
func commaElem(v []byte, n int) ([]byte, bool) {
	start := 0
	for i := 0; i <= len(v); i++ {
		if i == len(v) || v[i] == ',' {
			if n == 0 {
				return v[start:i], true
			}
			n--
			start = i + 1
		}
	}
	return nil, false
}

// finishCurrent 落盘当前染色体的 writer。
func (b *vcfShardBuilder) finishCurrent() error {
	if b.w == nil {
		return nil
	}
	w := b.w
	b.w = nil
	if err := w.Finish(); err != nil {
		return err
	}
	base := filepath.Join(b.outdir, "chr"+ChromName(uint8(b.cur)))
	return writeColumnar(base, b.schema, b.buildID, b.stats, b.nonFinite, colBinWidth)
}

// finish 结束构建；一条可建记录都没有时报错。
func (b *vcfShardBuilder) finish() error {
	if b.w == nil {
		return errors.New("no buildable records")
	}
	return b.finishCurrent()
}

// abort 清理未完成的 writer：关编码器、删 .tmp。
func (b *vcfShardBuilder) abort() {
	if b.w != nil {
		b.w.Abort()
		b.w = nil
	}
}

// buildVCFShardsSingle 是单文件模式：顺序读，CHROM 块变化时切 writer。
func buildVCFShardsSingle(outdir, path string, plan *vcfPlan, opts BuildOptions) error {
	r, err := openVCF(path, 0)
	if err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	defer r.Close()
	if _, _, err := readVCFHeader(r.br, false); err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	b := newVCFShardBuilder(outdir, plan, opts, -1)
	defer b.abort()
	sc := bufio.NewScanner(r.br)
	sc.Buffer(make([]byte, 64*1024), maxIngestLine)
	for sc.Scan() {
		if err := b.addLine(sc.Bytes()); err != nil {
			return fmt.Errorf("%s: %w", path, err)
		}
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	if err := b.finish(); err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	return nil
}

// buildVCFShardsParallel 是多文件模式：一个文件一条染色体，按文件并行。
// 每个文件内部是单线程 writer，文件级并发取 GOMAXPROCS/2：太少压不满 CPU，
// 太多会把每文件摊薄到半核以下，最大染色体反而拖长总工期。
func buildVCFShardsParallel(outdir string, plan *vcfPlan, opts BuildOptions) error {
	workers := runtime.GOMAXPROCS(0) / 2
	if workers < 1 {
		workers = 1
	}
	if workers > len(plan.inputs) {
		workers = len(plan.inputs)
	}
	var state buildState
	var wg sync.WaitGroup
	sem := make(chan struct{}, workers)
	for _, in := range plan.inputs {
		// 先在调度循环里拿槽再起 goroutine：否则 23 个 goroutine 抢同一个
		// channel，谁先拿到槽由调度决定，按大小排序就失效了。
		sem <- struct{}{}
		wg.Add(1)
		go func(in vcfInput) {
			defer wg.Done()
			defer func() { <-sem }()
			if err := buildOneVCFShard(outdir, in, plan, opts, &state); err != nil {
				state.fail(err)
			}
		}(in)
	}
	wg.Wait()
	return state.firstErr()
}

// buildOneVCFShard 建一个文件的染色体库。
func buildOneVCFShard(outdir string, in vcfInput, plan *vcfPlan, opts BuildOptions, state *buildState) error {
	r, err := openVCF(in.path, 1)
	if err != nil {
		return fmt.Errorf("%s: %w", in.path, err)
	}
	defer r.Close()
	if _, _, err := readVCFHeader(r.br, false); err != nil {
		return fmt.Errorf("%s: %w", in.path, err)
	}
	b := newVCFShardBuilder(outdir, plan, opts, int(in.cid))
	defer b.abort()
	sc := bufio.NewScanner(r.br)
	sc.Buffer(make([]byte, 64*1024), maxIngestLine)
	for sc.Scan() {
		if state.canceled.Load() {
			return nil
		}
		if err := b.addLine(sc.Bytes()); err != nil {
			return fmt.Errorf("%s: %w", in.path, err)
		}
	}
	if err := sc.Err(); err != nil {
		return fmt.Errorf("%s: %w", in.path, err)
	}
	if state.canceled.Load() {
		return nil
	}
	if err := b.finish(); err != nil {
		return fmt.Errorf("%s: %w", in.path, err)
	}
	return nil
}

// ---- header 落盘 ----

// buildImmkvHeader 生成 vcf.immkv.header：fileformat + 选中字段的 ##INFO
// （ID 加前缀，按 ##INFO 声明顺序）+ 无样本的 #CHROM 行。
func buildImmkvHeader(fileFormat string, selectedFields []valueField) []byte {
	if fileFormat == "" {
		fileFormat = "##fileformat=VCFv4.2"
	}
	out := make([]byte, 0, len(fileFormat)+64*len(selectedFields)+64)
	out = append(out, fileFormat...)
	out = append(out, '\n')
	for i := range selectedFields {
		out = append(out, prefixInfoLine(selectedFields[i].defLine, selectedFields[i].prefixed)...)
		out = append(out, '\n')
	}
	out = append(out, "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n"...)
	return out
}

// prefixInfoLine 把 ##INFO 声明里的 ID 属性值替换为 prefixed。
func prefixInfoLine(line []byte, prefixed string) []byte {
	for i := 0; i+4 <= len(line); i++ {
		if (line[i] == '<' || line[i] == ',') && bytes.HasPrefix(line[i+1:], []byte("ID=")) {
			start := i + 1 + 3
			end := start
			for end < len(line) && line[end] != ',' && line[end] != '>' {
				end++
			}
			out := make([]byte, 0, len(line)+len(prefixed))
			out = append(out, line[:start]...)
			out = append(out, prefixed...)
			out = append(out, line[end:]...)
			return out
		}
	}
	return line
}

// writeFileAtomic 写临时文件、fsync、rename。
func writeFileAtomic(path string, data []byte) error {
	tmp := path + ".tmp"
	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	_, err = f.Write(data)
	if err == nil {
		err = f.Sync()
	}
	if cerr := f.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		os.Remove(tmp)
		return err
	}
	return nil
}

files.iouring_linux.go:
//go:build linux

package immkv

import (
	"fmt"
	"os"
	"sync"
	"sync/atomic"
	"syscall"
	"unsafe"

	"golang.org/x/sys/unix"
)

// io_uring 直连 + O_DIRECT：值文件以 O_DIRECT 打开（绕开页缓存——3GiB cgroup
// 下缓冲读的页缓存记账回收会把单读延迟拖到 ~220µs），读请求经 512 深的提交
// 队列异步下发，单个驱动 goroutine 完成提交与收割——在途读深度与线程数彻底
// 解耦，线程预算仍由 StreamOptions.Threads 约束在解压池上。O_DIRECT 要求 4KB 对齐：
// 每段读 [对齐下界, 对齐上界)，命中视图按段内偏移切出。建环或 O_DIRECT 不可
// 用时 GetBatch 退回 pread 读池。要求内核 ≥5.6。

const (
	ioringOpRead       = 22
	ioringEnterGetEvts = 1
	ioringOffSQRing    = 0
	ioringOffCQRing    = 0x8000000
	ioringOffSQEs      = 0x10000000
	sysIoringSetup     = 425
	sysIoringEnter     = 426

	directAlign = 4096 // O_DIRECT 逻辑块对齐
)

type ioringSQOffsets struct {
	head, tail, ringMask, ringEntries, flags, dropped, array, resv1 uint32
	resv2                                                           uint64
}

type ioringCQOffsets struct {
	head, tail, ringMask, ringEntries, overflow, cqes, flags, resv1 uint32
	resv2                                                           uint64
}

type ioringParams struct {
	sqEntries, cqEntries, flags, sqThreadCPU, sqThreadIdle, features, wqFd uint32
	resv                                                                   [3]uint32
	sqOff                                                                  ioringSQOffsets
	cqOff                                                                  ioringCQOffsets
}

type ioringSQE struct {
	opcode      uint8
	flags       uint8
	ioprio      uint16
	fd          int32
	off         uint64
	addr        uint64
	len         uint32
	rwFlags     uint32
	userData    uint64
	bufIndex    uint16
	personality uint16
	spliceFdIn  int32
	addr3       uint64
	pad         [8]byte
}

type ioringCQE struct {
	userData uint64
	res      int32
	flags    uint32
}

// ioUring 持有一套已 mmap 的 SQ/CQ 环。非并发安全：由单个驱动 goroutine
// 独占（GetBatch 每次调用自建自毁，跨调用天然隔离）。
type ioUring struct {
	fd      int
	sqMask  uint32
	cqMask  uint32
	sqHead  *uint32 // SQ：内核已消费位置（只读）
	sqTail  *uint32 // SQ：本端发布位置（写）
	sqArray []uint32
	cqHead  *uint32 // CQ：本端收割位置（写）
	cqTail  *uint32 // CQ：内核写位置（只读）
	cqes    []ioringCQE
	sqes    []ioringSQE
	sqeTail uint32 // 下一个待发布的 SQE 序号（单调递增，槽 = 序号 & mask）
	mmaps   [3][]byte
}

func newIOUring(entries uint32) (*ioUring, error) {
	var p ioringParams
	fd, _, errno := syscall.Syscall(sysIoringSetup, uintptr(entries), uintptr(unsafe.Pointer(&p)), 0)
	if errno != 0 {
		return nil, errno
	}
	r := &ioUring{fd: int(fd)}
	mk := func(off int64, sz int) ([]byte, error) {
		return unix.Mmap(r.fd, off, sz, syscall.PROT_READ|syscall.PROT_WRITE, syscall.MAP_SHARED|syscall.MAP_POPULATE)
	}
	sqSize := int(p.sqOff.array) + int(p.sqEntries)*4
	cqSize := int(p.cqOff.cqes) + int(p.cqEntries)*int(unsafe.Sizeof(ioringCQE{}))
	sqeSize := int(p.sqEntries) * int(unsafe.Sizeof(ioringSQE{}))
	var err error
	if r.mmaps[0], err = mk(ioringOffSQRing, sqSize); err != nil {
		r.close()
		return nil, err
	}
	if r.mmaps[1], err = mk(ioringOffCQRing, cqSize); err != nil {
		r.close()
		return nil, err
	}
	if r.mmaps[2], err = mk(ioringOffSQEs, sqeSize); err != nil {
		r.close()
		return nil, err
	}
	sq, cq := r.mmaps[0], r.mmaps[1]
	ptr := func(b []byte, off uint32) *uint32 {
		return (*uint32)(unsafe.Add(unsafe.Pointer(&b[0]), int(off)))
	}
	r.sqHead = ptr(sq, p.sqOff.head)
	r.sqTail = ptr(sq, p.sqOff.tail)
	r.sqMask = *ptr(sq, p.sqOff.ringMask)
	r.sqArray = unsafe.Slice((*uint32)(unsafe.Add(unsafe.Pointer(&sq[0]), int(p.sqOff.array))), int(p.sqEntries))
	r.cqHead = ptr(cq, p.cqOff.head)
	r.cqTail = ptr(cq, p.cqOff.tail)
	r.cqMask = *ptr(cq, p.cqOff.ringMask)
	r.cqes = unsafe.Slice((*ioringCQE)(unsafe.Add(unsafe.Pointer(&cq[0]), int(p.cqOff.cqes))), int(p.cqEntries))
	r.sqes = unsafe.Slice((*ioringSQE)(unsafe.Add(unsafe.Pointer(&r.mmaps[2][0]), 0)), int(p.sqEntries))
	return r, nil
}

func (r *ioUring) close() {
	for i, m := range r.mmaps {
		if m != nil {
			syscall.Munmap(m)
			r.mmaps[i] = nil
		}
	}
	if r.fd >= 0 {
		syscall.Close(r.fd)
		r.fd = -1
	}
}

// inFlightSQEs 报已提交未回收槽位的 SQE 数（决定还能不能继续排）。
func (r *ioUring) inFlightSQEs() uint32 {
	return r.sqeTail - atomic.LoadUint32(r.sqHead)
}

// prep 排一个读请求；SQ 满时先 submitWait(0) 腾槽。
func (r *ioUring) prep(f *os.File, off uint64, buf []byte, userData uint64) error {
	if int(r.inFlightSQEs()) >= len(r.sqes) {
		if err := r.submitWait(0); err != nil {
			return err
		}
	}
	idx := r.sqeTail & r.sqMask
	r.sqes[idx] = ioringSQE{
		opcode:   ioringOpRead,
		fd:       int32(f.Fd()),
		off:      off,
		addr:     uint64(uintptr(unsafe.Pointer(&buf[0]))),
		len:      uint32(len(buf)),
		userData: userData,
	}
	r.sqArray[idx] = idx
	r.sqeTail++
	return nil
}

// submitWait 提交全部已排 SQE；minComplete > 0 时阻塞等至少这么多完成事件。
// Go 的异步抢占信号（SIGURG）会以 EINTR 打断 enter，按惯例重试。
func (r *ioUring) submitWait(minComplete uint32) error {
	pending := r.sqeTail - atomic.LoadUint32(r.sqTail)
	if pending > 0 {
		atomic.StoreUint32(r.sqTail, r.sqeTail) // store-release：SQE 与数组项先行
	}
	if pending == 0 && minComplete == 0 {
		return nil
	}
	for {
		_, _, errno := syscall.Syscall6(sysIoringEnter, uintptr(r.fd), uintptr(pending),
			uintptr(minComplete), ioringEnterGetEvts, 0, 0)
		if errno == 0 {
			return nil
		}
		if errno != syscall.EINTR {
			return errno
		}
	}
}

// reap 收割全部已完成 CQE（无阻塞），逐个回调。
func (r *ioUring) reap(fn func(userData uint64, res int32)) {
	head := atomic.LoadUint32(r.cqHead)
	tail := atomic.LoadUint32(r.cqTail)
	n := 0
	for head != tail {
		cqe := &r.cqes[head&r.cqMask]
		fn(cqe.userData, cqe.res)
		head++
		n++
	}
	if n > 0 {
		atomic.StoreUint32(r.cqHead, head)
	}
}

// directBufPools 按 2 的幂分桶的 4KB 对齐读缓冲（8K–256K）。对齐在块创建时
// 一次达成，复用不破坏；块容量即桶大小，归还按容量分桶。
var directBufPools [6]sync.Pool

func directBucket(n int) int {
	b := 8 << 10
	i := 0
	for b < n && i < len(directBufPools)-1 {
		b <<= 1
		i++
	}
	return i
}

const directMaxBucket = 256 << 10

// getDirectBuf 取一块 4KB 对齐、长度 n 的缓冲；超过最大桶（256KB，读段合并
// 的上限是 4MB）就现配现弃，对齐照做。
func getDirectBuf(n int) []byte {
	if n > directMaxBucket {
		raw := make([]byte, n+directAlign)
		off := int((-uintptr(unsafe.Pointer(&raw[0]))) & (directAlign - 1))
		return raw[off : off+n : n]
	}
	i := directBucket(n)
	if v := directBufPools[i].Get(); v != nil {
		return (*v.(*[]byte))[:n]
	}
	size := 8 << 10 << i
	raw := make([]byte, size+directAlign)
	off := int((-uintptr(unsafe.Pointer(&raw[0]))) & (directAlign - 1))
	b := raw[off : off+size : size] // 4KB 对齐、cap == 桶大小
	return b[:n]
}

// putDirectBuf 归还对齐缓冲（按容量分桶；超桶的不收）。
func putDirectBuf(b []byte) {
	if cap(b) > directMaxBucket {
		return
	}
	directBufPools[directBucket(cap(b))].Put(&b)
}

// driveDirect 是 O_DIRECT + io_uring 路径的读驱动（独占 ring 的唯一 goroutine），
// 事件循环：①非阻塞收新块，为每段算对齐区间、取对齐缓冲、排 SQE ②提交
// ③收割 CQE，整块完成的挂进 ready ④ready 非阻塞投给 decCh——投递绝不阻塞
// 驱动，CQ 才能持续收割不溢出；无事可做且在途非空时 enter(WAIT) 睡等完成。
// userData 打包为 块号<<8|段号（块 ≤64 段）。任何错误调 fail 后退出，在途
// 请求随 ring 销毁作废。
func driveDirect(r *ioUring, extCh <-chan []extent, decCh chan<- []extent,
	abort <-chan struct{}, fail func(error)) {

	type cstate struct {
		chunk []extent
		left  int
	}
	pending := map[uint64]*cstate{}
	ready := make([]*cstate, 0, 16)
	var nextUD uint64
	drained := false
	dead := false
	dfail := func(err error) {
		dead = true
		fail(err)
	}

	prep := func(ch []extent) {
		st := &cstate{chunk: ch, left: 0}
		ud := nextUD
		nextUD++
		pending[ud] = st
		for i := range ch {
			e := &ch[i]
			last := e.hits[len(e.hits)-1]
			e.size = last.valOff + uint64(last.frameLen) - e.off
			if e.size == 0 {
				continue // 零长裸存帧独占的段：无需读
			}
			// O_DIRECT 对齐区间与命中视图
			lo := e.off &^ (directAlign - 1)
			hi := (e.off + e.size + directAlign - 1) &^ (directAlign - 1)
			e.dbuf = getDirectBuf(int(hi - lo))
			e.buf = e.dbuf[e.off-lo : e.off-lo+e.size]
			e.dNeed = int32(e.off - lo + e.size)
			e.direct = true
			if err := r.prep(e.s.vfDirect, lo, e.dbuf, ud<<8|uint64(i)); err != nil {
				dfail(err)
				return
			}
			st.left++
		}
		if st.left == 0 {
			delete(pending, ud)
			ready = append(ready, st)
		}
	}
	complete := func(udFull uint64, res int32) {
		st := pending[udFull>>8]
		if st == nil {
			return
		}
		e := &st.chunk[udFull&0xFF]
		// 对齐读可能越过文件尾：EOF 短读合法，覆盖到所需字节即成功
		if res < 0 || res < e.dNeed {
			fail(fmt.Errorf("immkv: O_DIRECT 读失败：res=%d need=%d", res, e.dNeed))
			dead = true
			return
		}
		st.left--
		if st.left == 0 {
			delete(pending, udFull>>8)
			ready = append(ready, st)
		}
	}
	dispatch := func() bool {
		sent := false
		for len(ready) > 0 {
			st := ready[0]
			select {
			case decCh <- st.chunk:
				ready = ready[1:]
				sent = true
			default:
				return sent
			}
		}
		return sent
	}

	for {
		if dead {
			return
		}
		// ① 非阻塞收新块：SQ 有富余槽位才收
		for !drained && int(r.inFlightSQEs())+64 <= len(r.sqes) {
			var ch []extent
			var ok bool
			select {
			case ch, ok = <-extCh:
				if !ok {
					drained = true
					break
				}
				prep(ch)
			default:
				ok = false
				ch = nil
			}
			if ch == nil {
				break
			}
		}
		// ② 提交
		if err := r.submitWait(0); err != nil {
			dfail(err)
			return
		}
		// ③ 收割
		r.reap(complete)
		// ④ 非阻塞投递
		dispatch()
		// ⑤ 推进或等待（任何路径要么有进展要么睡，禁止空转）
		if drained && len(pending) == 0 && len(ready) == 0 {
			return
		}
		if len(pending) > 0 {
			if err := r.submitWait(1); err != nil {
				dfail(err)
				return
			}
			continue
		}
		if len(ready) > 0 {
			st := ready[0]
			select {
			case decCh <- st.chunk:
				ready = ready[1:]
			case <-abort:
				return
			}
			continue
		}
		select {
		case ch, ok := <-extCh:
			if !ok {
				drained = true
				continue
			}
			prep(ch)
		case <-abort:
			return
		}
	}
}

