files.key.go:
// key.go 是 immkv 的键编码：染色体号 + 位置 + 碱基，保证字节序 = 基因组自然序。
// 编码与 immdb 时期逐字节一致（既有键集文件与全部对照数字都依赖它）。

package immkv

import (
	"encoding/binary"
	"strconv"
	"strings"
)

// ChromID 把 VCF/TSV 里的染色体名映射为键首字节：1..22 → 0..21、X → 22、
// Y → 23、M/MT → 24（带不带 chr 前缀都认）。首字节序 = 染色体自然序。
// 其余 contig（chrUn_*、*_alt、随机片段等）返回 false，调用方自行跳过。
func ChromID(s string) (uint8, bool) {
	name := strings.TrimPrefix(strings.TrimPrefix(s, "chr"), "CHR")
	if n, err := strconv.ParseUint(name, 10, 8); err == nil {
		if n >= 1 && n <= 22 {
			return uint8(n - 1), true
		}
		return 0, false
	}
	switch strings.ToUpper(name) {
	case "X":
		return 22, true
	case "Y":
		return 23, true
	case "M", "MT":
		return 24, true
	}
	return 0, false
}

// ChromName 是 ChromID 的反函数：chromID → 染色体名（文件名与 VCF 列共用）。
func ChromName(id uint8) string {
	switch {
	case id <= 21:
		return strconv.Itoa(int(id) + 1)
	case id == 22:
		return "X"
	case id == 23:
		return "Y"
	case id == 24:
		return "M"
	}
	return "?"
}

// VarKey 编码排序键：[chromID][pos 大端 u32][ref][0x00][alt]。
func VarKey(c uint8, p uint32, ref, alt string) []byte {
	k := make([]byte, 0, 7+len(ref)+1+len(alt))
	k = append(k, c)
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], p)
	k = append(k, b[:]...)
	k = append(k, ref...)
	k = append(k, 0)
	return append(k, alt...)
}

// PosKey 编码位置前缀：[chromID][pos 大端 u32]。
func PosKey(c uint8, p uint32) []byte {
	k := make([]byte, 5)
	k[0] = c
	binary.BigEndian.PutUint32(k[1:], p)
	return k
}

files.manifest.go:
// manifest.go 是 v003 的 base.manifest 读写层。manifest 是 schema 的权威
// 副本，也是 vals/col/keys 三个文件与记录数的配对凭据；旧 v001 manifest
// 直接拒绝，不做双解码。
package immkv

import (
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const (
	manifestFormat  = "immkv-v003"
	manifestVersion = 3
)

// ManifestField 是 manifest 里的一项 schema 字段；Column 必须等于下标。
type ManifestField struct {
	Name   string `json:"name"`
	Column int    `json:"column"`
	Type   string `json:"type"`
	Number string `json:"number"`
}

// SourceInfoOrder 是构建期源 INFO 顺序的统计，只作诊断。
type SourceInfoOrder struct {
	OK  int64 `json:"ok"`
	Bad int64 `json:"bad"`
}

// Manifest 是 base.manifest 的 JSON 形态。
type Manifest struct {
	Format          string          `json:"format"`
	Version         int             `json:"version"`
	Base            string          `json:"base"`
	BuildID         string          `json:"build_id"`
	BinWidth        uint32          `json:"bin_width"`
	RecordCount     uint64          `json:"record_count"`
	KeysBytes       int64           `json:"keys_bytes"`
	ValsBytes       int64           `json:"vals_bytes"`
	ColBytes        int64           `json:"col_bytes"`
	SchemaHash      string          `json:"schema_hash"`
	Fields          []ManifestField `json:"fields"`
	SourceInfoOrder SourceInfoOrder `json:"source_info_order"`
	// NonFiniteFloats 是构建期遇到 NaN/Inf 并按缺失处理的 Float 次数；只作诊断。
	NonFiniteFloats int64 `json:"non_finite_floats"`
}

// NewManifest 建一份 v003 manifest 骨架；Fields、Column 与 schema hash 由
// SetSchema 写入。Base 是文件名前缀（如 chr1），不是路径。
func NewManifest(base string, fields []Field) (*Manifest, error) {
	if len(fields) == 0 {
		return nil, fmt.Errorf("immkv: manifest 没有字段")
	}
	m := &Manifest{Base: base}
	if err := m.SetSchema(fields); err != nil {
		return nil, err
	}
	return m, nil
}

// SetSchema 用字段表重写 manifest 的 Fields、Column 与 schema hash。
func (m *Manifest) SetSchema(fields []Field) error {
	s := Schema(fields)
	if err := s.Validate(); err != nil {
		return err
	}
	m.Format = manifestFormat
	m.Version = manifestVersion
	m.Fields = make([]ManifestField, len(fields))
	for i := range fields {
		m.Fields[i] = ManifestField{
			Name:   fields[i].Name,
			Column: i,
			Type:   fields[i].Type.String(),
			Number: fields[i].Number,
		}
	}
	m.SchemaHash = s.HashHex()
	return nil
}

// Schema 把 manifest 的字段条目还原成 schema，并校验 Column/Type/Number。
func (m *Manifest) Schema() (Schema, error) {
	s := make(Schema, len(m.Fields))
	for i := range m.Fields {
		mf := &m.Fields[i]
		if mf.Column != i {
			return nil, fmt.Errorf("immkv: manifest 字段 %q 的 column %d ≠ %d", mf.Name, mf.Column, i)
		}
		t, ok := parseFieldType(mf.Type)
		if !ok {
			return nil, fmt.Errorf("immkv: manifest 字段 %q 的类型 %q 未知", mf.Name, mf.Type)
		}
		s[i] = Field{Name: mf.Name, Type: t, Number: mf.Number}
	}
	if err := s.Validate(); err != nil {
		return nil, err
	}
	return s, nil
}

// Validate 校验 manifest 的格式、schema hash、配对字段与字节数。
func (m *Manifest) Validate() error {
	if m.Format != manifestFormat || m.Version != manifestVersion {
		return fmt.Errorf("immkv: manifest format/version 不合法")
	}
	if m.Base == "" || m.Base == "." || m.Base == ".." || filepath.Base(m.Base) != m.Base {
		return fmt.Errorf("immkv: manifest base %q 不合法", m.Base)
	}
	if len(m.Fields) == 0 {
		return fmt.Errorf("immkv: manifest 没有字段")
	}
	if len(m.BuildID) != 32 {
		return fmt.Errorf("immkv: manifest build_id %q 长度不是 32", m.BuildID)
	}
	if _, err := hex.DecodeString(m.BuildID); err != nil {
		return fmt.Errorf("immkv: manifest build_id %q 不是十六进制", m.BuildID)
	}
	s, err := m.Schema()
	if err != nil {
		return err
	}
	if len(m.SchemaHash) != 16 {
		return fmt.Errorf("immkv: manifest schema_hash %q 长度不是 16", m.SchemaHash)
	}
	if _, err := hex.DecodeString(m.SchemaHash); err != nil {
		return fmt.Errorf("immkv: manifest schema_hash %q 不是十六进制", m.SchemaHash)
	}
	if !strings.EqualFold(m.SchemaHash, s.HashHex()) {
		return fmt.Errorf("immkv: manifest schema hash 不匹配")
	}
	if m.KeysBytes < 0 || m.ValsBytes < 0 || m.ColBytes < 0 {
		return fmt.Errorf("immkv: manifest 文件字节数为负")
	}
	if m.SourceInfoOrder.OK < 0 || m.SourceInfoOrder.Bad < 0 {
		return fmt.Errorf("immkv: manifest source_info_order 为负")
	}
	if m.NonFiniteFloats < 0 {
		return fmt.Errorf("immkv: manifest non_finite_floats 为负")
	}
	return nil
}

// ReadManifest 读 base.manifest 并校验；旧 v001/v002 manifest 直接拒绝。
func ReadManifest(path string) (*Manifest, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var m Manifest
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, fmt.Errorf("immkv: %s: 解析 manifest: %w", path, err)
	}
	if m.Format != manifestFormat || m.Version != manifestVersion {
		return nil, fmt.Errorf("immkv: %s: v003 不兼容旧格式，请重建", path)
	}
	if err := m.Validate(); err != nil {
		return nil, fmt.Errorf("immkv: %s: %w", path, err)
	}
	return &m, nil
}

// ReadSchema 读库目录里任意一个 shard 的 manifest，返回整库 schema。
// 所有 shard 的 schema 必须一致；一个 manifest 都找不到时报错。
// 需要 shard 级诊断信息（build id、记录数、字节数）时用 ReadManifest。
func ReadSchema(dir string) (Schema, error) {
	if dir == "" {
		return nil, fmt.Errorf("immkv: ReadSchema: empty dir")
	}
	var (
		schema Schema
		hash   string
		first  string
	)
	for id := uint8(0); id <= 24; id++ {
		path := filepath.Join(dir, "chr"+ChromName(id)+".manifest")
		m, err := ReadManifest(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, err
		}
		if first == "" {
			s, err := m.Schema()
			if err != nil {
				return nil, err
			}
			schema, hash, first = s, m.SchemaHash, path
			continue
		}
		if !strings.EqualFold(hash, m.SchemaHash) {
			return nil, fmt.Errorf("immkv: %s 与 %s 的 schema 不一致", first, path)
		}
	}
	if first == "" {
		return nil, fmt.Errorf("immkv: %s 下没有 chr*.manifest", dir)
	}
	return schema, nil
}

// WriteManifest 校验后原子写 base.manifest。
func WriteManifest(path string, m *Manifest) error {
	raw, err := marshalManifest(m)
	if err != nil {
		return err
	}
	return writeFileAtomic(path, raw)
}

func marshalManifest(m *Manifest) ([]byte, error) {
	if err := m.Validate(); err != nil {
		return nil, err
	}
	raw, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(raw, '\n'), nil
}

files.record.go:
// record.go 是 v003 的 record 编解码：record = bitmap + typed payload。
// 读侧公开 Record 视图，按字段名取值；写侧公开 RecordEncoder。两边共用
// 同一套编码，RenderRecord 只负责把 record 规范化为 INFO 文本。
package immkv

import (
	"encoding/binary"
	"fmt"
	"iter"
	"math"
	"strconv"
)

// Value 是 Record.Values 回调的一项。Type 为 0 表示数组里的缺失元素；
// 数组字段用 Elems，标量字段用 Int/Float/Bytes。Bytes 是 raw record 的
// 视图，不复制，有效期由调用方持有的 record 字节决定。
type Value struct {
	Type  FieldType
	Int   int64
	Float float64
	Bytes []byte
	Elems []Value
}

// Record 是 raw record 的只读视图。NewRecord 校验结构；校验通过后，
// HasValue/Int/Float/Bytes 与 Values 不再返回错误。
type Record struct {
	schema Schema
	raw    []byte
}

// NewRecord 校验 raw 是否是 schema 的一条完整 record。raw 不被复制；
// 调用方要保证 raw 在 Record 使用期间有效。
func NewRecord(s Schema, raw []byte) (Record, error) {
	if err := validateRecord(s, raw); err != nil {
		return Record{}, err
	}
	return Record{schema: s, raw: raw}, nil
}

// HasValue 表示这条 record 里该字段是否有值。字段名不在 schema 时 panic。
func (r Record) HasValue(name string) bool {
	i, _ := r.field(name)
	return r.bit(i)
}

// Int 读 Integer 标量。字段缺失返回 0；调用方应先问 HasValue。
// 字段不是 Integer 或属于数组时 panic。
func (r Record) Int(name string) int64 {
	i, f := r.field(name)
	if f.Type != TypeInteger {
		panic("immkv: field " + name + " is not Integer")
	}
	if f.isArray() {
		panic("immkv: field " + name + " is an array; use Values()")
	}
	if !r.bit(i) {
		return 0
	}
	return r.valueAt(i, f).Int
}

// Float 读 Float 标量。字段缺失返回 0；调用方应先问 HasValue。
func (r Record) Float(name string) float64 {
	i, f := r.field(name)
	if f.Type != TypeFloat {
		panic("immkv: field " + name + " is not Float")
	}
	if f.isArray() {
		panic("immkv: field " + name + " is an array; use Values()")
	}
	if !r.bit(i) {
		return 0
	}
	return r.valueAt(i, f).Float
}

// Bytes 读 String 标量的原字节。字段缺失返回 nil；返回的是 raw record
// 的视图，不复制。
func (r Record) Bytes(name string) []byte {
	i, f := r.field(name)
	if f.Type != TypeString {
		panic("immkv: field " + name + " is not String")
	}
	if !r.bit(i) {
		return nil
	}
	return r.valueAt(i, f).Bytes
}

// Values 按 schema 顺序产出有值字段，字段缺失不产出。数组字段的 Value
// 带 Elems；Elems 里的零 Value 表示缺失元素。标量路径不分配。
func (r Record) Values() iter.Seq2[Field, Value] {
	return func(yield func(Field, Value) bool) {
		p := r.raw[recordBitmapLen(len(r.schema)):]
		for i := range r.schema {
			if !r.bit(i) {
				continue
			}
			f := r.schema[i]
			v, rest, err := decodeValue(f, p, true)
			if err != nil {
				panic("immkv: record 已损坏: " + err.Error())
			}
			p = rest
			if !yield(f, v) {
				return
			}
		}
	}
}

func (r Record) field(name string) (int, Field) {
	i := r.schema.Index(name)
	if i < 0 {
		panic("immkv: unknown field " + name)
	}
	return i, r.schema[i]
}

func (r Record) bit(i int) bool {
	if i < 0 || i >= len(r.schema) {
		panic("immkv: field index out of range")
	}
	return bitAt(r.raw, i)
}

// payloadAt 跳到第 i 个字段的 payload 起点。前面有值字段按编码跳过；
// 数组走 skipValue，不分配 Elems。
func (r Record) payloadAt(i int) ([]byte, error) {
	p := r.raw[recordBitmapLen(len(r.schema)):]
	for j := 0; j < i; j++ {
		if !r.bit(j) {
			continue
		}
		var err error
		p, err = skipValue(r.schema[j], p)
		if err != nil {
			return nil, fmt.Errorf("字段 %q: %w", r.schema[j].Name, err)
		}
	}
	return p, nil
}

func (r Record) valueAt(i int, f Field) Value {
	p, err := r.payloadAt(i)
	if err != nil {
		panic("immkv: record 已损坏: " + err.Error())
	}
	v, _, err := decodeValue(f, p, true)
	if err != nil {
		panic("immkv: record 已损坏: " + err.Error())
	}
	return v
}

// RenderRecord 把 record 规范化为 INFO 文本：字段顺序 = schema 顺序，
// Flag 写 name，数组逗号连接，缺失元素写 '.'，全缺写 '.'。
func RenderRecord(s Schema, raw []byte) ([]byte, error) {
	rec, err := NewRecord(s, raw)
	if err != nil {
		return nil, err
	}
	var out []byte
	first := true
	for f, v := range rec.Values() {
		if !first {
			out = append(out, ';')
		}
		first = false
		out = append(out, f.Name...)
		switch f.Type {
		case TypeFlag:
			continue
		case TypeInteger, TypeFloat, TypeString:
			out = append(out, '=')
			if f.isArray() {
				out = appendArray(out, v)
			} else {
				out = appendScalar(out, f.Type, v)
			}
		}
	}
	if len(out) == 0 {
		out = append(out, '.')
	}
	return out, nil
}

func appendScalar(dst []byte, t FieldType, v Value) []byte {
	switch t {
	case TypeInteger:
		return strconv.AppendInt(dst, v.Int, 10)
	case TypeFloat:
		return strconv.AppendFloat(dst, v.Float, 'g', -1, 64)
	case TypeString:
		return append(dst, v.Bytes...)
	default:
		return dst
	}
}

func appendArray(dst []byte, v Value) []byte {
	if len(v.Elems) == 0 {
		return append(dst, '.')
	}
	for i := range v.Elems {
		if i > 0 {
			dst = append(dst, ',')
		}
		e := v.Elems[i]
		if e.Type == 0 {
			dst = append(dst, '.')
			continue
		}
		dst = appendScalar(dst, e.Type, e)
	}
	return dst
}

// RecordEncoder 按字段名收集一条 record 的值，Encode 按 schema 顺序落成
// bitmap + payload。Encode 返回的 buf 归 encoder 所有，下一次 Encode/Reset
// 会覆盖；要保留就拷贝。
type RecordEncoder struct {
	schema    Schema
	index     map[string]int
	schemaErr error

	set     []bool
	vals    []encValue
	bitmap  []uint64
	buf     []byte
	scratch []byte
	err     error
}

type encValue struct {
	i     int64
	f     float64
	b     []byte
	elems []Value
}

// NewRecordEncoder 为一份 schema 建编码器。schema 的校验错误延迟到 Encode
// 返回；字段名在构造时解析一次。
func NewRecordEncoder(s Schema) *RecordEncoder {
	e := &RecordEncoder{
		schema:    s,
		index:     make(map[string]int, len(s)),
		schemaErr: s.Validate(),
		set:       make([]bool, len(s)),
		vals:      make([]encValue, len(s)),
		bitmap:    make([]uint64, (len(s)+63)/64),
	}
	for i := range s {
		e.index[s[i].Name] = i
	}
	return e
}

// Reset 清空上一条 record 的值，复用 buffer 与 bitmap。
func (e *RecordEncoder) Reset() *RecordEncoder {
	for i := range e.set {
		e.set[i] = false
		e.vals[i] = encValue{}
	}
	e.buf = e.buf[:0]
	e.err = nil
	return e
}

func (e *RecordEncoder) fail(format string, args ...any) {
	if e.err == nil {
		e.err = fmt.Errorf(format, args...)
	}
}

func (e *RecordEncoder) field(name string, want FieldType, array bool) (int, bool) {
	i, ok := e.index[name]
	if !ok {
		e.fail("immkv: unknown field %q", name)
		return 0, false
	}
	f := e.schema[i]
	if f.Type != want {
		e.fail("immkv: field %q is %s, not %s", name, f.Type, want)
		return 0, false
	}
	if f.isArray() != array {
		e.fail("immkv: field %q array=%v, not %v", name, f.isArray(), array)
		return 0, false
	}
	return i, true
}

// Int 设置一个 Integer 标量字段。
func (e *RecordEncoder) Int(name string, v int64) *RecordEncoder {
	i, ok := e.field(name, TypeInteger, false)
	if ok {
		e.set[i] = true
		e.vals[i] = encValue{i: v}
	}
	return e
}

// Float 设置一个 Float 标量字段；NaN/Inf 在 Encode 时返回错误。
func (e *RecordEncoder) Float(name string, v float64) *RecordEncoder {
	i, ok := e.field(name, TypeFloat, false)
	if !ok {
		return e
	}
	if math.IsNaN(v) || math.IsInf(v, 0) {
		e.fail("immkv: field %q float is NaN or Inf", name)
		return e
	}
	e.set[i] = true
	e.vals[i] = encValue{f: v}
	return e
}

// Bytes 设置一个 String 字段；Encode 时复制进输出 buffer。
func (e *RecordEncoder) Bytes(name string, v []byte) *RecordEncoder {
	i, ok := e.field(name, TypeString, false)
	if ok {
		e.set[i] = true
		e.vals[i] = encValue{b: v}
	}
	return e
}

// Flag 置位一个 Flag 字段。
func (e *RecordEncoder) Flag(name string) *RecordEncoder {
	i, ok := e.field(name, TypeFlag, false)
	if ok {
		e.set[i] = true
	}
	return e
}

// Values 设置一个 Number 为 R、G、. 的数值数组字段。elems 里的零 Value
// 表示缺失元素；缺整个字段就不要调用。
func (e *RecordEncoder) Values(name string, elems []Value) *RecordEncoder {
	i, ok := e.index[name]
	if !ok {
		e.fail("immkv: unknown field %q", name)
		return e
	}
	f := e.schema[i]
	if !f.isArray() {
		e.fail("immkv: field %q is not an array", name)
		return e
	}
	for k := range elems {
		el := &elems[k]
		if el.Type == 0 {
			if len(el.Elems) != 0 {
				e.fail("immkv: field %q element %d is missing but has Elems", name, k)
				return e
			}
			continue
		}
		if el.Type != f.Type {
			e.fail("immkv: field %q element %d is %s, not %s", name, k, el.Type, f.Type)
			return e
		}
		if len(el.Elems) != 0 {
			e.fail("immkv: field %q element %d has nested Elems", name, k)
			return e
		}
		if f.Type == TypeFloat && (math.IsNaN(el.Float) || math.IsInf(el.Float, 0)) {
			e.fail("immkv: field %q element %d float is NaN or Inf", name, k)
			return e
		}
	}
	e.set[i] = true
	e.vals[i] = encValue{elems: elems}
	return e
}

// Encode 按 schema 顺序写 bitmap + payload。返回的 buffer 由 encoder 持有。
func (e *RecordEncoder) Encode() ([]byte, error) {
	if e.schemaErr != nil {
		return nil, e.schemaErr
	}
	if e.err != nil {
		return nil, e.err
	}
	for i := range e.bitmap {
		e.bitmap[i] = 0
	}
	for i := range e.set {
		if e.set[i] {
			e.bitmap[i>>6] |= uint64(1) << uint(i&63)
		}
	}
	e.buf = e.buf[:0]
	for _, w := range e.bitmap {
		e.buf = binary.LittleEndian.AppendUint64(e.buf, w)
	}
	for i := range e.schema {
		if !e.set[i] {
			continue
		}
		f := e.schema[i]
		v := &e.vals[i]
		switch f.Type {
		case TypeFlag:
			// 只占位图，没有 payload。
		case TypeString:
			e.buf = binary.AppendUvarint(e.buf, uint64(len(v.b)))
			e.buf = append(e.buf, v.b...)
		case TypeInteger:
			if f.isArray() {
				e.buf = e.appendIntArray(e.buf, v.elems)
			} else {
				e.buf = binary.AppendUvarint(e.buf, zigzagEncode(v.i))
			}
		case TypeFloat:
			if f.isArray() {
				e.buf = e.appendFloatArray(e.buf, v.elems)
			} else {
				e.buf = binary.LittleEndian.AppendUint64(e.buf, math.Float64bits(v.f))
			}
		default:
			return nil, fmt.Errorf("immkv: field %q has invalid type %d", f.Name, f.Type)
		}
	}
	return e.buf, nil
}

func (e *RecordEncoder) appendIntArray(dst []byte, elems []Value) []byte {
	dst = binary.AppendUvarint(dst, uint64(len(elems)))
	for k := range elems {
		el := &elems[k]
		if el.Type == 0 {
			dst = binary.AppendUvarint(dst, 0)
			continue
		}
		e.scratch = binary.AppendUvarint(e.scratch[:0], zigzagEncode(el.Int))
		dst = binary.AppendUvarint(dst, uint64(len(e.scratch)))
		dst = append(dst, e.scratch...)
	}
	return dst
}

func (e *RecordEncoder) appendFloatArray(dst []byte, elems []Value) []byte {
	dst = binary.AppendUvarint(dst, uint64(len(elems)))
	for k := range elems {
		el := &elems[k]
		if el.Type == 0 {
			dst = binary.AppendUvarint(dst, 0)
			continue
		}
		dst = binary.AppendUvarint(dst, 8)
		dst = binary.LittleEndian.AppendUint64(dst, math.Float64bits(el.Float))
	}
	return dst
}

func zigzagEncode(v int64) uint64 {
	return uint64(v)<<1 ^ uint64(v>>63)
}

func zigzagDecode(u uint64) int64 {
	return int64(u>>1) ^ -int64(u&1)
}

func recordBitmapLen(n int) int {
	return ((n + 63) / 64) * 8
}

func bitAt(raw []byte, i int) bool {
	w := i >> 6
	return binary.LittleEndian.Uint64(raw[w*8:])&(uint64(1)<<uint(i&63)) != 0
}

func validateRecord(s Schema, raw []byte) error {
	return walkRecord(s, raw, nil)
}

// projectRecord 返回只含 selected 列的 record：位图长度不变，未选字段按缺失
// 处理，payload 按 schema 顺序重排。selected 的长度必须等于 len(s)；全选时
// 结果与输入逐字节一致。
func projectRecord(s Schema, raw []byte, selected []bool) ([]byte, error) {
	bl := recordBitmapLen(len(s))
	out := make([]byte, bl, bl+len(raw))
	var payload []byte
	err := walkRecord(s, raw, func(i int, p []byte) error {
		if !selected[i] {
			return nil
		}
		out[i>>3] |= 1 << uint(i&7) // 位图按字节寻址（小端字内的位序与 bitAt 一致）
		payload = append(payload, p...)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return append(out, payload...), nil
}

// walkRecord 校验 record 结构，并按 schema 顺序把每个有值字段的编码 payload
// 交给 fn。payload 是 raw 的视图，数组不展开；fn 为 nil 时只校验。
func walkRecord(s Schema, raw []byte, fn func(index int, payload []byte) error) error {
	bl := recordBitmapLen(len(s))
	if len(raw) < bl {
		return fmt.Errorf("immkv: record 位图长度 %d < %d", len(raw), bl)
	}
	p := raw[bl:]
	for i := range s {
		if !bitAt(raw, i) {
			continue
		}
		before := len(p)
		rest, err := skipValue(s[i], p)
		if err != nil {
			return fmt.Errorf("immkv: 字段 %q: %w", s[i].Name, err)
		}
		if fn != nil {
			if err := fn(i, p[:before-len(rest)]); err != nil {
				return err
			}
		}
		p = rest
	}
	if len(p) != 0 {
		return fmt.Errorf("immkv: record 尾部有 %d 字节多余数据", len(p))
	}
	return nil
}

func skipValue(f Field, p []byte) ([]byte, error) {
	_, rest, err := decodeValue(f, p, false)
	return rest, err
}

// decodeValue 解一个字段。want=false 时不收集数组元素，只校验并跳过；
// 标量路径不分配。
func decodeValue(f Field, p []byte, want bool) (Value, []byte, error) {
	switch f.Type {
	case TypeFlag:
		return Value{Type: TypeFlag}, p, nil
	case TypeString:
		l, rest, err := readLen(p)
		if err != nil {
			return Value{}, nil, err
		}
		return Value{Type: TypeString, Bytes: rest[:l]}, rest[l:], nil
	case TypeInteger, TypeFloat:
		if f.isArray() {
			return decodeArray(f, p, want)
		}
		return decodeScalar(f, p)
	default:
		return Value{}, nil, fmt.Errorf("未知字段类型 %d", f.Type)
	}
}

func decodeScalar(f Field, p []byte) (Value, []byte, error) {
	switch f.Type {
	case TypeInteger:
		u, n := binary.Uvarint(p)
		if n <= 0 {
			return Value{}, nil, fmt.Errorf("integer uvarint 截断或溢出")
		}
		return Value{Type: TypeInteger, Int: zigzagDecode(u)}, p[n:], nil
	case TypeFloat:
		if len(p) < 8 {
			return Value{}, nil, fmt.Errorf("float 需要 8 字节，剩 %d", len(p))
		}
		v := math.Float64frombits(binary.LittleEndian.Uint64(p))
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return Value{}, nil, fmt.Errorf("float 是 NaN 或 Inf")
		}
		return Value{Type: TypeFloat, Float: v}, p[8:], nil
	default:
		return Value{}, nil, fmt.Errorf("字段 %q 不是标量类型", f.Name)
	}
}

func decodeArray(f Field, p []byte, want bool) (Value, []byte, error) {
	count, n := binary.Uvarint(p)
	if n <= 0 {
		return Value{}, nil, fmt.Errorf("数组 count 截断或溢出")
	}
	p = p[n:]
	if count > uint64(len(p)) {
		return Value{}, nil, fmt.Errorf("数组 count %d 超过剩余 %d 字节", count, len(p))
	}
	var elems []Value
	if want {
		elems = make([]Value, int(count))
	}
	for k := 0; k < int(count); k++ {
		l, rest, err := readLen(p)
		if err != nil {
			return Value{}, nil, err
		}
		if l > 0 {
			elem := rest[:l]
			switch f.Type {
			case TypeInteger:
				u, en := binary.Uvarint(elem)
				if en <= 0 {
					return Value{}, nil, fmt.Errorf("数组元素 %d integer 截断或溢出", k)
				}
				if en != len(elem) {
					return Value{}, nil, fmt.Errorf("数组元素 %d integer 长度 %d ≠ %d", k, en, len(elem))
				}
				if want {
					elems[k] = Value{Type: TypeInteger, Int: zigzagDecode(u)}
				}
			case TypeFloat:
				if l != 8 {
					return Value{}, nil, fmt.Errorf("数组元素 %d float 长度 %d ≠ 8", k, l)
				}
				v := math.Float64frombits(binary.LittleEndian.Uint64(elem))
				if math.IsNaN(v) || math.IsInf(v, 0) {
					return Value{}, nil, fmt.Errorf("数组元素 %d float 是 NaN 或 Inf", k)
				}
				if want {
					elems[k] = Value{Type: TypeFloat, Float: v}
				}
			default:
				return Value{}, nil, fmt.Errorf("数组元素类型 %s 不支持", f.Type)
			}
			_ = elem
		}
		p = rest[l:]
	}
	return Value{Type: f.Type, Elems: elems}, p, nil
}

func readLen(p []byte) (int, []byte, error) {
	l, n := binary.Uvarint(p)
	if n <= 0 {
		return 0, nil, fmt.Errorf("uvarint 截断或溢出")
	}
	if l > uint64(len(p)-n) {
		return 0, nil, fmt.Errorf("长度 %d 超过剩余 %d 字节", l, len(p)-n)
	}
	return int(l), p[n:], nil
}

