// schema.go 定义 v003 的 schema：有序字段表、字段类型、Number 校验与
// schema hash。schema 的权威副本落在 base.manifest；这里只提供类型和
// 纯函数，不碰盘上读写。
package immkv

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

// FieldType 是一个 schema 字段的物理类型。
type FieldType uint8

const (
	// TypeInteger 是 int64，盘上 zigzag uvarint。
	TypeInteger FieldType = iota + 1
	// TypeFloat 是 float64，盘上 8 字节 IEEE 754 小端。
	TypeFloat
	// TypeString 是原字节，盘上 uvarint(len) + bytes。
	TypeString
	// TypeFlag 没有 payload，只占 record 位图的一位。
	TypeFlag
)

// String 返回 manifest 里的类型名。
func (t FieldType) String() string {
	switch t {
	case TypeInteger:
		return "Integer"
	case TypeFloat:
		return "Float"
	case TypeString:
		return "String"
	case TypeFlag:
		return "Flag"
	default:
		return fmt.Sprintf("FieldType(%d)", uint8(t))
	}
}

func parseFieldType(s string) (FieldType, bool) {
	switch s {
	case "Integer":
		return TypeInteger, true
	case "Float":
		return TypeFloat, true
	case "String":
		return TypeString, true
	case "Flag":
		return TypeFlag, true
	default:
		return 0, false
	}
}

// Field 是 schema 的一项；Name 已加过 prefix，Number 是 VCF 的原文。
type Field struct {
	Name   string
	Type   FieldType
	Number string
}

// Schema 是有序字段表；顺序即 record 位图的位号。
type Schema []Field

// Validate 校验字段表。空 schema 合法（对应零字段 record），但 manifest
// 会另外要求至少一个字段。
func (s Schema) Validate() error {
	seen := make(map[string]bool, len(s))
	for i := range s {
		f := &s[i]
		if f.Name == "" {
			return fmt.Errorf("immkv: schema 第 %d 个字段名为空", i)
		}
		if seen[f.Name] {
			return fmt.Errorf("immkv: schema 字段 %q 重复", f.Name)
		}
		seen[f.Name] = true

		switch f.Type {
		case TypeFlag:
			if f.Number != "0" {
				return fmt.Errorf("immkv: Flag 字段 %q 的 Number 必须是 0，得到 %q", f.Name, f.Number)
			}
		case TypeInteger, TypeFloat, TypeString:
			switch f.Number {
			case "1", "A", "R", "G", ".":
			case "0":
				return fmt.Errorf("immkv: 字段 %q 的 Number=0 只能是 Flag", f.Name)
			default:
				return fmt.Errorf("immkv: 字段 %q 的 Number %q 不合法", f.Name, f.Number)
			}
		default:
			return fmt.Errorf("immkv: 字段 %q 的类型 %d 不合法", f.Name, f.Type)
		}
	}
	return nil
}

// Index 返回字段名的位号；不存在返回 -1。
func (s Schema) Index(name string) int {
	for i := range s {
		if s[i].Name == name {
			return i
		}
	}
	return -1
}

// Hash 按 schema 顺序对 "name\tType\tNumber\n" 取 SHA-256 前 8 字节。
func (s Schema) Hash() [8]byte {
	h := sha256.New()
	for i := range s {
		fmt.Fprintf(h, "%s\t%s\t%s\n", s[i].Name, s[i].Type.String(), s[i].Number)
	}
	var out [8]byte
	copy(out[:], h.Sum(nil))
	return out
}

// HashHex 返回 Hash 的十六进制形态，manifest 里存这个。
func (s Schema) HashHex() string {
	h := s.Hash()
	return hex.EncodeToString(h[:])
}

// isArray 表示该字段在 record 里是否按数组编码。只有 Number 为 R、G、.
// 的数值字段是数组；String 永远是原字节，A 已按 ALT 下标取成标量。
func (f Field) isArray() bool {
	if f.Type != TypeInteger && f.Type != TypeFloat {
		return false
	}
	switch f.Number {
	case "R", "G", ".":
		return true
	}
	return false
}

files.shard.go:
// shard.go 是 immkv 的读侧之一：分染色体分片、OpenEager 句柄、解压缓存。
//
// 每条染色体一个 shard：两个只读文件句柄（.keys/.vals），锚点索引打开时一次
// pread 全量读入常驻；组（1024 条记录）与值帧按需 pread，OpenEager 配 LRU
// 缓存组窗口与解压值。键首字节（chromID）路由到对应 shard，Scan 跨染色体按
// chromID 序拼接。

package immkv

import (
	"bytes"
	"container/list"
	"encoding/binary"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"sync"
	"unsafe"

	"github.com/klauspost/compress/zstd"
)

// ---- 解压缓存：分片 LRU（结构移植自 immdb，缓存对象从 []byte 泛化为 any） ----

const lruShards = 16

type lruEnt struct {
	key  int64
	blob any
	size int
}

type lruShard struct {
	mu   sync.Mutex
	cap  int
	used int
	m    map[int64]*list.Element
	l    *list.List
	_pad [64]byte // 隔离相邻分片 mutex 的缓存行（假共享）
}

type lruCache struct {
	shards [lruShards]lruShard
}

func newLRU(capBytes int) *lruCache {
	c := &lruCache{}
	per := capBytes / lruShards
	for i := range c.shards {
		c.shards[i].cap = per
		c.shards[i].m = make(map[int64]*list.Element)
		c.shards[i].l = list.New()
	}
	return c
}

func (c *lruCache) shard(k int64) *lruShard {
	// splitmix64 终结混合：键本身低位带结构（文件偏移），直接取模会全部
	// 挤进同一分片
	h := uint64(k)
	h ^= h >> 33
	h *= 0xff51afd7ed558ccd
	h ^= h >> 33
	return &c.shards[h%lruShards]
}

func (c *lruCache) get(k int64) (any, bool) {
	s := c.shard(k)
	s.mu.Lock()
	defer s.mu.Unlock()
	if el, ok := s.m[k]; ok {
		s.l.MoveToFront(el)
		return el.Value.(*lruEnt).blob, true
	}
	return nil, false
}

func (c *lruCache) add(k int64, v any, size int) {
	s := c.shard(k)
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.m[k]; ok {
		return
	}
	s.m[k] = s.l.PushFront(&lruEnt{k, v, size})
	s.used += size
	for s.used > s.cap && s.l.Len() > 1 {
		el := s.l.Back()
		ent := el.Value.(*lruEnt)
		s.l.Remove(el)
		delete(s.m, ent.key)
		s.used -= ent.size
	}
}

// frameDecoder 是值帧解压后端的窄接口：decode 把 src 的解压结果追加进 dst
// 返回（dst 容量够时零分配）；Close 释放后端资源。两个实现：libzstd CGO
// （zstdcgo_cgo.go，DDict 常驻、并发安全）与 klauspost 纯 Go（kpDecoder）。
// 帧格式标准互通，后端按 CGO 可用性与建器成败择一。
type frameDecoder interface {
	decode(src, dst []byte) ([]byte, error)
	Close() error
}

// kpDecoder 把 klauspost 解码器适配到 frameDecoder。
type kpDecoder struct {
	dec *zstd.Decoder
}

func (k *kpDecoder) decode(src, dst []byte) ([]byte, error) {
	return k.dec.DecodeAll(src, dst)
}

func (k *kpDecoder) Close() error {
	k.dec.Close()
	return nil
}

// ---- 单染色体 shard ----

type shard struct {
	kf, vf   *os.File
	vfDirect *os.File // O_DIRECT 值文件句柄；不可用为 nil（流式深队列读用）
	count    uint64
	nBlock   uint32
	recsBlk  uint64
	indexOff uint64
	blkPfx   []uint64 // 块首键 8B 前缀（大端装载，零填充），比较语义与全键一致
	blkOff   []uint64 // 每块在 keys 文件里的偏移
	keysEnd  uint64   // 键流数据区终点（= indexOff）
	dec      frameDecoder
	cache    *lruCache // OpenEager 用；nil = 不缓存（OpenStreaming 不用它）
}

func openShard(base string, cache *lruCache) (*shard, error) {
	kf, err := os.Open(base + ".keys")
	if err != nil {
		return nil, err
	}
	vf, err := os.Open(base + ".vals")
	if err != nil {
		kf.Close()
		return nil, err
	}
	s := &shard{kf: kf, vf: vf, cache: cache}
	// O_DIRECT 可选句柄：不支持（EINVAL 等）只是退回缓冲读，不算错
	if df, err := openDirect(base + ".vals"); err == nil {
		s.vfDirect = df
	}
	fail := func(err error) (*shard, error) {
		kf.Close()
		vf.Close()
		if s.vfDirect != nil {
			s.vfDirect.Close()
		}
		return nil, err
	}
	var kh [headerSize]byte
	if _, err := kf.ReadAt(kh[:], 0); err != nil {
		return fail(err)
	}
	if string(kh[0:8]) != keysMagic {
		return fail(errors.New("immkv: bad keys magic: " + base))
	}
	if v := binary.LittleEndian.Uint32(kh[8:12]); v != 1 {
		return fail(fmt.Errorf("immkv: keys version %d ≠ 1", v))
	}
	if v := binary.LittleEndian.Uint16(kh[20:22]); uint64(v) != recsPerBlock {
		return fail(fmt.Errorf("immkv: recsPerBlock %d ≠ %d", v, recsPerBlock))
	}
	s.count = binary.LittleEndian.Uint64(kh[12:20])
	s.recsBlk = recsPerBlock
	s.nBlock = binary.LittleEndian.Uint32(kh[24:28])
	s.indexOff = binary.LittleEndian.Uint64(kh[28:36])
	s.keysEnd = s.indexOff
	var vh [headerSize]byte
	if _, err := vf.ReadAt(vh[:], 0); err != nil {
		return fail(err)
	}
	if string(vh[0:8]) != valsMagic {
		return fail(errors.New("immkv: bad vals magic: " + base))
	}
	if v := binary.LittleEndian.Uint32(vh[8:12]); v != 3 {
		return fail(fmt.Errorf("immkv: vals version %d ≠ 3", v))
	}
	if v := binary.LittleEndian.Uint64(vh[12:20]); v != s.count {
		return fail(fmt.Errorf("immkv: vals count %d ≠ keys count %d", v, s.count))
	}
	// 块索引一次读入常驻：[prefix 8B ×N][blockOff 8B ×N]。分配前先校验
	// 偏移与字节数，坏头（越界/负长度）返回错误而不是 panic。
	st, err := kf.Stat()
	if err != nil {
		return fail(err)
	}
	if s.indexOff < headerSize || s.indexOff+16*uint64(s.nBlock) != uint64(st.Size()) {
		return fail(fmt.Errorf("immkv: %s: keys 块索引区 [%d, %d) 与文件 %d B 不符",
			base+".keys", s.indexOff, s.indexOff+16*uint64(s.nBlock), st.Size()))
	}
	ib := make([]byte, 16*uint64(s.nBlock))
	if _, err := kf.ReadAt(ib, int64(s.indexOff)); err != nil {
		return fail(err)
	}
	s.blkPfx = make([]uint64, s.nBlock)
	s.blkOff = make([]uint64, s.nBlock)
	prevOff := uint64(0)
	for i := uint32(0); i < s.nBlock; i++ {
		s.blkPfx[i] = binary.BigEndian.Uint64(ib[8*i:])
		off := binary.LittleEndian.Uint64(ib[8*uint64(s.nBlock)+8*uint64(i):])
		// 块偏移必须落在数据区内且单调递增，否则 block() 的窗口长度会算负
		if off < headerSize || off >= s.indexOff || (i > 0 && off < prevOff) {
			return fail(fmt.Errorf("immkv: %s: 块 %d 偏移 %d 不合法（索引区起点 %d）",
				base+".keys", i, off, s.indexOff))
		}
		s.blkOff[i] = off
		prevOff = off
	}
	// 每值成帧构建的库在 vals 头里嵌训练字典；有字典的库 CGO 可用时解压走
	// libzstd DDict。无字典的 v2 打包库保留 klauspost：实测 gozstd 解 64KB
	// 打包帧即使 dst 给足也不快过 klauspost（4096/1：977ms 对 867ms；65536/4：
	// 586ms 对 562ms，ClinVar 键集 A/B 两轮），还省一个 96KB 缓冲桶；点查路径
	// 两者无差（p50 同 300ns）。
	var dict []byte
	decOpts := []zstd.DOption{zstd.IgnoreChecksum(true)} // 帧完整性由文件保证，跳过 xxhash 校验
	if dictLen := binary.LittleEndian.Uint32(vh[20:24]); dictLen > 0 {
		dictOff := binary.LittleEndian.Uint64(vh[24:32])
		dict = make([]byte, dictLen)
		if _, err := vf.ReadAt(dict, int64(dictOff)); err != nil {
			return fail(err)
		}
		decOpts = append(decOpts, zstd.WithDecoderDicts(dict))
	}
	var dec frameDecoder
	if len(dict) > 0 {
		dec, _ = newCGODictDecoder(dict)
	}
	if dec == nil {
		kd, derr := zstd.NewReader(nil, decOpts...)
		if derr != nil {
			return fail(derr)
		}
		dec = &kpDecoder{dec: kd}
	}
	s.dec = dec
	return s, nil
}

// Close 关闭文件句柄与解码器。shard 不可再用。
func (s *shard) Close() error {
	s.dec.Close()
	err := s.kf.Close()
	if ce := s.vf.Close(); err == nil {
		err = ce
	}
	if s.vfDirect != nil {
		if ce := s.vfDirect.Close(); err == nil {
			err = ce
		}
	}
	return err
}

// blockEnt 是一个微块的解析结果：视图指向窗口/缓存持有的 buf；cum[i] 是
// 第 i 条记录相对 baseValOff 的偏移（share 位不计增量），valOff_i = base+cum[i]。
type blockEnt struct {
	n       int
	keyEnds []uint32
	lens    []uint32
	base    uint64
	keys    []byte
	cum     []uint64
	buf     []byte
}

// keyAt 返回块内第 j 条键（视图）。
func (e *blockEnt) keyAt(j int) []byte {
	lo := uint32(0)
	if j > 0 {
		lo = e.keyEnds[j-1]
	}
	return e.keys[lo:e.keyEnds[j]]
}

// valLoc 返回块内第 j 条的值帧定位。
func (e *blockEnt) valLoc(j int) (valOff uint64, frameLen uint32, raw, packed bool) {
	l := e.lens[j]
	return e.base + e.cum[j], l & frameLenMask, l&flagRaw != 0, l&flagPacked != 0
}

// parseBlockView 从 buf 起点解析微块的零分配视图：keyEnds/lens/keys 都是 buf
// 的子切片，不含 cum（随机访问的偏移前缀和由块持有方另行构建）。流式顺扫用
// 这个——全量一轮 410 万块，逐块分配会把 GC 打爆。
type blockView struct {
	n       int
	base    uint64
	keyEnds []uint32
	lens    []uint32
	keys    []byte
}

func (v *blockView) keyAt(j int) []byte {
	lo := uint32(0)
	if j > 0 {
		lo = v.keyEnds[j-1]
	}
	return v.keys[lo:v.keyEnds[j]]
}

// valOffAt 从块内第 from 条（已知其 valOff）推导第 to 条的 valOff：
// to 条带 share 位则偏移不动，否则累加前一条帧长（≤64 步）。
func (v *blockView) valOffAt(from, to int, fromOff uint64) uint64 {
	off := fromOff
	for i := from; i < to && i+1 < v.n; i++ {
		if v.lens[i+1]&flagShare == 0 {
			off += uint64(v.lens[i] & frameLenMask)
		}
	}
	return off
}

func parseBlockView(buf []byte, n int) (blockView, int, error) {
	if n < 1 {
		return blockView{}, 0, errors.New("immkv: 空微块")
	}
	if len(buf) < 8*n+8 {
		return blockView{}, 0, errors.New("immkv: 微块头不足")
	}
	v := blockView{n: n}
	v.keyEnds = unsafe.Slice((*uint32)(unsafe.Add(unsafe.Pointer(&buf[0]), 0)), n)
	lensAt := 4 * n
	v.lens = unsafe.Slice((*uint32)(unsafe.Add(unsafe.Pointer(&buf[0]), lensAt)), n)
	v.base = binary.LittleEndian.Uint64(buf[8*n:])
	// keyEnds 必须非降（允许零长键）且末项在键区内；否则 keyAt 的切片
	// 会高位小于低位而 panic。逐项校验，不只看末项。
	for i := 1; i < n; i++ {
		if v.keyEnds[i] < v.keyEnds[i-1] {
			return blockView{}, 0, fmt.Errorf("immkv: 微块 keyEnds 第 %d 项 %d < 前项 %d", i, v.keyEnds[i], v.keyEnds[i-1])
		}
	}
	keyLen := int(v.keyEnds[n-1])
	if len(buf) < 8*n+8+keyLen {
		return blockView{}, 0, errors.New("immkv: 微块键区不足")
	}
	v.keys = buf[8*n+8 : 8*n+8+keyLen]
	return v, 8*n + 8 + keyLen, nil
}

// parseBlock 从 buf 起点解析一个 n 条记录的微块（含 cum），返回块与占用字节数。
// eager 点查用（块进 LRU，解析成本一次性）。
func parseBlock(buf []byte, n int) (*blockEnt, int, error) {
	v, used, err := parseBlockView(buf, n)
	if err != nil {
		return nil, 0, err
	}
	e := &blockEnt{n: v.n, base: v.base, keyEnds: v.keyEnds, lens: v.lens, keys: v.keys, buf: buf}
	// cum[i] = 第 i 条相对 base 的偏移：第 i 条带 share 位（与上一条同帧）
	// 则不加第 i−1 条的帧长，否则加（零长帧自然推进 0）
	e.cum = make([]uint64, n+1)
	for i := 1; i <= n; i++ {
		e.cum[i] = e.cum[i-1]
		if i < n && e.lens[i]&flagShare == 0 {
			e.cum[i] += uint64(e.lens[i-1] & frameLenMask)
		}
	}
	return e, used, nil
}

// nRecs 返回第 b 块的记录数（末块可短）。
func (s *shard) nRecs(b int) int {
	n := int(s.count - uint64(b)*s.recsBlk)
	if n > int(s.recsBlk) {
		n = int(s.recsBlk)
	}
	return n
}

// block 取第 b 块（LRU 缓存，键取块偏移正值域）；读取或解析失败返回错误。
func (s *shard) block(b int) (*blockEnt, error) {
	ck := int64(s.blkOff[b])
	if s.cache != nil {
		if v, ok := s.cache.get(ck); ok {
			return v.(*blockEnt), nil
		}
	}
	hi := s.keysEnd
	if b+1 < int(s.nBlock) {
		hi = s.blkOff[b+1]
	}
	buf := make([]byte, hi-s.blkOff[b])
	if _, err := s.kf.ReadAt(buf, int64(s.blkOff[b])); err != nil {
		return nil, fmt.Errorf("immkv: 读微块 %d: %w", b, err)
	}
	e, _, err := parseBlock(buf, s.nRecs(b))
	if err != nil {
		return nil, fmt.Errorf("immkv: 解析微块 %d: %w", b, err)
	}
	if s.cache != nil {
		s.cache.add(ck, e, len(buf)+len(e.cum)*8+64)
	}
	return e, nil
}

// key8 把键前 8 字节按大端装进 u64（不足补零），供块索引二分。
func key8(key []byte) uint64 {
	var b [8]byte
	copy(b[:], key)
	return binary.BigEndian.Uint64(b[:])
}

// blockFor 返回首个「块内可能含 ≥ key 记录」的块号：最后一个首键前缀 < key
// 前缀的块的下一块——与旧锚点语义一致，重复键跨块时能落到 run 的首块。
func (s *shard) blockFor(key []byte) int {
	b := sort.Search(int(s.nBlock), func(i int) bool {
		return s.blkPfx[i] >= key8(key)
	}) - 1
	if b < 0 {
		return 0
	}
	return b
}

// seek 返回首个 key ≥ 目标 的位置 (块号, 块内下标)；超过数据末尾返回
// (nBlock, 0)。读取失败返回错误。
func (s *shard) seek(key []byte) (int, int, error) {
	for b := s.blockFor(key); b < int(s.nBlock); b++ {
		e, err := s.block(b)
		if err != nil {
			return 0, 0, err
		}
		n := s.nRecs(b)
		j := sort.Search(n, func(j int) bool {
			return bytes.Compare(e.keyAt(j), key) >= 0
		})
		if j < n {
			return b, j, nil
		}
	}
	return int(s.nBlock), 0, nil
}

// get 精确点查，命中返回 lowerBound 那条（重复键取 run 的第一条）。
func (s *shard) get(key []byte) ([]byte, bool, error) {
	for b := s.blockFor(key); b < int(s.nBlock); b++ {
		e, err := s.block(b)
		if err != nil {
			return nil, false, err
		}
		n := s.nRecs(b)
		j := sort.Search(n, func(j int) bool {
			return bytes.Compare(e.keyAt(j), key) >= 0
		})
		if j >= n {
			continue // 本块全 < key：下一块首键可能恰为 key（run 跨块）
		}
		if !bytes.Equal(e.keyAt(j), key) {
			return nil, false, nil
		}
		vo, fl, raw, packed := e.valLoc(j)
		v, err := s.value(b*int(s.recsBlk)+j, vo, fl, raw, packed)
		if err != nil {
			return nil, false, err
		}
		return v, true, nil
	}
	return nil, false, nil
}

// getPrefix 依序回调所有以 prefix 开头的键值对，fn 返回 false 提前停止。
func (s *shard) getPrefix(prefix []byte, fn func(k, v []byte) bool) error {
	b, j, err := s.seek(prefix)
	if err != nil {
		return err
	}
	for ; b < int(s.nBlock); b, j = b+1, 0 {
		e, err := s.block(b)
		if err != nil {
			return err
		}
		n := s.nRecs(b)
		for ; j < n; j++ {
			k := e.keyAt(j)
			if !bytes.HasPrefix(k, prefix) {
				return nil
			}
			vo, fl, raw, packed := e.valLoc(j)
			v, err := s.value(b*int(s.recsBlk)+j, vo, fl, raw, packed)
			if err != nil {
				return err
			}
			if !fn(k, v) {
				return nil
			}
		}
	}
	return nil
}

// scan 依序回调键在 [lo, hi) 内的记录；lo 为 nil 从头开始，hi 为 nil 到结尾。
func (s *shard) scan(lo, hi []byte, fn func(k, v []byte) bool) error {
	b, j := 0, 0
	if lo != nil {
		var err error
		b, j, err = s.seek(lo)
		if err != nil {
			return err
		}
	}
	for ; b < int(s.nBlock); b, j = b+1, 0 {
		e, err := s.block(b)
		if err != nil {
			return err
		}
		n := s.nRecs(b)
		for ; j < n; j++ {
			k := e.keyAt(j)
			if hi != nil && bytes.Compare(k, hi) >= 0 {
				return nil
			}
			vo, fl, raw, packed := e.valLoc(j)
			v, err := s.value(b*int(s.recsBlk)+j, vo, fl, raw, packed)
			if err != nil {
				return err
			}
			if !fn(k, v) {
				return nil
			}
		}
	}
	return nil
}

// packEnt 是一个已解压的打包帧：组头 [firstRec u32][n u32][lens u32×n][values]，
// pfx[i] 是第 i 个成员值在 buf 里的起点（pfx[n] = 值区终点）。
type packEnt struct {
	first uint32
	n     uint32
	pfx   []int32
	buf   []byte
}

func (p *packEnt) value(i uint32) []byte {
	return p.buf[p.pfx[i]:p.pfx[i+1]]
}

// decodePack 解一个打包帧并建组内前缀索引；帧不合法返回 error。dst 可传入
// 复用缓冲（容量够时零分配；流式路径用池，eager 路径传 nil 交给缓存持有）。
func decodePack(dec frameDecoder, frame, dst []byte) (*packEnt, error) {
	buf, err := dec.decode(frame, dst[:0])
	if err != nil {
		return nil, err
	}
	if len(buf) < 8 {
		return nil, errors.New("immkv: 打包帧头不足 8B")
	}
	p := &packEnt{first: binary.LittleEndian.Uint32(buf[0:4]), n: binary.LittleEndian.Uint32(buf[4:8])}
	if int(p.n) < 1 || len(buf) < 8+4*int(p.n) {
		return nil, errors.New("immkv: 打包帧头不合法")
	}
	p.pfx = make([]int32, p.n+1)
	// 长度表按 int 累加并逐项卡在值区内：u32 长度塞进 int32 累加会回绕，
	// 只查末项拦不住越界（如 lens=[0xffffffff,1]）。
	o := 8 + 4*int(p.n)
	for i := uint32(0); i < p.n; i++ {
		p.pfx[i] = int32(o)
		o += int(binary.LittleEndian.Uint32(buf[8+4*i:]))
		if o > len(buf) {
			return nil, fmt.Errorf("immkv: 打包帧长度表第 %d 项越过值区终点", i)
		}
	}
	p.pfx[p.n] = int32(o)
	if o != len(buf) {
		return nil, errors.New("immkv: 打包帧长度表与值区不符")
	}
	p.buf = buf
	return p, nil
}

// value 取一条记录的值：帧按 valOff 查 LRU（键取负值，与组窗口的正值键隔离；
// 零长裸存帧不入缓存——它与后一帧共享 valOff，会顶掉别人的缓存位）。打包帧
// 缓存解压后的 packEnt，单值帧缓存解压值。返回切片指向缓存里的缓冲，生命周期
// 到它被逐出为止（契约口径：到下一次查询前）。读取或解压失败返回错误。
func (s *shard) value(rec int, valOff uint64, frameLen uint32, raw, packed bool) ([]byte, error) {
	if raw && frameLen == 0 {
		return emptyValue, nil // 零长值不入缓存，直接给空切片
	}
	ck := -int64(valOff)
	if s.cache != nil {
		if v, ok := s.cache.get(ck); ok {
			if packed {
				// 缓存命中与未命中走同一成员校验：坏元数据让记录号落在帧外
				// 时返回错误，而不是越界切片 panic。
				p := v.(*packEnt)
				if uint32(rec) < p.first || uint32(rec) >= p.first+p.n {
					return nil, fmt.Errorf("immkv: 打包帧记录号 %d 不在 [%d, %d) 内", rec, p.first, p.first+p.n)
				}
				return p.value(uint32(rec) - p.first), nil
			}
			return v.([]byte), nil
		}
	}
	frame := make([]byte, frameLen)
	if _, err := s.vf.ReadAt(frame, int64(valOff)); err != nil {
		return nil, fmt.Errorf("immkv: 读值帧 (off=%d len=%d): %w", valOff, frameLen, err)
	}
	if packed {
		p, err := decodePack(s.dec, frame, nil) // 解出进 LRU 缓存，缓冲由缓存持有
		if err != nil {
			return nil, fmt.Errorf("immkv: 解压打包帧 (off=%d): %w", valOff, err)
		}
		if uint32(rec) < p.first || uint32(rec) >= p.first+p.n {
			return nil, fmt.Errorf("immkv: 打包帧记录号 %d 不在 [%d, %d) 内", rec, p.first, p.first+p.n)
		}
		if s.cache != nil {
			s.cache.add(ck, p, len(p.buf)+len(p.pfx)*4+64)
		}
		return p.value(uint32(rec) - p.first), nil
	}
	var v []byte
	if raw {
		v = frame
	} else {
		var err error
		if v, err = s.dec.decode(frame, nil); err != nil {
			return nil, fmt.Errorf("immkv: 解压值帧 (off=%d): %w", valOff, err)
		}
	}
	if s.cache != nil {
		s.cache.add(ck, v, len(v)+64)
	}
	return v, nil
}

// ---- 分染色体集合与 OpenEager ----

type shardSet struct {
	present [25]bool
	chroms  []uint8
	shards  [25]*shard
}

// openShardSet 打开 dir 下全部成对存在的 chr*.keys/chr*.vals；一个都没有
// 返回错误。cacheMB > 0 时按染色体数均分建 LRU，0 表示不缓存。
func openShardSet(dir string, cacheMB int) (*shardSet, error) {
	ss := &shardSet{}
	for id := uint8(0); id <= 24; id++ {
		base := filepath.Join(dir, "chr"+ChromName(id))
		if _, err := os.Stat(base + ".keys"); err == nil {
			ss.chroms = append(ss.chroms, id)
			ss.present[id] = true
		}
	}
	if len(ss.chroms) == 0 {
		return nil, fmt.Errorf("immkv: %s 里没有任何 chr*.keys/chr*.vals", dir)
	}
	for _, id := range ss.chroms {
		base := filepath.Join(dir, "chr"+ChromName(id))
		// 每 shard 各持一份独立 LRU：缓存键是 shard 内局部编号，
		// 共享实例会跨染色体撞键互相污染
		var cache *lruCache
		if cacheMB > 0 {
			cache = newLRU(cacheMB << 20 / len(ss.chroms))
		}
		s, err := openShard(base, cache)
		if err != nil {
			ss.close()
			return nil, err
		}
		ss.shards[id] = s
	}
	return ss, nil
}

func (ss *shardSet) close() error {
	var firstErr error
	for id := uint8(0); id < 25; id++ {
		if s := ss.shards[id]; s != nil {
			if err := s.Close(); err != nil && firstErr == nil {
				firstErr = err
			}
			ss.shards[id] = nil
		}
	}
	return firstErr
}

// DB 是 OpenEager 的分染色体路由读器；多 goroutine 并发安全。
type DB struct {
	shardSet
}

// OpenEager 打开 dir 下全部存在的染色体（chr1..chr22、chrX、chrY、chrM），
// 锚点索引即时全量载入，不预读数据。不存在的染色体视为无数据：查询路由过去
// 即未命中。cacheMB 是全局解压缓存预算（组窗口 + 值帧），0 不缓存。
// 同一目录可被任意多进程同时打开。
func OpenEager(dir string, cacheMB int) (*DB, error) {
	ss, err := openShardSet(dir, cacheMB)
	if err != nil {
		return nil, err
	}
	return &DB{shardSet: *ss}, nil
}

// Close 关闭全部 shard。调用方保证不与查询并发。
func (d *DB) Close() error { return d.close() }

// Get 精确点查。未命中返回 (nil, false, nil)；读取或解压失败返回
// (nil, false, err)。空键不命中。
func (d *DB) Get(key []byte) ([]byte, bool, error) {
	if len(key) == 0 || key[0] > 24 || !d.present[key[0]] {
		return nil, false, nil
	}
	return d.shards[key[0]].get(key)
}

// GetPrefix 前缀查询：按 prefix[0] 路由。前缀为空直接返回 nil。
// 回调返回 false 表示提前停止，不是错误；读取或解压失败返回 error。
func (d *DB) GetPrefix(prefix []byte, fn func(k, v []byte) bool) error {
	if len(prefix) == 0 {
		return nil
	}
	if prefix[0] <= 24 && d.present[prefix[0]] {
		return d.shards[prefix[0]].getPrefix(prefix, fn)
	}
	return nil
}

// Scan 区间扫描：跨染色体按 chromID 序拼接；lo/hi 可为 nil（nil = 全库扫描），
// hi 为独占上界。回调返回 false 表示提前停止，不是错误；读取或解压失败返回
// error。lo/hi 原样传给内层文件——只有命中首尾染色体的那一侧才需要设界。
func (d *DB) Scan(lo, hi []byte, fn func(k, v []byte) bool) error {
	cLo, cHi := 0, 25
	if len(lo) > 0 {
		cLo = int(lo[0])
	}
	if len(hi) > 0 {
		if int(hi[0]) < cLo {
			return nil
		}
		cHi = int(hi[0])
	}
	for c := cLo; c <= cHi && c <= 24; c++ {
		s := d.shards[c]
		if s == nil {
			continue
		}
		var l, h []byte
		if len(lo) > 0 && c == cLo {
			l = lo
		}
		if len(hi) > 0 && c == cHi {
			h = hi
		}
		stop := false
		if err := s.scan(l, h, func(k, v []byte) bool {
			if !fn(k, v) {
				stop = true
				return false
			}
			return true
		}); err != nil {
			return err
		}
		if stop {
			return nil
		}
	}
	return nil
}

files.simple.go:
// simple.go 是 immkv 的单库精确点查句柄：直接打开一对 .keys/.vals，
// 不做染色体分片与首字节路由。适用于无染色体/坐标的普通 KV，
// 例如 gene symbol -> 字符串；查询面只有 Get。

package immkv

import (
	"encoding/binary"
	"fmt"
)

// SimpleKVDB 是单库精确点查句柄：打开 basePath.keys / basePath.vals 这一对
// 文件，键可以是任意字节串。多 goroutine 并发安全；返回切片只保证到下一次
// 查询前有效。
type SimpleKVDB struct {
	s *shard
}

// OpenSimpleKV 打开 basePath.keys 与 basePath.vals 这一对文件。cacheMB 是
// 解压缓存预算（MB），0 表示不缓存。与 OpenEager 不同，它不做染色体分片，
// 也不按首字节路由。
func OpenSimpleKV(basePath string, cacheMB int) (*SimpleKVDB, error) {
	var cache *lruCache
	if cacheMB > 0 {
		cache = newLRU(cacheMB << 20)
	}
	s, err := openShard(basePath, cache)
	if err != nil {
		return nil, err
	}
	return &SimpleKVDB{s: s}, nil
}

// Get 精确点查；未命中返回 (nil, false, nil)，读取、解压或 record 形状不符
// 返回 (nil, false, err)。重复键返回排序后的第一条。库里的值是单 String
// 字段 record，这里解包后返回原始值字节。
func (d *SimpleKVDB) Get(key []byte) ([]byte, bool, error) {
	raw, ok, err := d.s.get(key)
	if err != nil || !ok {
		return nil, ok, err
	}
	return decodeSimpleValue(raw)
}

// decodeSimpleValue 解空 schema 库的 record：8B bitmap（只允许 bit0）
// + uvarint(len) + 原字节。record 形状不符时返回错误。
func decodeSimpleValue(raw []byte) ([]byte, bool, error) {
	if len(raw) < 8 {
		return nil, false, fmt.Errorf("immkv: 简单库 record 长度 %d < 8", len(raw))
	}
	if binary.LittleEndian.Uint64(raw[:8]) != 1 {
		return nil, false, fmt.Errorf("immkv: 简单库 record 位图不是单 String 字段")
	}
	length, n := binary.Uvarint(raw[8:])
	if n <= 0 {
		return nil, false, fmt.Errorf("immkv: 简单库 record 长度字段无效")
	}
	start := 8 + n
	if length != uint64(len(raw)-start) {
		return nil, false, fmt.Errorf("immkv: 简单库 record 长度 %d ≠ 剩余 %d", length, len(raw)-start)
	}
	return raw[start:], true, nil
}

// Close 关闭文件句柄与解码器。调用方保证不与查询并发。
func (d *SimpleKVDB) Close() error { return d.s.Close() }

files.stream.go:
// stream.go 是 immkv 的读侧之二：OpenStreaming 批量流式句柄。
//
// GetBatch 对一段升序键做两阶段查询：阶段一对每条染色体的键流做合并连接
// （顺扫键流窗口，光标只前进），收齐全部命中的值帧 (偏移, 长度, 裸存标记)；
// 阶段二把相邻命中合并成读段，Threads 路并行 pread + 解压回填结果。
// 磁盘读取因此是字节精确的：只读命中的值帧与扫过的键流，无缺页放大。

package immkv

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"sync"
)

const (
	streamWindow = 256 << 10 // 键流窗口目标字节数（一次 pread 覆盖若干组）
	mergeGap     = 4 << 10   // 值帧相邻合并的间隔阈值：间隔 ≤ 它并入同一读段；gnomAD 命中值平均间隔 ~114KB，阈值大了会顺读值文件（实测 256KB 时每轮多读 200GB）
	maxExtent    = 4 << 20   // 单个读段的上限，控制缓冲与单次 pread 尺寸
)

// ErrUnsorted 表示 GetBatch 的输入键不升序。
var ErrUnsorted = errors.New("immkv: GetBatch keys not ascending")

// StreamDB 是批量流式句柄：GetBatch / Close。方法面刻意只有这两个——
// 单条查询开 OpenEager；同一库可同时开两种句柄（只读无冲突）。
type StreamDB struct {
	shardSet
	threads int
	cols    [25]*colShard
	colSel  []int  // 选中的列号（升序）；nil = 全部
	selMask []bool // colSel 对应的位图；nil = 全部
	profile ioProfile

	forceCol bool // 测试用：跳过成本估算，强制列存路径
}

// OpenStreaming 打开 dir 下的批量流式句柄。StreamOptions.Threads 是唯一并发
// 旋钮：同时决定在途 pread 请求数与并行解压 goroutine 数（默认 1）；机械
// 硬盘上它不起作用（单磁头，引擎靠相邻合并转顺序读）。
//
// 库里有 base.col/manifest 时，顺序查按估算的 I/O 成本在记录序与列存之间
// 选路；StreamOptions.Columns 只选字段（nil/空 = 全部列），不决定路径；
// 两条路径返回的 record 都只含选中字段。直接由 Create 建、没有
// base.col/manifest 的库仍按记录序服务；此时给非空 Columns 会报错。
func OpenStreaming(dir string, opts StreamOptions) (*StreamDB, error) {
	if opts.Threads <= 0 {
		opts.Threads = 1
	}
	ss, err := openShardSet(dir, 0)
	if err != nil {
		return nil, err
	}
	d := &StreamDB{shardSet: *ss, threads: opts.Threads, profile: detectIOProfile(dir)}
	anyCol, allCol := false, true
	var buildID string
	for _, id := range d.chroms {
		cs, err := openColShard(filepath.Join(dir, "chr"+ChromName(id)), d.shards[id])
		if err != nil {
			d.Close()
			return nil, err
		}
		d.cols[id] = cs
		if cs == nil {
			allCol = false
			continue
		}
		anyCol = true
		if buildID == "" {
			buildID = cs.buildID
		} else if buildID != cs.buildID {
			d.Close()
			return nil, errors.New("immkv: 各染色体的 base.col build id 不一致")
		}
		if len(d.chroms) > 0 && d.cols[d.chroms[0]] != nil &&
			!sameColSchema(d.cols[d.chroms[0]].schema, cs.schema) {
			d.Close()
			return nil, errors.New("immkv: 各染色体的 base.col schema 不一致")
		}
	}
	if anyCol && !allCol {
		d.Close()
		return nil, errors.New("immkv: 部分染色体缺少 base.col/manifest")
	}
	if len(opts.Columns) > 0 {
		if !anyCol {
			d.Close()
			return nil, errors.New("immkv: 库没有 base.col/manifest，不能按列选择")
		}
		seen := make(map[int]bool, len(opts.Columns))
		sel := make([]int, 0, len(opts.Columns))
		for _, c := range opts.Columns {
			if c < 0 || c >= len(d.cols[d.chroms[0]].schema) {
				d.Close()
				return nil, fmt.Errorf("immkv: Columns 列号 %d 越界", c)
			}
			if seen[c] {
				d.Close()
				return nil, fmt.Errorf("immkv: Columns 列号 %d 重复", c)
			}
			seen[c] = true
			sel = append(sel, c)
		}
		sort.Ints(sel)
		d.colSel = sel
		d.selMask = make([]bool, len(d.cols[d.chroms[0]].schema))
		for _, c := range sel {
			d.selMask[c] = true
		}
	}
	return d, nil
}

// Close 关闭全部 shard。调用方保证不与查询并发。
func (d *StreamDB) Close() error {
	for id := uint8(0); id < 25; id++ {
		if c := d.cols[id]; c != nil {
			c.Close()
			d.cols[id] = nil
		}
	}
	return d.close()
}

// directOK 报全部在场染色体的值文件都开出了 O_DIRECT 句柄（深队列读路径
// 的前提；任一失败就整体退回缓冲读，避免同一批里混两种路径）。
func (d *StreamDB) directOK() bool {
	for _, id := range d.chroms {
		if d.shards[id].vfDirect == nil {
			return false
		}
	}
	return len(d.chroms) > 0
}

// GetBatch 批量点查。keys 必须升序（字节序；VCF 按染色体自然序 + 位置排序
// 即天然满足），返回切片与 keys 等长同序，某项未命中为 nil。返回切片只保证
// 到下一次查询前有效，要保留自己拷。任何 I/O 或解压错误整批返回 error。
// 并发安全：句柄可被多个 goroutine 同时调用（每次调用状态独立）。
func (d *StreamDB) GetBatch(keys [][]byte) ([][]byte, error) {
	if len(keys) == 0 {
		return [][]byte{}, nil
	}
	for i := 1; i < len(keys); i++ {
		if bytes.Compare(keys[i-1], keys[i]) > 0 {
			return nil, ErrUnsorted
		}
	}
	out := make([][]byte, len(keys))
	// 三级流水线：生产者（本 goroutine，合并连接顺扫键流）→ 读池（Threads 路
	// 在途读）→ 解压池（Threads 路，CPU 由 GOMAXPROCS 兜底）。读与解压分池
	// 解耦，磁盘等待不占解压的 CPU 时间。
	var (
		extCh  = make(chan []extent, 4) // 生产者 → 读池
		decCh  = make(chan []extent, 8) // 读池 → 解压池
		abort  = make(chan struct{})
		wgRead sync.WaitGroup
		wgDec  sync.WaitGroup
		errMu  sync.Mutex
		ferr   error
	)
	fail := func(err error) {
		errMu.Lock()
		defer errMu.Unlock()
		if ferr == nil {
			ferr = err
			close(abort)
		}
	}
	failed := func() bool {
		errMu.Lock()
		defer errMu.Unlock()
		return ferr != nil
	}
	wgDec.Add(d.threads)
	if r, rerr := newIOUring(512); rerr == nil && d.directOK() {
		// O_DIRECT + io_uring：单驱动 goroutine 深队列异步读（绕开页缓存，
		// 在途读深度与线程数解耦；线程预算全部留给解压池）
		defer r.close()
		wgRead.Add(1)
		go func() {
			defer wgRead.Done()
			driveDirect(r, extCh, decCh, abort, fail)
		}()
	} else {
		wgRead.Add(d.threads)
		for w := 0; w < d.threads; w++ {
			go func() { // 读池（io_uring 或 O_DIRECT 不可用时的兜底）
				defer wgRead.Done()
				for {
					select {
					case ch, ok := <-extCh:
						if !ok {
							return
						}
						if err := readChunk(ch); err != nil {
							fail(err)
							return
						}
						select {
						case decCh <- ch:
						case <-abort:
							return
						}
					case <-abort:
						return
					}
				}
			}()
		}
	}
	for w := 0; w < d.threads; w++ {
		go func() { // 解压池
			defer wgDec.Done()
			for {
				select {
				case ch, ok := <-decCh:
					if !ok {
						return
					}
					if err := decodeChunk(ch, out); err != nil {
						fail(err)
						return
					}
				case <-abort:
					return
				}
			}
		}()
	}
	// 生产者：按染色体分段（键升序 ⇒ 同染色体键连续）合并连接、切读段投递
	type recSpan struct{ start, end int }
	var recSpans []recSpan
	i := 0
	for i < len(keys) && !failed() {
		if len(keys[i]) == 0 { // 空键排最前，直接未命中
			i++
			continue
		}
		id := keys[i][0]
		j := i + 1
		for j < len(keys) && len(keys[j]) > 0 && keys[j][0] == id {
			j++
		}
		if id <= 24 && d.present[id] {
			hits, err := mergeJoin(d.shards[id], keys[i:j], i)
			if err != nil {
				fail(err)
				break
			}
			if cs := d.cols[id]; cs != nil {
				useCol, cerr := d.preferColumnar(cs, d.shards[id], hits)
				if cerr != nil {
					fail(cerr)
					break
				}
				if useCol {
					if cerr := cs.readColBatch(hits, selectedColumns(cs.schema, d.colSel), out, d.threads); cerr != nil {
						fail(cerr)
						break
					}
					i = j
					continue
				}
			}
			recSpans = append(recSpans, recSpan{i, j})
			for _, ch := range chunkExtents(buildExtents(d.shards[id], hits)) {
				select {
				case extCh <- ch:
				case <-abort:
				}
				if failed() {
					break
				}
			}
		}
		i = j
	}
	// 统一收尾：关 extCh → 等读池 → 关 decCh → 等解压池，全部落定后判错——
	// 解压池的错误可能在生产者跑完之后才出现，提前判错会把它丢掉
	close(extCh)
	wgRead.Wait()
	close(decCh)
	wgDec.Wait()
	// 记录序路径按 Columns 裁剪，与列存路径返回同形状的 record；列存路径
	// 已在 readColBatch 里按同一列选择装配。
	if ferr == nil && len(d.selMask) > 0 {
		schema := d.cols[d.chroms[0]].schema
		for _, sp := range recSpans {
			for k := sp.start; k < sp.end; k++ {
				if out[k] == nil {
					continue
				}
				projected, perr := projectRecord(schema, out[k], d.selMask)
				if perr != nil {
					return nil, perr
				}
				out[k] = projected
			}
		}
	}
	if ferr != nil {
		return nil, ferr
	}
	return out, nil
}

// costs 返回读路的粗略成本参数：单次随机读耗时（秒）与顺序带宽（B/s）。
// 数值取自 2026-11-09/10 的 HDD/NVMe 实测量级，只用于二选一，不参与计时。
func (p ioProfile) costs() (randSec, seqBps float64) {
	if p.rotational {
		return 0.45e-3, 170e6
	}
	return 10e-6, 3e9
}

// preferColumnar 估算记录序（命中帧随机读）与列存（命中 bin 的选中列顺序
// 读）谁更省，返回是否走列存。hits 按记录号升序。
func (d *StreamDB) preferColumnar(cs *colShard, s *shard, hits []sHit) (bool, error) {
	if len(hits) == 0 {
		return false, nil
	}
	// 实验开关：显式对比两条路，不改变默认选路。
	if os.Getenv("IMMKV_FORCE_RECORD") != "" {
		return false, nil
	}
	if os.Getenv("IMMKV_FORCE_COLUMNAR") != "" {
		return true, nil
	}
	if d.forceCol {
		return true, nil
	}
	sel := selectedColumns(cs.schema, d.colSel)
	colBytes, colRaw, err := cs.estimate(hits, sel)
	if err != nil {
		return false, err
	}
	// 记录序的实际读形状由 readExtents 的合并规则决定：稠密命中会并成大段
	// 顺序读，只有稀疏命中才按帧计随机读。
	extents := buildExtents(s, hits)
	var seqBytes uint64
	var frames int
	var recBytes uint64
	var lastOff uint64
	var lastLen uint32
	have := false
	for _, h := range hits {
		if h.frameLen == 0 {
			continue
		}
		if have && h.valOff == lastOff && h.frameLen == lastLen {
			continue
		}
		have, lastOff, lastLen = true, h.valOff, h.frameLen
		frames++
		recBytes += uint64(h.frameLen)
	}
	for i := range extents {
		last := extents[i].hits[len(extents[i].hits)-1]
		seqBytes += last.valOff + uint64(last.frameLen) - extents[i].off
	}
	randSec, seqBps := d.profile.costs()
	workers := float64(d.threads)
	if workers < 1 {
		workers = 1
	}
	// 2026-11-12 chr22 实测标定（NVMe，4 线程，568 列）：
	//   - 记录序整条染色体 11.1s，解压后 record 12.1GB，约 270MB/s/线程；
	//   - 列存整条染色体 67.3s，payload 11.9GB，约 44MB/s/线程。
	// 记录序按命中帧解压（帧内还可打包多条记录）；列存还含位图与装配。
	const recordDecodePerThread = 2.5e8
	const colDecodePerThread = 4.5e7
	const typedRecCompressionRatio = 4.3
	decodeBps := colDecodePerThread * workers
	recRaw := float64(recBytes) * typedRecCompressionRatio
	recSec := float64(len(extents))*randSec + float64(seqBytes)/seqBps + recRaw/(recordDecodePerThread*workers)
	colSec := float64(colBytes)/seqBps + float64(colRaw)/decodeBps
	if os.Getenv("IMMKV_DEBUG_PATH") != "" {
		fmt.Fprintf(os.Stderr, "path: pick=%v colBytes=%d colRaw=%d colSec=%.3f recExtents=%d recFrames=%d recBytes=%d recSec=%.3f rot=%v\n",
			colSec < recSec, colBytes, colRaw, colSec, len(extents), frames, recBytes, recSec, d.profile.rotational)
	}
	return colSec < recSec, nil
}

// emptyValue 是零长值的共享只读空切片（长度 0 无从写入，共享安全）。
var emptyValue = []byte{}

// sHit 是一条命中：值帧在 vals 文件里的位置 + 该键在整批里的回填下标；
// rec 是该记录在本染色体内的全局记录号（打包帧换算组内下标用）。
type sHit struct {
	valOff   uint64
	frameLen uint32
	raw      bool
	packed   bool
	rec      int64
	dst      int
}

// mergeJoin 对一段升序键做合并连接。键流按微块（64 条/块）顺扫：窗口一次
// 读入若干块（凑满 streamWindow 或到键流尾），块解析为零分配视图（数组是
// 窗口缓冲的子切片）；光标 (块号, 块内下标, 该下标的 valOff) 跨查询保持、
// 只前进；块内定位用二分（log₂64 = 6 次比较），命中时从光标累加推导 valOff
// （≤64 步）。返回的命中按值偏移升序（记录按 key 序、帧按记录序落盘）。
func mergeJoin(s *shard, keys [][]byte, base int) ([]sHit, error) {
	if s.nBlock == 0 || len(keys) == 0 {
		return nil, nil
	}
	var hits []sHit
	b := s.blockFor(keys[0])
	j := 0            // 块内下一待看下标
	jOff := uint64(0) // 第 j 条记录的 valOff（块内推导的运行值）
	var (
		blocks []blockView
		winB0  = -1
		winB1  = 0
	)
	loadWin := func(from int) error {
		b1 := from + 1
		for b1 < int(s.nBlock) && s.blkOff[b1]-s.blkOff[from] < streamWindow {
			b1++
		}
		hi := s.keysEnd
		if b1 < int(s.nBlock) {
			hi = s.blkOff[b1]
		}
		buf := make([]byte, hi-s.blkOff[from])
		if _, err := s.kf.ReadAt(buf, int64(s.blkOff[from])); err != nil {
			return err
		}
		blocks = blocks[:0]
		p := 0
		for bb := from; bb < b1; bb++ {
			v, used, err := parseBlockView(buf[p:], s.nRecs(bb))
			if err != nil {
				return err
			}
			blocks = append(blocks, v)
			p += used
		}
		winB0, winB1 = from, b1
		return nil
	}
	for ki := 0; ki < len(keys); ki++ {
		q := keys[ki]
		for {
			if b >= int(s.nBlock) {
				break // 数据扫完，剩余键全部未命中
			}
			if b >= winB1 {
				if err := loadWin(b); err != nil {
					return nil, err
				}
				j, jOff = 0, blocks[0].base
			}
			v := &blocks[b-winB0]
			if j == 0 {
				jOff = v.base
			}
			if j >= v.n {
				b++
				j = 0
				continue
			}
			jj := j + sort.Search(v.n-j, func(t int) bool {
				return bytes.Compare(v.keyAt(j+t), q) >= 0
			})
			if jj >= v.n {
				b++
				j = 0
				continue
			}
			c := bytes.Compare(v.keyAt(jj), q)
			if c > 0 {
				// 记录键 > 查询键：未命中，光标停在当前记录（先推偏移再挪下标）
				jOff = v.valOffAt(j, jj, jOff)
				j = jj
				break
			}
			// 命中：valOff 从光标累加推导
			vo := v.valOffAt(j, jj, jOff)
			l := v.lens[jj]
			hits = append(hits, sHit{
				valOff: vo, frameLen: l & frameLenMask,
				raw: l&flagRaw != 0, packed: l&flagPacked != 0,
				rec: int64(b)*int64(s.recsBlk) + int64(jj), dst: base + ki,
			})
			// 下一个输入键与此键相等时光标停在当前记录上，让同一记录
			// 再服务一次（批量点查对每个输入独立）
			nextOff := v.valOffAt(j, jj+1, jOff)
			j = jj + 1
			jOff = nextOff
			if ki+1 < len(keys) && bytes.Equal(keys[ki+1], q) {
				j = jj
				jOff = vo
			}
			break
		}
	}
	return hits, nil
}

// extent 是一次 pread 的读段：从 off 起读到段内最后一条命中的帧尾。
type extent struct {
	s      *shard
	off    uint64
	hits   []sHit // 段内命中，值偏移升序
	buf    []byte // 命中帧字节视图（O_DIRECT 路径是 dbuf 的子切片）
	dbuf   []byte // 读入缓冲本体（对齐或普通），解压完归还池；raw/单值段被 out 引用不还
	size   uint64 // 段的盘上字节数（readChunk / driveDirect 填）
	dNeed  int32  // dbuf 内需要覆盖到的字节数（O_DIRECT 对齐读可能越过文件尾，EOF 短读合法）
	direct bool   // dbuf 走对齐缓冲池（driveDirect 填；归还各回各池）
}

// buildExtents 把命中按相邻合并成读段：间隔 ≤ mergeGap 且段长 ≤ maxExtent
// 时并入，否则另起一段。稀疏位点在值文件里的平均间隔 ~160KB（gnomAD 全量库
// 实测口径），合并后每次 syscall 取回数条帧。
func buildExtents(s *shard, hits []sHit) []extent {
	var exts []extent
	for i := 0; i < len(hits); {
		j := i
		last := hits[i].valOff + uint64(hits[i].frameLen)
		for j+1 < len(hits) {
			h := hits[j+1]
			end := h.valOff + uint64(h.frameLen)
			// 同帧成员（含零长裸存帧）的 valOff 不大于 last，间隔按 0 计；
			// 直接相减会无符号下溢成巨值，把段无谓打碎
			var gap int64
			if h.valOff > last {
				gap = int64(h.valOff - last)
			}
			if gap > mergeGap || end-hits[i].valOff > maxExtent {
				break
			}
			last = end
			j++
		}
		exts = append(exts, extent{s: s, off: hits[i].valOff, hits: hits[i : j+1]})
		i = j + 1
	}
	return exts
}

// readChunk 把一块读段全部读入（每 reader 一路在途读，threads 个 reader 即
// StreamOptions.Threads 路并发读），读完对该块覆盖的文件区间做 fadvise(DONTNEED)
// ——值只读一次，页缓存留着只会顶爆 cgroup 限额、拖慢后续读。
func readChunk(chunk []extent) error {
	for i := range chunk {
		e := &chunk[i]
		last := e.hits[len(e.hits)-1]
		e.size = last.valOff + uint64(last.frameLen) - e.off
		e.buf = getExtentBuf(int(e.size))
		e.dbuf = e.buf
		if _, err := e.s.vf.ReadAt(e.buf, int64(e.off)); err != nil {
			return err
		}
	}
	first, lastE := chunk[0], chunk[len(chunk)-1]
	fadviseDontNeed(first.s.vf, int64(first.off), int64(lastE.off+lastE.size-first.off))
	return nil
}

// decodeChunk 解一块读段并回填。打包帧解出的成员值拷进本块 slab——结果自
// 包含、段读缓冲可即时回收复用，全量注释一轮的分配量从「每命中一整帧」降到
// 「每命中一个值」。
func decodeChunk(chunk []extent, out [][]byte) error {
	slab := make([]byte, 0, 1<<16)
	for i := range chunk {
		var err error
		if slab, err = decodeExtent(&chunk[i], out, slab); err != nil {
			return err
		}
	}
	return nil
}

// decodeExtent 解一个读段并回填：raw 帧零拷（out 引用 buf，本块内该段缓冲
// 不回收）；单值 zstd 帧整帧解压成新缓冲；打包帧整帧解压后把成员值拷进
// slab，段缓冲随后回收。返回推进后的 slab。
func decodeExtent(e *extent, out [][]byte, slab []byte) ([]byte, error) {
	reusable := true
	defer func() {
		if reusable {
			if e.direct {
				putDirectBuf(e.dbuf)
			} else {
				putExtentBuf(e.dbuf)
			}
			e.buf, e.dbuf = nil, nil
		}
	}()
	for i := 0; i < len(e.hits); {
		j := i
		h := e.hits[i]
		// 只把同一打包帧的成员并成组（valOff、frameLen、packed 三者全同）；
		// 零长裸存帧与共址的下一帧不能并——它不是那帧的成员
		for j+1 < len(e.hits) &&
			e.hits[j+1].valOff == h.valOff &&
			e.hits[j+1].frameLen == h.frameLen &&
			h.packed && e.hits[j+1].packed {
			j++
		}
		frame := e.buf[h.valOff-e.off : h.valOff-e.off+uint64(h.frameLen)]
		switch {
		case h.raw:
			if h.frameLen == 0 {
				out[h.dst] = emptyValue // 零长值：非 nil 空切片（nil 会被当成未命中）
				i = j + 1
				continue
			}
			out[h.dst] = frame
			reusable = false // out 引用 buf，本调用结束前不能复用
		case h.packed:
			p, err := decodePack(e.s.dec, frame, getExtentBuf(64<<10))
			if err != nil {
				return slab, err
			}
			for k := i; k <= j; k++ {
				hk := e.hits[k]
				idx := hk.rec - int64(p.first)
				if idx < 0 || idx >= int64(p.n) {
					return slab, fmt.Errorf("immkv: 打包帧记录号 %d 不在 [%d, %d) 内", hk.rec, p.first, p.first+p.n)
				}
				v := p.value(uint32(idx))
				t := len(slab)
				slab = append(slab, v...)
				out[hk.dst] = slab[t:]
			}
			putExtentBuf(p.buf) // 成员值已拷进 slab，解码缓冲即可复用
		default:
			v, err := e.s.dec.decode(frame, nil)
			if err != nil {
				return slab, err
			}
			out[h.dst] = v
			reusable = false // 解出的整帧缓冲由 out 引用，交 GC
		}
		i = j + 1
	}
	return slab, nil
}

// extentBufPool 复用段读缓冲。按尺寸分桶避免大段把池撑爆：≤64KB（gnomAD
// 段主流尺寸）走池，更大的现配。
var extentBufPools = [2]sync.Pool{}

func getExtentBuf(n int) []byte {
	if n <= 16<<10 {
		if bp := extentBufPools[0].Get(); bp != nil {
			return (*bp.(*[]byte))[:n]
		}
		b := make([]byte, 16<<10)
		return b[:n]
	}
	if n <= 64<<10 {
		if bp := extentBufPools[1].Get(); bp != nil {
			return (*bp.(*[]byte))[:n]
		}
		b := make([]byte, 64<<10)
		return b[:n]
	}
	return make([]byte, n)
}

func putExtentBuf(b []byte) {
	switch {
	case cap(b) <= 16<<10:
		extentBufPools[0].Put(&b)
	case cap(b) <= 64<<10:
		extentBufPools[1].Put(&b)
	}
}

// chunkExtents 把一条染色体的读段切成投递块：≤64 段一块。
func chunkExtents(exts []extent) [][]extent {
	if len(exts) == 0 {
		return nil
	}
	const n = 64
	var chunks [][]extent
	for i := 0; i < len(exts); i += n {
		j := i + n
		if j > len(exts) {
			j = len(exts)
		}
		chunks = append(chunks, exts[i:j])
	}
	return chunks
}

